INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a89168b2-b90b-57f3-ab0d-d691c368d8a3', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'dc9bb2b5-5e35-50ac-afaf-4717d4fb0aec', 10, 27, 'እርሱ ግን “በሰው ዘንድ የማይቻለው በእግዚአብሔር ዘንድ ይቻላል” አላቸው።'),
  ('288ee679-9c25-5d16-a697-bda861016e9c', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '1477e80f-445c-592e-a1bf-40b70a676caf', 1, 28, 'ጴጥሮስም፥ “እነሆ፥ እኛ ሁሉን ትተን ተከትለንሃል፤ እንግዲህ ምን እናገኛለን?” አለው።'),
  ('9a6b4114-07c2-5af5-a65f-80409fb000b6', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '1477e80f-445c-592e-a1bf-40b70a676caf', 2, 29, 'እርሱም እንዲህ አላቸው፥ “እውነት እላችኋለሁ፥ ቤቱንና ዘመዶቹን፥ ወንድሞቹንና ሚስቱን፥ ልጆቹንም ስለ እግዚአብሔር መንግሥት የሚተው፥'),
  ('097acab6-867d-5265-abea-d909698e82af', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', '1477e80f-445c-592e-a1bf-40b70a676caf', 3, 30, 'በዚህ ዓለም መቶ እጥፍ ዋጋ፥ በሚመጣውም ዓለም የዘለዓለም ሕይወትን የማይቀበል ማንም የለም።”'),
  ('a3b5cf10-7c3c-5a67-aa21-d67777a31727', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'f67d1a32-6369-5f94-a2d7-d5ee665a2b59', 1, 31, 'ዐሥራ ሁለቱንም ወሰዳቸው፤ እንዲህም አላቸው፥ “እነሆ፥ ወደ ኢየሩሳሌም እንወጣለን፤ በነቢያትም የተጻፈው ሁሉ በሰው ልጅ ላይ ይፈጸማል።'),
  ('09304a4b-10bd-5fd5-a7cf-713c61a271f8', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'f67d1a32-6369-5f94-a2d7-d5ee665a2b59', 2, 32, 'ለአሕዛብ አሳልፈው ይሰጡታል፤ ይዘብቱበታልም፤ ይሰድቡታልም፤ ይተፉበታልም።'),
  ('24e4620b-405f-5972-ab91-57d412760653', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'f67d1a32-6369-5f94-a2d7-d5ee665a2b59', 3, 33, 'ይገርፉታል፤ ይገድሉታልም፤ በሦስተኛዪቱም ቀን ይነሣል።”'),
  ('782e078a-397f-5a47-aa8a-6ae5cf309f31', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'f67d1a32-6369-5f94-a2d7-d5ee665a2b59', 4, 34, 'እነርሱ ግን፤ ከተናገራቸው ያስተዋሉት የለም፤ ይህ ነገር ከእነርሱ የተሰወረ ነበርና፤ የተናገረውንም አያውቁም ነበርና።'),
  ('b854e2ba-c715-5195-a185-2f6b7a284ee1', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 1, 35, 'ከዚህም በኋላ ኢያሪኮ በደረሱ ጊዜ አንድ ዕውር በጎዳና ተቀምጦ ይለምን ነበር።'),
  ('4a5ebbde-c24d-5fe6-a0bb-67d2e34318e6', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 2, 36, 'የሚያልፈውንም ሰው ድምፅ ሰምቶ፥ “ይህ የምሰማው ምንድን ነው?” አለ።'),
  ('57f87b4f-db95-5e8f-a758-c914eec8669b', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 3, 37, 'እነርሱም፥ “የናዝሬቱ ኢየሱስ ያልፋል” ብለው ነገሩት።'),
  ('3aaadebc-c858-568f-a057-07bcb9404b81', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 4, 38, 'ድምፁንም ከፍ አድርጎ፥ “የዳዊት ልጅ ኢየሱስ ሆይ፥ ማረኝ” አለ።'),
  ('b39390b8-7d99-572d-a109-74dbc56b29f7', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 5, 39, 'የሚመሩትም ዝም እንዲል ገሠጹት፤ እርሱ ግን በጣም ጮኾ፥ “የዳዊት ልጅ ሆይ፥ ማረኝ” አለ።'),
  ('1e4bfdfd-19ce-5c02-a88a-57e917a4070b', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 6, 40, 'ጌታችን ኢየሱስም ቆመና ወደ እርሱ እንዲያመጡት አዘዘ።'),
  ('2e9f64d6-f9b7-5ba4-ae1a-21e7724d6fc0', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 7, 41, 'ወደ እርሱም በደረሰ ጊዜ፥ “ምን ላደርግልህ ትወዳለህ?” ብሎ ጠየቀው፤ እርሱም፥ “ጌታ ሆይ፥ ዐይኖች እንዲያዩ ነው” አለው።'),
  ('aa7e30e7-06a3-501f-a5b5-52449ff4dadf', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 8, 42, 'ጌታችን ኢየሱስም፥ “እይ፤ እምነትህ አዳነችህ” አለው።'),
  ('40a49e43-1e98-59bc-a577-fd2fcba0495f', '0ab06477-3a91-5b2b-a6fa-0cd1065dcaa4', 'bcd681a6-3db5-5272-a1d9-77ee38465946', 9, 43, 'በዚያን ጊዜም አየ፤ እግዚአብሔርንም አመሰገነ፤ ተከተለውም፤ ሕዝቡም ሁሉ አይተው እግዚአብሔርን አመሰገኑት።'),
  ('a3f88e55-b77c-5d77-a518-59ce645bff2a', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 1, 1, 'ጌታችን ኢየሱስም ወደ ኢያሪኮ ገብቶ በዚያ ያልፍ ነበር።'),
  ('58786df6-57e5-5783-a8dc-47c1c73c9b50', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 2, 2, 'እነሆ፥ የቀራጮች አለቃ ስሙ ዘኬዎስ የተባለ አንድ ሰው ነበር፤ እርሱም ባለጸጋ ነበር።'),
  ('1a42e42b-18a9-5c2e-a891-7744dfc8d811', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 3, 3, 'ጌታችን ኢየሱስንም ያየው ዘንድ፥ ማን እንደ ሆነም ያውቅ ዘንድ ይሻ ነበር፤ የሰው ብዛትም ይከለክለው ነበር፤ ቁመቱ አጭር ነበርና።'),
  ('46b6f795-77e6-5d62-a985-b59863a94e24', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 4, 4, 'ወደ ፊቱም ሮጠ፤ ያየው ዘንድም በሾላ ላይ ወጣ፤ በዚያች መንገድ ያልፍ ዘንድ አለውና።'),
  ('4eef7d42-c1f9-5617-a281-7051647f486c', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 5, 5, 'ጌታችን ኢየሱስም ወደዚያ በደረሰ ጊዜ አሻቅቦ አየውና፥ “ዘኬዎስ ሆይ፥ ፈጥነህ ውረድ፤ ዛሬ በቤትህ እውል ዘንድ አለኝና” አለው።'),
  ('c0a40a44-c6f6-5d88-a489-01cf9dc7d75f', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 6, 6, 'ፈጥኖም ወረደ፤ ደስ እያለውም ወደ ቤቱ ይዞት ገባ።'),
  ('81f3803f-cc14-52af-ae3a-8c2c1815e424', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 7, 7, 'ሁሉም አይተው “ወደ ኀጢኣተኛ ሰው ቤት ሊውል ገባ” ብለው አንጐራጐሩ።'),
  ('7538dcd8-8d8c-5b8c-a7ad-907c30a59369', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 8, 8, 'ዘኬዎስም ቆመና ጌታችንን እንዲህ አለው፥ “ጌታዬ ሆይ፥ አሁን የገንዘቤን እኩሌታ ለነዳያን እሰጣለሁ፤ የበደልሁትም ቢኖር ስለ አንድ ፋንታ አራት እጥፍ እከፍለዋለሁ።”'),
  ('b8ee3728-a9c3-581b-a681-7ff602a4c767', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 9, 9, 'ጌታችን ኢየሱስም እንዲህ አለው፥ “ዛሬ ለዚህ ቤት ሕይወት ሆነ፤ እርሱ የአብርሃም ልጅ ነውና።'),
  ('43c7b309-df76-5334-a4cb-406376d4905c', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '7eb86709-a1df-5b48-addc-92500dcc2ec9', 10, 10, 'የሰው ልጅ የጠፋውን ሊፈልግና ሊያድን መጥቶአልና።”'),
  ('78ab977f-721a-5375-ada5-8c9fd5f3cac3', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 1, 11, 'ይህንም ሲሰሙ፤ ምሳሌ መስሎ ነገራቸው፤ ወደ ኢየሩሳሌም ቀርቦ ነበርና፤ እነርሱም የእግዚአብሔር መንግሥት ወዲያውኑ የምትገለጥ መስሎአቸው ነበርና።'),
  ('43c61251-845a-5f8b-ad40-c16bd5be05ac', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 2, 12, 'እንዲህም አለ፥ “አንድ የከበረ ሰው መንግሥት ይዞ ሊመለስ ወደ ሩቅ ሀገር ሄደ።'),
  ('2ae85b35-d13f-5ac1-afec-9d2070855d7c', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 3, 13, 'ዐሥሩን አገልጋዮቹንም ጠርቶ ዐሥር ምናን ሰጣቸውና፦ እንግዲህ እስክመለስ ድረስ ነግዱ አላቸው።'),
  ('c6b4c8e0-6a90-58d1-adea-78093d2533d7', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 4, 14, 'የሀገሩ ሰዎች ግን ይጠሉት ነበርና፥ ይህ በእኛ ላይ ሊነግሥ አንሻም ብለው አከታትለው መልእክተኞችን ላኩ።'),
  ('bde80f08-923a-5f51-a79a-2f51ed7f3680', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 5, 15, 'ከዚህም በኋላ፤ መንግሥትን ይዞ በተመለሰ ጊዜ እንደ አተረፉ ያውቅ ዘንድ ምናን የሰጣቸውን ብላቴኖቹን እንዲያመጡአቸው አዘዘ።'),
  ('3e25673a-f9a7-5220-a754-2f7322fd3a12', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 6, 16, 'አንደኛውም መጥቶ፦ አቤቱ፥ ምናንህ ዐሥር ነበር፤ እነሆ ዐሥር ምናን አትርፌአለሁ አለው።'),
  ('10131d49-e98a-52a4-a5bd-02870a367676', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 7, 17, 'ጌታውም፦ መልካም፥ አንተ በጎ አገልጋይ በጥቂት የታመንህ ስለሆንህ በብዙ ላይ እሾምሃለሁ፤ በዐሥሩ ከተሞች ላይ ተሾም አለው።'),
  ('83e1897c-d4e6-579f-a46c-f3da7d82de03', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 8, 18, 'ሁለተኛውም መጥቶ፦ አቤቱ፥ ምናንህ አምስት ነበር፤ አምስት አትርፌአለሁ አለው።'),
  ('35ebe81e-2134-530f-a0df-312ec33c808f', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 9, 19, 'እርሱንም፦ አንተም በአምስት ከተሞች ተሾም አለው።'),
  ('02d01949-0579-5bb5-af72-768557c3e854', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 10, 20, 'ሦስተኛውም መጥቶ እንዲህ አለው፦ አቤቱ፥ በእኔ ዘንድ የነበረቺው ምናንህ እነኋት፤ በጨርቅ ጠቅልዬ አኑሬአት ነበር።'),
  ('25590d61-1a7e-511f-aaf8-40aca850636f', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 11, 21, 'አንተ ያላኖርኸውን የምትወስድ፥ ያልዘራኸውን የምታጭድ፥ ያልበተንኸውንም የምትሰበስብ ጨካኝ ሰው እንደ ሆንህ ስለማውቅህ ፈርቼሃለሁና።'),
  ('ce5d7823-f636-5177-a5b1-815a45f70a7c', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 12, 22, 'ጌታውም እንዲህ አለው፦ አንተ ክፉ ሰነፍ አገልጋይ፥ እኔ ያላስቀመጥሁትን የምወስድ፥ ያልዘራሁትን የማጭድ፥ ያልበተንሁትንም የምሰበስብ ጨካኝ ሰው እንደ ሆንሁ ታውቃለህን? እንደ ቃልህ እፈርድብሃለሁ።'),
  ('3ae69847-9620-5bb1-a677-a39832ee0a1a', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 13, 23, 'ለምን ገንዘቤን ወደ ለዋጮች አላስገባህም? እኔም መጥቼ ከትርፉ ጋር በወሰድሁት ነበር።'),
  ('8e6f0f90-eb1b-5474-a314-ba513e5e6ff5', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 14, 24, 'ከዚያ የቆሙትንም፦ ይህን ምናን ከእርሱ ተቀብላችሁ ዐሥር ምናን ላለው ስጡት አላቸው።'),
  ('c9751f7e-0f64-59e0-a411-43e1d67a9f3b', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 15, 25, 'እነርሱም አቤቱ፥ ዐሥር ምናን ያለው አይደለምን? አሉት።'),
  ('c0947d90-6ab1-535f-a2ec-c7b365db4521', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 16, 26, 'እርሱም እንዲህ አላቸው፦ ላለው ሁሉ ይሰጡታል፤ ይጨምሩለታልም፤ የሌለውን ግን ያን ያለውንም ቢሆን ይወስዱበታል።'),
  ('152e3b88-ff90-520c-aac0-41ed7b348d4b', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'a7ddf7fc-ebc4-59a3-a951-7c428a54c0a7', 17, 27, 'ነገር ግን እነዚያን ልነግሥባቸው ያልወደዱትን ጠላቶችን ወደዚህ አምጡና በፊቴ ውጉአቸው።”'),
  ('13440026-80a6-5c0e-aadb-d420a0fe46fb', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 1, 28, 'ይህንም ተናግሮ ወደ ፊት ሄደ፤ ወደ ኢየሩሳሌምም ወጣ።'),
  ('c5acd04d-b9be-5b9b-af3e-865febe5601f', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 2, 29, 'ደብረ ዘይት ወደሚባል ተራራ አጠገብ ወዳሉት ወደ ቤተ ፋጌና ወደ ቢታንያ በቀረበ ጊዜ፥ ከደቀ መዛሙርቱ ሁለቱን ላከ።'),
  ('b5132100-ca8c-5d3a-a4c6-b812da0b8a58', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 3, 30, 'እንዲህም አላቸው፥ “በፊታችሁ ወደ አለችው መንደር ሂዱ፤ ገብታችሁም ሰው ያልተቀመጠበት የታሰረ ውርንጫ ታገኛላችሁ፤ ፈትታችሁም አምጡልኝ።'),
  ('02d15665-f6b0-5286-a504-d973d01eb436', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 4, 31, 'ለምን ትፈቱታላችሁ? የሚላችሁ ቢኖር ጌታው ይሻዋል በሉ።”'),
  ('35126445-4e9c-5f01-a343-fb08e55a52e3', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 5, 32, 'የተላኩትም ሄደው እንደ አላቸው አገኙ።'),
  ('f9d66c80-10b2-5ee1-a7a0-e0c23e7d21fc', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 6, 33, 'ውርንጫውንም ሲፈቱ ባለቤቶቹ “ውርንጫውን ለምን ትፈቱታላችሁ?” አሉአቸው።'),
  ('7b069fac-3f62-5e7c-a871-6d7388643e01', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 7, 34, 'እነርሱም “ጌታው ይሻዋል” አሉ።'),
  ('d91db32b-d10d-57f3-accb-9759f923e4e2', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 8, 35, 'ይዘውም ወደ ጌታችን ኢየሱስ ወሰዱት፤ በውርንጫው ላይም ልብሳቸውን ጭነው ጌታችን ኢየሱስን በዚያ ላይ አስቀመጡት።'),
  ('03ab56bc-7b7a-576e-a82e-c96063d357bd', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 9, 36, 'ሲሄዱም በመንገድ ልብሳቸውን አነጠፉ።'),
  ('027d087c-1281-59ad-a09b-c015f1168899', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 10, 37, 'ወደ ደብረ ዘይት ዐቀበት መውረጃም በደረሱ ጊዜ፥ ደቀ መዛሙርቱ በሙሉ ስለ አዩት ኀይል ሁሉ ደስ ይላቸውና እግዚአብሔርን በታላቅ ቃል ያመሰግኑት ዘንድ ጀመሩ።'),
  ('ec64c98e-4dde-578f-a262-3696f462ad5d', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 11, 38, 'እንዲህ እያሉ፥ “በእግዚአብሔር ስም የሚመጣ ቡሩክ ነው፤ የእስራኤል ንጉሥ ቡሩክ ነው፤ ሰላም በምድር፥ በአርያምም ክብር ይሁን።”'),
  ('39880a95-e900-5163-ab3b-217121ffa7fb', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 12, 39, 'ከፈሪሳውያንም በሕዝቡ መካከል፥ “መምህር ሆይ፥ ደቀ መዛሙርትህን ገሥጻቸው” ያሉት ነበሩ።'),
  ('2ddabe1b-c524-59ce-a89f-fc1095311923', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'be9f3e70-e9ff-5622-a42d-b774ccb2d2c5', 13, 40, 'እርሱም መልሶ እንዲህ አላቸው፥ “እነዚህ ዝም ቢሉ እኒህ ድንጋዮች ይጮሀሉ።”'),
  ('cc3ee711-11db-5ad8-a1aa-43dba22d7618', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'eb4f975f-919f-5648-a7d1-0b89fd606547', 1, 41, 'በደረሰ ጊዜም ከተማዪቱን አይቶ አለቀሰላት።'),
  ('9c6534a7-3eea-5ee6-a165-56b6620b124f', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'eb4f975f-919f-5648-a7d1-0b89fd606547', 2, 42, 'እንዲህም አላት፥ “አንቺስ ብታውቂ ሰላምሽ ዛሬ ነበረ፤ ከእንግዲህ ወዲህ ግን ከዐይኖችሽ ተሰወረ።'),
  ('4291438a-ef65-51f0-af37-d17f569174d7', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'eb4f975f-919f-5648-a7d1-0b89fd606547', 3, 43, 'ጠላቶችሽ አንቺን የሚከቡበት ቀን ይመጣል፤ ይከትሙብሻል፤ ያስጨንቁሻልም፤ በአራቱ ማዕዘንም ከብበው ይይዙሻል።'),
  ('53fd2e1d-47e9-5dc9-ac92-1a5a8ea65d82', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', 'eb4f975f-919f-5648-a7d1-0b89fd606547', 4, 44, 'አንቺን ይጥሉሻል፤ ልጆችሽንም ከአንቺ ጋር ይጥሉአቸዋል፤ ድንጋይንም በደንጋይ ላይ አይተዉልሽም፤ የይቅርታሽን ዘመን አላወቅሽምና።”'),
  ('f1a1d1b0-3c5e-5feb-a50b-bcb59ceb07a1', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '412e72fe-5ca7-5bac-a0af-3da12ca70542', 1, 45, 'ወደ ቤተ መቅደስም ገብቶ በዚያ የሚሸጡትንና የሚገዙትን ሁሉ አስወጣ፤ የለዋጮችንም መደርደሪያ፥ የርግብ ሻጮችንም ወንበር ገለበጠ።'),
  ('d613cdd5-14b2-567e-a343-133de4b8eedd', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '412e72fe-5ca7-5bac-a0af-3da12ca70542', 2, 46, '“ቤቴ የጸሎት ቤት ይባላል የሚል ጽሑፍ አለ፤ እናንተ ግን የሌቦችና የቀማኞች ዋሻ አደረጋችሁት” አላቸው።'),
  ('bc89fb52-c50c-5fc1-a2fb-583157cb48b8', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '412e72fe-5ca7-5bac-a0af-3da12ca70542', 3, 47, 'ዘወትርም በመቅደስ ያስተምር ነበር፤ የካህናት አለቆች፥ ጻፎችና የሕዝብ ታላላቆችም ሊገድሉት ይሹ ነበር።'),
  ('9bea79e3-7ba7-56c7-a3fe-5a77aa6fadb8', 'd7bf4a4e-ca24-5283-a5c1-5ce691df3b3e', '412e72fe-5ca7-5bac-a0af-3da12ca70542', 4, 48, 'ነገር ግን የሚያደርጉትን አጡ፤ ሕዝቡ ሁሉ ትምህርቱን በመስማት ይመሰጡ ነበርና።'),
  ('23657921-0900-5fc8-a976-717a076fdf30', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 1, 1, 'ከዚህም በኋላ በአንድ ቀን ሕዝቡን በመቅደስ ሲያስተምራቸው፥ ወንጌልንም ሲነግራቸው፥ የካህናት አለቆች፥ ጻፎችና ሽማግሌዎች ተነሡበት።'),
  ('ba4c3226-1a8f-525c-a80e-a83d5b3f304d', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 2, 2, '“ይህን በማን ሥልጣን ታደርጋለህ? ይህንስ እንድታደርግ ማን ፈቀደልህ? እስኪ ንገረን” አሉት።'),
  ('ce22a21a-b843-5612-a4ed-7d0446a30b5e', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 3, 3, 'እርሱም መልሶ፥ “እኔም አንዲት ነገርን እጠይቃችኋለሁ፤ ንገሩኝ፤'),
  ('057437a7-cfe5-5f3b-ae0c-6c2e6bc9391e', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 4, 4, 'የዮሐንስ ጥምቀት ከወዴት ናት? ከሰማይ ናትን? ወይስ ከሰው?” አላቸው።'),
  ('2629d956-bdad-5afd-a3ef-7aa38c0f90d8', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 5, 5, 'እርስ በርሳቸውም እንዲህ ተባባሉ፤ “ከሰማይ ነው ብንለው ለምን አላመናችሁትም? ይለናል።'),
  ('7113a9db-9a3a-50e7-a6c2-42c22bae0027', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 6, 6, 'ከሰው ነው ብንለውም ሕዝቡ ሁሉ በድንጋይ ይወግሩናል፤ ሁሉም ዮሐንስ ነቢይ እንደ ሆነ አምነውበታልና።'),
  ('239e04f5-47f9-5a36-a3b9-9387f95ce389', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 7, 7, 'ከወዴት እንደ ሆነች አናውቅም” ብለው መለሱለት።'),
  ('fec695cf-aa76-5cd2-a95c-fcf2e401055e', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'bc529332-f8e5-53b1-a897-0a9b31a8e483', 8, 8, 'ጌታችን ኢየሱስም፥ “እኔም ይህን በማን ሥልጣን እንደማደርግ አልነግራችሁም” አላቸው።'),
  ('cb24b416-671b-551f-acac-b48b2b2b0546', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 1, 9, 'ለሕዝቡም ይህን ምሳሌ ይመስልላቸው ጀመረ፤ እንዲህም አላቸው፥ “አንድ ሰው ወይን ተከለ፤ መጭመቂያም አስቈፈረ፤ ግንብም ሠራለት፤ ለገባሮችም ሰጥቶ ወደ ሩቅ ሀገር ሄደ፤ ሳይመለስም ዘገየ።'),
  ('9efa9baa-7b86-5996-abf4-fc4993ab7174', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 2, 10, 'የመከሩ ወራት በሆነ ጊዜም ወደ ገባሮቹ፥ ከወይኑ ፍሬ ይልኩለት ዘንድ አገልጋዩን ላከ፤ ገባሮቹ ግን አገልጋዩን ደብድበው ባዶ እጁን ሰደዱት።'),
  ('66c010ea-077c-57aa-a972-6a288ae437a1', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 3, 11, 'ዳግመኛም ሌላውን አገልጋዩን ላከ፤ እርሱንም ደብድበውና አዋርደው ባዶ እጁን ሰደዱት።'),
  ('4648dba3-5360-54ce-ab60-138c3c53976f', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 4, 12, 'ደግሞ ሦስተኛውን አገልጋዩን ላከ፤ እርሱንም አቍስለው ሰደዱት።'),
  ('6a2da654-cf24-54b8-aba2-997d2808aa20', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 5, 13, 'የወይኑ ባለቤትም፦ እንግዲህ ምን ላድርግ? ምናልባት እርሱን እንኳ አይተው ያፍሩ እንደ ሆነ የምወደውን ልጄን ልላክ ብሎ ላከው።'),
  ('17ce9057-a770-5e0a-a2dd-92113bea2a96', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 6, 14, 'ገባሮቹም ባዩት ጊዜ ወራሹ ይህ ነው፤ ኑ፥ እንግደለውና ርስቱን እንውሰድ ብለው ተማከሩ።'),
  ('b0b0ea89-8f63-5d9a-af5b-07fc902925de', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 7, 15, 'ከወይኑ ቦታም ወደ ውጭ አውጥተው ገደሉት።'),
  ('05a5a758-41ed-5825-acc5-6e6af73a93b6', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 8, 16, 'የወይኑ ባለቤት በመጣ ጊዜ እንግዲህ ምን ያደርጋቸዋል? ይመጣል፤ እነዚያንም ገባሮች ይገድላቸዋል፤ ወይኑንም ለሌሎች ገባሮች ይሰጣል፤” ቃሉንም ሰምተው፥ “አይሆንም፤ እንዲህ አይደረግም” አሉ።'),
  ('4e532e10-d4b1-50ef-a268-6b7e5a6e9e3c', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 9, 17, 'ጌታችን ኢየሱስም ተመለከተና እንዲህ አላቸው፤ “ግንበኞች የናቁአት ድንጋይ እርስዋ የማዕዘን ራስ ሆነች፥ የሚለው ጽሑፍ ምንድነው?'),
  ('dfb80663-3e59-5c46-aede-c44bd0b56c51', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 10, 18, 'በዚያች ድንጋይ ላይ የወደቀ ሁሉ ይቀጠቀጣል፤ እርስዋም የወደቀችበትን ታደቅቀዋለች።”'),
  ('6476ea6d-ea33-5d70-a19c-f66155635409', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', 'dbf0462a-980e-5227-a8b5-ad4edd0c78e1', 11, 19, 'ያን ጊዜም የካህናት አለቆችና ጻፎች ሊይዙት ወደዱ፤ ይህን ስለ እነርሱ እንደ መሰለ ዐውቀዋልና፤ ነገር ግን ሕዝቡን ፈሩአቸው።'),
  ('d5141daf-d718-5a8c-aa03-cf56ebb0038e', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 1, 20, 'ከእነርሱም ተለይተው ከሄዱ በኋላ፥ የሚጠባበቁትን አዘጋጁለት፤ በአነጋገሩም ያስቱት ዘንድ ወደ መኳንንትና ወደ መሳፍንት አሳልፈው ሊሰጡት ራሳቸውን የሚያመጻድቁ ሰላዮችን ወደ እርሱ ላኩ።'),
  ('649554e9-c40c-59aa-aebb-07c270117630', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 2, 21, 'እነርሱም እንዲህ ብለው ጠየቁት፥ “መምህር ሆይ፥ አንተ እውነት እንደምትናገርና እንደምታስተምር፥ ፊት አይተህም እንደማታዳላ፥ የእግዚአብሔርንም መንገድ በቀጥታ እንደምታስተምር እናውቃለን።'),
  ('736fa548-61ee-502b-ab33-bd936f1ea7fc', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 3, 22, 'ለቄሣር ግብር መስጠት ይገባል? ወይስ አይገባም?”'),
  ('a7d9d79f-66af-5551-a1e0-6757855fcb26', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 4, 23, 'ተንኰላቸውንም ዐውቆ፥ “ለምን ትፈትኑኛላችሁ? ገንዘቡን አሳዩኝ” አላቸው።'),
  ('61c62ec5-b04c-5d7f-a304-536c8eb40436', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 5, 24, 'አምጥተውም አሳዩት፤ “መልኩ፥ ጽሕፈቱስ የማነው?” አላቸው፤ እነርሱም፥ “የቄሣር ነው” ብለው መለሱለት።'),
  ('b97d286d-5a73-5c59-a2d8-71c41886427e', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 6, 25, 'እርሱም፥ “እንኪያስ የቄሣርን ለቄሣር፥ የእግዚአብሔርንም ለእግዚአብሔር ስጡ” አላቸው።'),
  ('32d8df97-067d-59cf-aa9e-0dcfbe0b539b', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '6d9ae351-d8c6-5fbf-a255-1d978681ff52', 7, 26, 'በሕዝቡም ሁሉ ፊት በአነጋገሩ ማሳሳት ተሳናቸው፤ መልሱንም አድንቀው ዝም አሉ።'),
  ('7f06434e-8055-5aba-a0ad-14aa7222318f', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 1, 27, '“ሙታን አይነሡም” ከሚሉ ከሰዱቃውያንም አንዳንድ ሰዎች ወደ እርሱ መጡ።'),
  ('4ed081fd-9be3-58d3-a585-3231edaaca92', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 2, 28, 'እነርሱም እንዲህ ብለው ጠየቁት፥ “መምህር ሆይ፥ ሙሴ፦ ‘ወንድሙ ልጅ ሳይወልድ ሚስቱን ትቶ የሞተበት ሰው ቢኖር ወንድሙ ሚስቱን አግብቶ ለወንድሙ ዘር ይተካ’ ሲል ጽፎልናል።'),
  ('e7f2e58a-5fc1-580c-a4d5-470a067ef2b2', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 3, 29, 'እንግዲህ ከእኛ ዘንድ ሰባት ወንድማማቾች ነበሩ፤ ታላቁ ሚስት አግብቶ ልጅ ሳይወልድ ሞተ።'),
  ('cf662256-a6fe-57ca-a81b-f16d0151ed53', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 4, 30, 'እንደዚሁም ሁለተኛው አገባት፤ እርሱም ልጅ ሳይወልድ ሞተ፤'),
  ('eb57bb39-9228-508f-ae25-2687bbcf7fb3', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 5, 31, 'ሦስተኛውም አገባት፤ እንዲሁም ሰባቱ ሁሉ አገቡአት፤ ልጅ ሳይወልዱም ሞቱ።'),
  ('194fa7ac-19d1-50d0-af00-63f4ad2f6dcb', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 6, 32, 'ከሁሉም በኋላ ያቺ ሴት ሞተች።'),
  ('9c651741-23ea-5be7-a9e4-dc5e8c80b648', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 7, 33, 'እንግዲህ ሙታን በሚነሡበት ጊዜ ከእነርሱ ለማንኛው ሚስት ትሆናለች? ሰባቱም ሁሉ አግብተዋት ነበርና።”'),
  ('b13ad8c1-5d6b-5ddf-a94c-73a7a034fb8a', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 8, 34, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “የዚህ ዓለም ልጆች ያገባሉ፥ ይጋባሉም፤ ይወልዳሉ፥ ይዋለዳሉም።'),
  ('c651ba4d-497a-5966-aea8-055fbcc1fb9f', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 9, 35, 'ያን ዓለምና የሙታንን ትንሣኤ ሊወርሱ የሚገባቸው እነዚያ ግን አያገቡም፤ አይጋቡም።'),
  ('7372162b-064f-5d8f-abca-b54116dc5e3d', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 10, 36, 'እንግዲህ ወዲህ ሞት የለባቸውም፤ እንደ እግዚአብሔር መላእክት ናቸው እንጂ፤ የትንሣኤ ልጆችም ስለሆኑ የእግዚአብሔር ልጆች ይሆናሉ።'),
  ('73c32e83-5d0b-566c-a613-c7b5fa4683fe', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 11, 37, 'ሙታን እንደሚነሡስ እግዚአብሔር፦ ‘እኔ የአብርሃም አምላክ፥ የይስሐቅም አምላክ፥ የያዕቆብም አምላክ ነኝ’ ብሎ በቍጥቋጦው ዘንድ እንደ አነጋገረው ሙሴ ተናግሮአል።'),
  ('7e5f1f8a-7563-540b-ae05-7804bd133fd5', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 12, 38, 'እንኪያስ የሕያዋን አምላክ እንጂ የሙታን አምላክ አይደለም፤ ሁሉም በእርሱ ዘንድ ሕያዋን ናቸውና።”'),
  ('c28af834-d76e-57bc-a105-c94c075b0d3f', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 13, 39, 'ከጻፎችም ወገን የሆኑ ሰዎች፥ “መምህር ሆይ፥ መልካም ብለሃል” ብለው መለሱ።'),
  ('f7b23901-b949-526b-a856-0d769a01fcde', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '5c6e52c9-b0f3-5f68-acf8-57f993e7d300', 14, 40, 'ከዚያ ወዲህ ግን ሊጠይቀው የደፈረ ማንም የለም።'),
  ('0a513c65-ab1f-581b-acca-2e146dde4537', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '58a9b85e-2b61-5530-a3fe-7cfcbfb4749e', 1, 41, 'እንዲህም አላቸው፥ “ክርስቶስን እንዴት የዳዊት ልጅ ይሉታል?'),
  ('4927c29a-d0e5-5776-a3f1-c95afb36cd3d', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '58a9b85e-2b61-5530-a3fe-7cfcbfb4749e', 2, 42, 'እርሱ ራሱ ዳዊት በመዝሙር መጽሐፍ ‘ጌታ ጌታዬን በቀኜ ተቀመጥ፥'),
  ('6be7f6a3-7304-5b8c-abaf-3b10b42db0fc', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '58a9b85e-2b61-5530-a3fe-7cfcbfb4749e', 3, 43, 'ጠላቶችህን ከእግርህ ጫማ በታች እስከ አደርጋቸው ድረስ’ ብሏል።'),
  ('92b6ab17-c542-5048-a06c-719fad68e345', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '58a9b85e-2b61-5530-a3fe-7cfcbfb4749e', 4, 44, 'እንግዲህ እርሱ ራሱ ዳዊት ‘ጌታዬ’ ያለው እንዴት ልጁ ይሆናል?”'),
  ('7961108b-2e43-5c37-a6fc-cfe6138e348d', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '50772e5f-ccfc-5924-abc1-10b2d52f7cd8', 1, 45, 'ሕዝቡም ሲሰሙ ደቀ መዛሙርቱን እንዲህ አላቸው።'),
  ('9b9e1d18-45c5-50ce-acf1-81f34fcb85bd', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '50772e5f-ccfc-5924-abc1-10b2d52f7cd8', 2, 46, '“ልብሳቸውን አንዘርፍፈው ወዲያ ወዲህ ማለትን ከሚሹ፥ በገበያ እጅ መነሣትንና በአደባባይ ፊት ለፊት፥ በማዕድም ጊዜ በከበሬታ መቀመጫ መቀመጥን ከሚወዱ ጻፎች ተጠበቁ።'),
  ('30d4a3aa-6707-5c0a-ac7d-b21a292aadb2', 'cd4c9712-13ea-54ea-a0da-d47bdb6a2560', '50772e5f-ccfc-5924-abc1-10b2d52f7cd8', 3, 47, 'የመበለቶችን ገንዘብ የሚበሉ፥ ለምክንያት ጸሎትንም የሚያስረዝሙ እነዚህ ታላቅ ፍርድን ይቀበላሉ።”'),
  ('cb375124-3532-5a4e-a144-0357c90071fe', 'ade5a48a-bc6e-5138-a923-b36723122139', '7edf04e5-8ea1-5f35-a4b5-f6405eff5d8c', 1, 1, 'በሙዳየ ምጽዋቱ መባቸውን የሚያገቡ ባለጠጎችን አየ።'),
  ('f4571dc0-6c28-5ed7-ace0-8d9e5055d9bb', 'ade5a48a-bc6e-5138-a923-b36723122139', '7edf04e5-8ea1-5f35-a4b5-f6405eff5d8c', 2, 2, 'አንዲት ድሃ መበለትም ሁለት መሐለቅ ስታስገባ አየ።'),
  ('a0855aff-8269-5858-a824-b420b7305b02', 'ade5a48a-bc6e-5138-a923-b36723122139', '7edf04e5-8ea1-5f35-a4b5-f6405eff5d8c', 3, 3, 'እንዲህም አላቸው፥ “እውነት እላችኋለሁ፥ ይህቺ ድሃ መበለት ከሁሉ ይልቅ አብዝታ ለእግዚአብሔር መባ አገባች።'),
  ('7233a47a-1b3b-56f6-a9c2-19d320540dff', 'ade5a48a-bc6e-5138-a923-b36723122139', '7edf04e5-8ea1-5f35-a4b5-f6405eff5d8c', 4, 4, 'እነዚህ ሁሉ ከተረፋቸው ለእግዚአብሔር መባ አግብተዋልና፤ ይህቺ ግን ከድህነቷ ያላትን ጥሪቷን ሁሉ አገባች።”'),
  ('6832e3c5-a25d-5dd8-af78-366d45ac995b', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 1, 5, 'ስለ ቤተ መቅደስም ድንጋዩ ያማረ ነው፥ አሠራሩም ያጌጠ ነው የሚሉት ነበሩ።'),
  ('68ca755a-44f8-53a8-a1a3-6ce99bc12af3', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 2, 6, 'እንዲህም አላቸው፥ “ይህን ታያላችሁን? በእዚህ ቦታ ድንጋይ በድንጋይ ላይ የማይተውበትና ሳይፈርስ የማይቀርበት ዘመን ይመጣል።”'),
  ('326e6871-9f67-56fb-aca3-b2819822ae4d', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 3, 7, 'እነርሱም፥ “መምህር ሆይ፥ ይህ መቼ ይደረጋል? ይህስ የሚሆንበት ጊዜው፥ ምልክቱስ ምንድን ነው?” ብለው ጠየቁት።'),
  ('554d1bc8-5714-5594-a4e4-778755156562', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 4, 8, 'እርሱም እንዲህ አላቸው፥ “ብዙዎች እኔ ክርስቶስ ነኝ፤ ጊዜውም ደርሶአል እያሉ በስሜ ይመጣሉና እንዳያስቱአችሁ ተጠንቀቁ፤ እነርሱንም ተከትላችሁ አትሂዱ።'),
  ('4593ae8d-39d1-5e0c-aa4f-caad6aec57e6', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 5, 9, 'ጦርነትንና ጠብን፥ ክርክርንም በሰማችሁ ጊዜ አትደንግጡ፤ አስቀድሞ ይህ ይሆን ዘንድ ግድ ነውና፤ ነገር ግን ወዲያው የሚፈጸም አይደለም።”'),
  ('f0eecb34-d75c-5617-a73a-6991ff768078', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 6, 10, 'እንዲህም አላቸው፥ “ሕዝብ በሕዝብ ላይ፥ ነገሥታትም በነገሥታት ላይ ይነሣሉ።'),
  ('36ff9605-7f35-5a52-ac9f-350434249af1', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 7, 11, 'በየሀገሩ ታላቅ የምድር መነዋወጥና ራብ፥ በሰውም ላይ በሽታና ፍርሀት ይመጣል፤ በሰማይም ታላቅ ምልክት ይሆናል።'),
  ('022fc862-536f-5d37-a3a2-86ec572d720d', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 8, 12, 'ከዚህም ሁሉ አስቀድሞ ይይዙአችኋል፤ ወደ አደባባዮችም ይወስዱአችኋል፤ ያሳድዱአችኋል፤ ያስሩአችኋል፤ ስለ ስሜም ወደ ነገሥታትና ወደ መሳፍንት ይወስዱአችኋል።'),
  ('785e99ca-8a19-582a-ae47-72d75fed1071', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 9, 13, 'ይህም በእነርሱ ላይ ምስክር ይሆንባቸዋል።'),
  ('9c258df6-86f8-535c-a43a-d3f5ec174267', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 10, 14, 'ዕወቁ፤ የምትናገሩትንም በልባችሁ አታስቡ።'),
  ('ef93e85e-f38b-50e5-a249-41aa76b3632d', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 11, 15, 'በእናንተ ላይ የሚነሡ ሊመልሱላችሁና ሊከራከሯችሁ እንዳይችሉ እኔ አፍንና ጥበብን እሰጣችኋለሁ።'),
  ('db889f61-00a3-50fb-a4fe-87603c957947', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 12, 16, 'ወላጆቻችሁና ወንድሞቻችሁ፥ ወዳጆቻችሁና ባልንጀሮቻችሁ አሳልፈው ይሰጡአችኋል።'),
  ('05079187-50c9-5ef1-a1ea-8fa500c2baeb', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 13, 17, 'ሁሉም ስለ ስሜ ይጠሉአችኋል፤ ይገድሉአችኋልም።'),
  ('ddbfc0d5-4db4-5dbb-a727-3d00b057ca4f', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 14, 18, 'ነገር ግን ከራስ ጠጕራችሁ አንዲቱ እንኳ አትጠፋም።'),
  ('6d3e9c3c-d290-53c5-a1f7-1c6d19171c8a', 'ade5a48a-bc6e-5138-a923-b36723122139', '2b3477d5-1958-5382-ab10-c13227a170e9', 15, 19, 'በትዕግሥታችሁም ነፍሳችሁን ገንዘብ ታደርጓታላችሁ።'),
  ('bc3731c9-8589-5a2e-a15b-f0996eefb393', 'ade5a48a-bc6e-5138-a923-b36723122139', '6fda450f-9409-5e9e-a7ef-c4552f6c2667', 1, 20, '“ኢየሩሳሌምን ጭፍሮች ከብበዋት ባያችሁ ጊዜ ጥፋቷ እንደ ደረሰ ዕወቁ።'),
  ('10d3c86f-6388-5c2b-a0cd-6684a6203bd9', 'ade5a48a-bc6e-5138-a923-b36723122139', '6fda450f-9409-5e9e-a7ef-c4552f6c2667', 2, 21, 'ያንጊዜ በይሁዳ ያሉ ወደ ተራራ ይሽሹ፤ በመካከልዋ ያሉም ከእርስዋ ይውጡ፤ በአውራጃዎችዋ ያሉም ወደ እርስዋ አይግቡ።'),
  ('2883cbdd-2d46-52ae-a245-093468993bd2', 'ade5a48a-bc6e-5138-a923-b36723122139', '6fda450f-9409-5e9e-a7ef-c4552f6c2667', 3, 22, 'በእርስዋ ላይ የተጻፈው ሁሉ ይፈጸም ዘንድ እርስዋን የሚበቀሉበት ጊዜዋ ነውና።'),
  ('b44ca839-1a6d-55ed-adee-59893daaf79c', 'ade5a48a-bc6e-5138-a923-b36723122139', '6fda450f-9409-5e9e-a7ef-c4552f6c2667', 4, 23, 'ነገር ግን በዚያ ወራት ለፀነሱና ለሚያጠቡ ወዮላቸው፤ በምድር ላይ ጽኑ መከራ፥ በዚህም ሕዝብ ላይ መቅሠፍት ይሆናልና።'),
  ('4b89fa88-af93-53f6-aa59-c95143c364ba', 'ade5a48a-bc6e-5138-a923-b36723122139', '6fda450f-9409-5e9e-a7ef-c4552f6c2667', 5, 24, 'በሰይፍ ስለት ይወድቃሉ፤ በአሕዛብም ሁሉ ይማረካሉ፤ የአሕዛብ ጊዜያቸው እስኪፈጸም ድረስ አሕዛብ ኢየሩሳሌምን ይረግጡአታል።'),
  ('6aeae51d-ed0c-5ca3-a783-2232f16bcc28', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 1, 25, '“በፀሐይና በጨረቃ፥ በከዋክብትም ላይ ምልክት ይሆናል፤ በምድር ላይም አሕዛብ ይጨነቃሉ፤ ከባሕሩና ከሞገዱ ድምፅ የተነሣም ይሸበራሉ።'),
  ('3bf520b8-0064-5ca4-a9c7-82965ba497a8', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 2, 26, 'በዓለም ላይ ከሚመጣው ፍርሀትና ሽብር የተነሣም የሰዎች ነፍስ ትዝላለች፤ ያንጊዜ የሰማያት ኀይል ይናወጣልና።'),
  ('d984acbf-c5d5-5f5a-a5a8-a432d7436bd3', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 3, 27, 'ያንጊዜም በሰማይ ደመና፥ በፍጹም ኀይልና ክብር ሲመጣ የሰውን ልጅ ያዩታል።'),
  ('5f3a40e3-9d29-5af1-a475-8b38ce57308e', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 4, 28, 'ይህም ሁሉ በሆነ ጊዜ ወደ ላይ አቅንታችሁ ተመልከቱ፤ ራሳችሁንም አንሡ፤ የሚያድናችሁ መጥቶአልና።”'),
  ('20fe4337-145b-54ad-a206-7600aec65bc7', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 5, 29, 'ምሳሌም መስሎ እንዲህ አላቸው፥ “በለስንና ዛፎችን ሁሉ እዩ።'),
  ('7cbcf8e0-6177-5647-ae71-0fd2e21157d3', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 6, 30, 'ለምልመውም ያያችኋቸው እንደ ሆነ መከር እንደ ደረሰ ታውቃላችሁ።'),
  ('ffdabc2f-33b9-57fb-a961-a4f55d1fc571', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 7, 31, 'እንዲሁ እናንተም ይህ እንደ ሆነ ስታዩ የእግዚአብሔር መንግሥት እንደ ደረሰች ዕወቁ።'),
  ('3af4764d-423d-5e70-a608-e7844f723e93', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 8, 32, 'እውነት እላችኋለሁ፥ ይህ ሁሉ እስኪደረግ ድረስ ይህቺ ትውልድ አታልፍም።'),
  ('356c903c-ead1-52d2-ac37-3a4ab82e288a', 'ade5a48a-bc6e-5138-a923-b36723122139', '3f2f1974-c56f-51f3-a4a7-31dcdee19d52', 9, 33, 'ሰማይና ምድር ያልፋል፤ ቃሌ ግን አያልፍም።'),
  ('cf21aef8-bcda-5dbb-af18-4b91af1834ad', 'ade5a48a-bc6e-5138-a923-b36723122139', '6e723550-bdd0-5788-a34c-4847d7d23d2c', 1, 34, '“ራሳችሁን ጠብቁ፤ በመብልና በመጠጥ፥ በመቀማጠልና የዓለምን ኑሮ በማሰብ ልባችሁን አታደንድኑ፤ ያቺ ቀንም በድንገት ትደርስባችኋለች።'),
  ('cb93dbbf-3a89-5ea9-a568-9ff326500163', 'ade5a48a-bc6e-5138-a923-b36723122139', '6e723550-bdd0-5788-a34c-4847d7d23d2c', 2, 35, 'በምድር በሚኖሩት ሁሉ ላይ እንደ ተዘረጋች ወጥመድ ትደርሳለችና።'),
  ('523f34f7-d3a8-5293-a2c3-248cb5baca55', 'ade5a48a-bc6e-5138-a923-b36723122139', '6e723550-bdd0-5788-a34c-4847d7d23d2c', 3, 36, 'እንግዲህ ከዚህ ከሚመጣው ሁሉ በጸሎታችሁ ማምለጥ እንድትችሉ፥ በሰው ልጅ ፊትም እንድትቆሙ ሁልጊዜ ትጉ።”'),
  ('8c1f4790-ed4a-5780-a496-acde5b7cf97d', 'ade5a48a-bc6e-5138-a923-b36723122139', 'f3764325-5923-54c7-a960-033ecbcf8379', 1, 37, 'ቀን ቀን በመቅደስ ያስተምር ነበር፤ ሌሊት ግን ወጥቶ ደብረ ዘይት በሚባለው ተራራ ያድር ነበር።'),
  ('651f0c8b-81c9-53fc-aa08-ba8cba5095b4', 'ade5a48a-bc6e-5138-a923-b36723122139', 'f3764325-5923-54c7-a960-033ecbcf8379', 2, 38, 'ሕዝቡም ሁሉ ቃሉን ሊሰሙ እርሱ ወዳለበት ወደ መቅደስ ማልደው ይሄዱ ነበር።'),
  ('b258b3f6-c06c-5315-a870-b310f6331512', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '3e4005f5-7faa-5f02-a5f2-c3eeec1e4b19', 1, 1, 'ፋሲካም የሚባለው የቂጣ በዓል ቀረበ።'),
  ('dbf1b422-8d92-52e7-af4f-732d99f4f816', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '3e4005f5-7faa-5f02-a5f2-c3eeec1e4b19', 2, 2, 'የካህናት አለቆችና ጻፎችም ሊገድሉት ይሹ ነበር፤ ነገር ግን ሕዝቡን ይፈሩአቸው ነበር።'),
  ('cf8702bd-d34c-5542-a745-47a92b558ab7', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '5d1f4110-a127-57e1-aa5e-1a98ba3c2287', 1, 3, 'ቍጥሩ ከዐሥራ ሁለቱ በነበረው በአስቆሮቱ ይሁዳ ልብ ሰይጣን አደረ።'),
  ('4b64f4b7-8d8b-52e8-a1c2-7429e333f25e', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '5d1f4110-a127-57e1-aa5e-1a98ba3c2287', 2, 4, 'ሄዶም ከካህናት አለቆችና ከታላላቆች ጋር እርሱን አሳልፎ እንዲሰጣቸው ተነጋገረ።'),
  ('69094d0b-8079-573e-aed0-b694d8bd04db', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '5d1f4110-a127-57e1-aa5e-1a98ba3c2287', 3, 5, 'ደስ ብሏቸውም ሠላሳ ብር ሊሰጡት ተስማሙ።'),
  ('4622c269-574f-53bd-a7e6-471d7c01b5dc', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '5d1f4110-a127-57e1-aa5e-1a98ba3c2287', 4, 6, 'እርሱም እሺ አለ፤ ሰው ሳይኖርም እርሱን አሳልፎ ሊሰጣቸው ምቹ ጊዜ ይሻ ነበር።'),
  ('729dcc23-ccf7-5cf7-a7c8-b2cb82c96052', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 1, 7, 'የፋሲካን በግ የሚያርዱባት የቂጣ በዓልም ደረሰች።'),
  ('c8644749-aee0-579d-a91b-177c6260b1a5', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 2, 8, 'ጌታችን ኢየሱስም ጴጥሮስንና ዮሐንስን፥ “ሂዱና የምንበላውን የፋሲካ በግ አዘጋጁልን” አላቸው።'),
  ('84340c2a-36c9-55ff-a7a9-1f7c05ed7622', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 3, 9, 'እነርሱም፥ “ወዴት ልናዘጋጅልህ ትወዳለህ?” አሉት።'),
  ('f3923443-eb77-5776-af7a-1c8ad1469148', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 4, 10, 'እንዲህም አላቸው፥ “ወደ ከተማ በገባችሁ ጊዜ፥ የውኃ ማድጋ የተሸከመ ሰው ታገኛላችሁ፤ ወደሚገባበትም ቤት እርሱን ተከተሉት።'),
  ('3ac6ce82-bd27-5b05-ac96-5f1858af1b4a', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 5, 11, 'የዚያን ቤት ጌታ፦ መምህር ከደቀ መዛሙርቴ ጋር የፋሲካን በግ የምበላበት ቤት ወዴት ነው? ብሎሃል በሉት።'),
  ('4d96ed33-dbbe-5460-aa24-d98412006ed8', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 6, 12, 'እርሱም በሰገነት ላይ የተነጠፈ ታላቅ አዳራሽ ያሳያችኋል፤ በዚያ አዘጋጁልን።”'),
  ('9ba2f843-e903-5bae-a766-83978bfd42ab', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '6a726094-4f66-59f3-a0c0-e484b116042c', 7, 13, 'በሄዱም ጊዜ እንዳላቸው አገኙ፤ የፋሲካውንም በግ አዘጋጁ።'),
  ('2a31ce04-a7db-51ac-a620-799865a83944', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 1, 14, 'ሰዓቱም በደረሰ ጊዜ ጌታችን ኢየሱስ በማዕድ ተቀመጠ፤ ዐሥራ ሁለቱ ደቀ መዛሙርቱም ከእርሱ ጋር ተቀመጡ።'),
  ('a32b516a-9181-55ad-ad7d-6f61ea5e5fdd', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 2, 15, 'እርሱም እንዲህ አላቸው፥ “ከመከራዬ አስቀድሞ ይህን ፋሲካ ከእናንተ ጋር ልበላ እጅግ ወደድሁ።'),
  ('3bb56a8c-e892-5b7a-a234-ec902fff9702', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 3, 16, 'ነገር ግን፤ በእግዚአብሔር መንግሥት እስኪፈጸም ድረስ እንግዲህ ከእርሱ እንደማልበላ እነግራችኋለሁ” አላቸው።'),
  ('ea3fec87-3b27-5324-ae84-c41d07c22c2a', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 4, 17, 'ጽዋውንም ተቀብሎ አመሰገነ፤ እንዲህም አለ፥ “ይህን እንኩ ሁላችሁም ተካፈሉት።'),
  ('1581ee32-0d6f-5754-a501-20a97f28b3c8', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 5, 18, 'እላችኋለሁ፥ የእግዚአብሔር መንግሥት እስክትመጣ ድረስ፤ እንግዲህ ወዲህ ከዚህ የወይን ፍሬ አልጠጣም።”'),
  ('322c535a-6ee8-50bb-a2ef-715f6ae0bdd5', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 6, 19, 'ኅብስቱንም አነሣ፤ አመስገነ፤ ፈትቶም ሰጣቸው፤ እንዲህም አላቸው፥ “ስለ እናንተ ቤዛ ሆኖ የሚሰጥ ሥጋዬ ይህ ነው፤ ይህንም ለመታሰቢያዬ አድርጉት፤”'),
  ('1781e3c5-dd63-5a36-a619-d508e27c209b', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '023e806d-a696-50cf-ab66-a2b70d9e9664', 7, 20, 'እንዲሁም ከእራት በኋላ ጽዋዉን አንሥቶ እንዲህ አላቸው፥ “ይህ ጽዋ ስለ እናንተ በሚፈስሰው ደሜ የሚሆን አዲስ ኪዳን ነው።'),
  ('2b5df3a2-73a5-537f-acdd-d84574155e5f', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'a68e6855-7126-5034-aec2-7c3f551d1ddb', 1, 21, '“ነገር ግን አሳልፎ የሚሰጠኝ ሰው እጅ እነሆ፥ በማዕድ ከእኔ ጋር ነው።'),
  ('4bf4b31a-e7f0-5f7f-a7c2-036a58947063', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'a68e6855-7126-5034-aec2-7c3f551d1ddb', 2, 22, 'የሰው ልጅስ ስለ እርሱ እንደ ተጻፈ ይሄዳል፤ ነገር ግን የሰው ልጅ በእጁ ለሚሰጥበት ለዚያ ሰው ወዮለት።”'),
  ('751709b5-1bfd-5d65-a9e6-34a47eec8cb7', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'a68e6855-7126-5034-aec2-7c3f551d1ddb', 3, 23, 'ደቀ መዛሙርቱም ከእነርሱ ይህን የሚያደርግ ማን እንደ ሆነ እርስ በርሳቸው ተነጋገሩ።'),
  ('9360225c-c1a2-5b37-a44b-6cee9f62b68f', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 1, 24, 'ከዚህም በኋላ ከእነርሱ ማን እንደሚበልጥ እርስ በርሳቸው ተከራከሩ።'),
  ('bb136a81-c69b-58c0-a999-80fa02647b52', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 2, 25, 'እርሱም እንዲህ አላቸው፥ “አሕዛብን ንጉሦቻቸው ይገዙአቸዋል፤ በላያቸውም ሥልጣን ያላቸው ቸርነት አድራጊዎች ይባላሉ።'),
  ('7bd62690-c43d-5301-afc7-03f93919b18e', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 3, 26, 'ለእናንተ ግን እንዲህ አይደለም፤ ነገር ግን ከእናንተ ታላቁ እንደ ታናሽ ይሁናችሁ፤ አለቃውም እንደ አገልጋይ ይሁን።'),
  ('7e427b4e-0860-5fd6-a8d9-c8b958918fa3', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 4, 27, 'የሚበልጥ ማንኛው ነው? በማዕድ ላይ የተቀመጠው ነው? ወይስ የሚላላከው? በማዕድ ላይ የተቀመጠው አይደለምን? እነሆ፥ እኔ በመካከላችሁ እንደ አገልጋይ ነኝ።'),
  ('62cf24ab-5534-5a88-a333-a1e6478c1929', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 5, 28, 'ነገር ግን ስለ እኔ የታገሣችሁ እናንተ በመከራዬ ከእኔ ጋር ናችሁ።'),
  ('bfe02dbc-4c04-531e-aa04-8ebc76c22f49', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 6, 29, 'አባቴ ለእኔ እንደ ሰጠኝ፥ እኔም ለእናንተ መንግሥትን አዘጋጅላችኋለሁ፤'),
  ('0dedb592-4483-5f7d-a7b0-7d0973adf150', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '8bac05e0-33b7-5655-a216-0148b4ae755b', 7, 30, 'በመንግሥቴ በማዕዴ ትበሉና ትጠጡ ዘንድ፥ በወንበሮችም ተቀምጣችሁ በዐሥራ ሁለቱ ነገደ እስራኤል ትፈርዱ ዘንድ።”'),
  ('a47b7004-5f67-5fe6-a6a2-603add6622d2', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 1, 31, 'ጌታችን ኢየሱስም እንዲህ አለ፥ “ስምዖን፥ ስምዖን ሆይ፥ ሰይጣን እንደ አጃ ሊያበጥራችሁ አሁን ልመናን ለመነ።'),
  ('f58d8bcc-0359-55a3-ad9c-849fdaca5f22', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 2, 32, 'እኔ ግን ሃይማኖታችሁ እንዳይደክም ስለ እናንተ ጸለይሁ፤ አንተም ተመልሰህ ወንድሞችህን አጽናቸው።”'),
  ('9d7c70de-9cd4-5bbe-af58-8bbf57ec4b96', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 3, 33, 'እርሱም፥ “አቤቱ፥ እኔ ለመታሰርም ቢሆን፥ ለሞትም ቢሆን እንኳ ከአንተ ጋራ ለመሄድ የተዘጋጀሁ ነኝ” አለው።'),
  ('cb9b624e-7d2a-50e1-a6fb-d06fe003cd4c', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 4, 34, 'እርሱ ግን፥ “ጴጥሮስ ሆይ፥ እልሃለሁ፥ ዛሬ ዶሮ ሳይጮኽ እንደማታውቀኝ ሦስት ጊዜ ትክደኛለህ” አለው።'),
  ('c27b3e17-4eae-5ba3-a7ca-5830cc568c16', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 5, 35, 'ደግሞም፥ “ያለ ስልቻ፥ ያለ ከረጢትና ያለ ጫማ በላክኋችሁ ጊዜ በውኑ የተቸገራችሁት ነገር ነበርን?” አላቸው፤ እነርሱም፥ “የለም” አሉት።'),
  ('51edd8f1-a3b0-5a68-ac8f-32f13d15c18f', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 6, 36, 'እርሱም እንዲህ አላቸው፥ “አሁን ግን ኮሮጆ ያለው ኮሮጆውን ይያዝ፤ ከረጢትም ያለው እንዲሁ ያድርግ፤ ሰይፍ የሌለውም ልብሱን ሸጦ ሰይፍ ይግዛ።'),
  ('4d44b1de-4741-53d7-a836-8353a10b1d10', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 7, 37, 'እላችኋለሁ፥ ከኃጥኣን ጋር ተቈጠረ ተብሎ የተጻፈው በእኔ ይደርሳል፤ ስለ እኔ የተጻፈውም ሁሉ ይፈጸማል።”'),
  ('83f7f5cb-0569-594e-ab84-b931f472bc8f', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7bb367be-c94b-5f4d-a731-f94e17fa98e2', 8, 38, 'እነርሱም፥ “አቤቱ፥ እነሆ፥ እዚህ በእኛ ዘንድ ሁለት ሰይፎች አሉ” አሉት፤ እርሱም፥ “እንግዲያስ ይበቃችኋል” አላቸው።'),
  ('9c0a8339-6639-53ae-ac31-503a7e93cbe5', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 1, 39, 'ወጥቶም እንዳስለመደው ይጸልይ ዘንድ ወደ ደብረ ዘይት ሄደ፤ ደቀ መዛሙርቱም ተከተሉት።'),
  ('5223cfdc-9f9b-501f-a42b-afd211021f46', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 2, 40, 'ከዚያም ደርሶ፥ “ወደ መከራ እንዳትገቡ ጸልዩ” አላቸው።'),
  ('72667237-fe74-5afe-a70c-097ea0210a16', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 3, 41, 'የድንጋይ ውርወራ ያህልም ከእነርሱ ፈቀቅ ብሎ እየሰገደ ጸለየ።'),
  ('021e8e15-d5e1-599a-acaf-5d1ab0393fca', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 4, 42, 'እንዲህም አለ፥ “አባት ሆይ፥ ብትፈቅድስ ይህን ጽዋ ከእኔ አሳልፈው፤ ነገር ግን የአንተ ፈቃድ ይሁን እንጂ የእኔ ፈቃድ አይሁን።”'),
  ('7361ea2b-5fc3-5c8d-a5a3-9eb97e11f61f', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 5, 43, 'የሚያበረታታው የእግዚአብሔር መልአክም ከሰማይ ታየው።'),
  ('430f97f6-c5d3-5ee9-adee-0bc0f4b894cc', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 6, 44, 'ፈራ፤ መላልሶም ጸለየ፤ ላቡም በምድር ላይ እንደሚወርድ እንደ ደም ነጠብጣብ ሆነ።'),
  ('d79639af-ce9e-5400-a65b-579d0ffa5376', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 7, 45, 'ከሚጸልይበትም ተነሥቶ ወደ ደቀ መዛሙርቱ ሄደ፤ ከኀዘንም የተነሣ ተኝተው አገኛቸው።'),
  ('8dee7f59-235b-5bae-a83f-9475a9f26e78', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'e8e98455-54c8-57ab-a5a3-88e9d8cd2080', 8, 46, '“ስለ ምን ትተኛላችሁ? ወደ ፈተና እንዳትገቡ ተነሡና ጸልዩ” አላቸው።'),
  ('cefd881a-0184-55aa-aa7d-191bb08f0544', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 1, 47, 'ይህንም ሲነግራቸው ሕዝቡ ደረሱ፤ ከዐሥራ ሁለቱ ደቀ መዛሙርቱ አንዱ ይሁዳም ይመራቸው ነበር፤ ወደ ጌታችን ኢየሱስም ቀርቦ ሳመው፤ የሰጣቸውም ምልክት ይህ ነበር፤ “የምስመው እርሱ ነውና እርሱን አጽንታችሁ ያዙት” አላቸው።'),
  ('76b162e1-9695-5446-a98a-9ffe396cce8e', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 2, 48, 'ጌታችን ኢየሱስም ይሁዳን፥ “በመሳም የሰውን ልጅ አሳልፈህ ትሰጠዋለህን?” አለው።'),
  ('9deb940d-dff0-5cbf-a786-ef95638cd5ef', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 3, 49, 'አብረውት የነበሩትም የሆነውን ባዩ ጊዜ፥ ጌታችን ኢየሱስን፥ “አቤቱ፥ በሰይፍ ልንመታቸው ትፈቅዳለህን?” አሉት።'),
  ('0f4ccc7f-b6f8-5565-ae13-0ecc1623f29b', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 4, 50, 'ከእነርሱም አንዱ የሊቀ ካህናቱን አገልጋይ መታው፤ ቀኝ ጆሮውንም ቈረጠው።'),
  ('d2321efa-9cff-5a0a-a74f-530935af18f4', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 5, 51, 'ጌታችን ኢየሱስም መልሶ፥ “ይህንስ ተው” አለ፤ ወዲያውም ጆሮውን ዳስሶ አዳነው።'),
  ('719832f7-e276-518a-ad34-45a1b8f4750a', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 6, 52, 'ጌታችን ኢየሱስም ሊይዙት ወደ እርሱ የመጡትን የካህናት አለቆችን፥ የቤተ መቅደስ ሹሞችንና ሽማግሌዎችን እንዲህ አላቸው፥ “ሌባን እንደምትይዙ በሰይፍና በጎመድ ልትይዙኝ መጣችሁን?'),
  ('0a52b214-bba5-5187-a6f5-e5dc5deba975', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '18110652-7f1b-55f4-a0bd-ee9f973b1057', 7, 53, 'ዘወትርም ከእናንተ ጋር በቤተ መቅደስ ስኖር እጃችሁን እንኳ አልዘረጋችሁብኝም፤ ነገር ግን ጊዜያችሁ ይህ ነው፤ የጨለማው አበጋዝም ሥልጣኑ ይህ ነው።”'),
  ('9f55c15c-a1c1-5810-a337-20ec28bb6525', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 1, 54, 'ይዘውም ወደ ሊቀ ካህናቱ ቤት ወሰዱት፤ ጴጥሮስም ከሩቅ ይከተለው ነበር።'),
  ('6b7e6ad1-c602-561c-abe0-e355096aab03', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 2, 55, 'በግቢውም ውስጥ እሳት አንድደው ተቀመጡ፤ ጴጥሮስም አብሮአቸው በመካከላቸው ተቀመጠ።'),
  ('0415e2ca-aad2-55f0-aa56-2f402980435b', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 3, 56, 'በእሳቱም ብርሃን በኩል ተቀምጦ ሳለ አንዲት ብላቴና አየችው፤ እርሱ መሆኑንም ለየችውና፥ “ይህም ከእርሱ ጋር ነበር” አለች።'),
  ('b2423d29-6e88-58c4-a7bc-b34d68b7bdcf', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 4, 57, 'እርሱ ግን፥ “ሴትዮ! የምትዪውን አላውቅም” ብሎ ካደ።'),
  ('95ef8be1-c05a-5b93-ab7e-4224b3c3c8c9', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 5, 58, 'ከጥቂት ጊዜም በኋላ ሌላ ሰው አየውና፥ “አንተም ከእነርሱ ወገን ነህ” አለው፤ ጴጥሮስ ግን፥ “አንተ ሰው! እኔ አይደለሁም” አለው።'),
  ('ad8e32fa-c127-5aae-a032-44f3a6f24552', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 6, 59, 'አንዲት ሰዓት ያህልም ቈይቶ አንድ ሌላ ሰው፥ “ይህም በእውነት ከእርሱ ጋር ነበረ፤ ሰውየውም የገሊላ ሰው ነው” ብሎ አስጨነቀው።'),
  ('aa53a208-292e-5a8a-ae52-84c2f999f6f0', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 7, 60, 'ጴጥሮስ ግን፥ “አንተ ሰው! የምትለውን አላውቅም” አለው፤ እርሱም ይህን ሲናገር ያንጊዜ ዶሮ ጮኸ።'),
  ('e942678f-7449-523b-a77d-524c1d47f654', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 8, 61, 'ጌታችን ኢየሱስም ዘወር ብሎ ጴጥሮስን አየው፤ ጴጥሮስም፥ “ዛሬ ዶሮ ሳይጮኽ ሦስት ጊዜ ትክደኛለህ” ያለውን የጌታችንን ቃል ዐሰበ።'),
  ('c2c36eb9-4caa-5c05-a129-4ef349d1e144', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '33df00ca-2361-5150-a2d6-2f409a801caf', 9, 62, 'ጴጥሮስም ወደ ውጭ ወጥቶ መራራ ልቅሶን አለቀሰ።'),
  ('51882b48-5e67-5b49-ad52-c8b88e5eed38', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'a794d2b1-cdb4-533d-af72-8a5bbf95cee6', 1, 63, 'ጌታችን ኢየሱስን ይዘውት የነበሩት ሰዎችም ይዘባበቱበትና ይደበድቡት ነበር።'),
  ('ed119c78-0e96-5ac9-ac6f-679bfe8daa8d', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'a794d2b1-cdb4-533d-af72-8a5bbf95cee6', 2, 64, 'ሸፍነውም ፊቱን በጥፊ ይመቱት ነበር፤ “ፊትህን በጥፊ የመታህ ማነው? ንገረን” እያሉም ይጠይቁት ነበር።'),
  ('525a9665-f19b-55a3-ab60-66cacf893816', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', 'a794d2b1-cdb4-533d-af72-8a5bbf95cee6', 3, 65, 'ሌላም ብዙ ነገር እየተሳደቡ በእርሱ ላይ ይናገሩ ነበር።'),
  ('efad458f-aca5-5d7d-ab39-b01d07390456', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7b58577e-5f3c-5025-a25f-a840154f4898', 1, 66, 'በነጋም ጊዜ፥ የካህናት አለቆች፥ ጻፎችና የሕዝቡ ሽማግሌዎች ተሰብስበው ወደ ሸንጎአቸው ወሰዱት።'),
  ('f090da50-b1ee-5596-a618-fbfd71bfb69a', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7b58577e-5f3c-5025-a25f-a840154f4898', 2, 67, '“አንተ ክርስቶስ እንደ ሆንህ በግልጥ ንገረን” አሉት፤ እርሱም እንዲህ አላቸው፥ “ብነግራችሁም አታምኑኝም።'),
  ('564694ab-e747-5560-adf8-d6fe06cde85f', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7b58577e-5f3c-5025-a25f-a840154f4898', 3, 68, 'ብጠይቃችሁም አትመልሱልኝም፤ ወይም አትተዉኝም።'),
  ('0cab6bc3-bc0a-5b0c-aa58-3094c182d376', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7b58577e-5f3c-5025-a25f-a840154f4898', 4, 69, 'ነገር ግን ከእንግዲህ ወዲህ የሰው ልጅ በእግዚአብሔር ኀይል ቀኝ ይቀመጣል።”'),
  ('a6d67aac-7e61-5b3c-afd4-0c1acedd7f28', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7b58577e-5f3c-5025-a25f-a840154f4898', 5, 70, 'ሁሉም፥ “እንግዲያስ አንተ የእግዚአብሔር ልጅ ነህን?” አሉት፤ እርሱም፥ “እኔ የእግዚአብሔር ልጅ እንደ ሆንሁ እናንተ ትላላችሁ” አላቸው።'),
  ('8876237c-df61-5391-af3d-b6aa168342c9', 'a5fe83a0-8e1d-5ba9-ab61-e383083136ee', '7b58577e-5f3c-5025-a25f-a840154f4898', 6, 71, 'እነርሱም፥ “ስለ እርሱ ምን ምስክር እንሻለን? እኛ ራሳችን ሲናገር ሰምተናል” አሉ።'),
  ('1358fd1a-e9e4-512c-a7d4-e3c51a1b165f', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'f9e47df3-aef6-5d44-a6a4-dd9bfecda606', 1, 1, 'ሁሉም በሙሉ ተነሥተው ወደ ጲላጦስ ወሰዱት።'),
  ('1c3f3bea-e5e0-564a-ab8c-9164679ca772', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'f9e47df3-aef6-5d44-a6a4-dd9bfecda606', 2, 2, 'እንዲህም እያሉ ይከስሱት ጀመር፥ “ይህ ሰው ለቄሣር ግብር እንዳይሰጡ ሲከለክልና ሕዝቡን ሲያሳምፅ፥ ራሱንም የእስራኤል ንጉሥ ክርስቶስን ሲያደርግ አገኘነው።”'),
  ('0fa1b8b3-12a6-5d6b-a345-7f3a28a03282', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'f9e47df3-aef6-5d44-a6a4-dd9bfecda606', 3, 3, 'ጲላጦስም፥ “አንተ የአይሁድ ንጉሥ ነህን?” ብሎ ጠየቀው፤ ጌታችን ኢየሱስም፥ “እኔ እንደ ሆንሁ አንተ አልህ” አለው።'),
  ('2d9ff9e0-c84c-587a-a4f7-0aace9d40e9e', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'f9e47df3-aef6-5d44-a6a4-dd9bfecda606', 4, 4, 'ጲላጦስም ለካህናት አለቆችና ለሕዝቡ፥ “በዚህ ሰው ላይ ያገኘሁት አንድስ እንኳ በደል የለም” አላቸው።'),
  ('14641b89-bc14-5db4-a51c-77ca092c1ff9', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'f9e47df3-aef6-5d44-a6a4-dd9bfecda606', 5, 5, 'ሕዝቡም፥ “ከገሊላ ጀምሮ እስከዚህ ድረስ በመላው ይሁዳ እያስተማረ ሕዝቡን ያውካል” እያሉ አጽንተው ጮኹ።'),
  ('b946e02b-50bd-54fa-a9c0-696e8dd449bc', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 1, 6, 'ጲላጦስም “ገሊላ” ሲሉ ሰምቶ፤ ሰውየዉ ገሊላዊ እንደ ሆነ የገሊላን ሰዎች ጠየቀ።'),
  ('fb1e42d9-eb79-51fd-aed1-991d9ad0a742', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 2, 7, 'ከሄሮድስ ግዛትም ውስጥ መሆኑን ዐውቆ ወደ ሄሮድስ ላከው፤ ሄሮድስ በዚያ ወራት በኢየሩሳሌም ነበርና።'),
  ('f0bdbcda-25fa-5448-a62f-acc1044f81ee', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 3, 8, 'ሄሮድስም ጌታችን ኢየሱስን ባየው ጊዜ እጅግ ደስ አለው፤ ዜናውን ስለሚሰማ ከረጅም ጊዜ ጀምሮ ሊያየው ይሻ ነበርና፤ የሚያደርገውንም ተአምራት ሊያይ ይመኝ ነበርና።'),
  ('c5997282-06cb-54f8-a986-2f9ac03f5df9', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 4, 9, 'በብዙ ነገርም መረመረው፤ እርሱ ግን አንድስ እንኳ አልመለሰለትም።'),
  ('7f65f0b5-9f12-5c91-a0da-c8a852fdaf7c', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 5, 10, 'የካህናት አለቆችና ጻፎችም ቆመው በብዙ ያሳጡት ነበር።'),
  ('c59317f5-b5e7-5a44-aa58-316715b8d61a', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 6, 11, 'ሄሮድስም ከሠራዊቱ ጋር አቃለለው፤ አፌዘበትም፤ የሚያንፀባርቅ ልብስም አልብሶ ወደ ጲላጦስ መልሶ ሰደደው።'),
  ('d48e2175-a5b3-5e05-a620-b98649630ce9', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 7, 12, 'በዚያም ቀን ሄሮድስና ጲላጦስ ተስማሙ፤ ቀድሞ ጥል ነበራቸውና።'),
  ('8aa108ce-7831-556c-a7d6-2abbcd66fe65', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 8, 13, 'ጲላጦስም የካህናት አለቆችንና መኳንንቱን፥ ሕዝቡንም ጠራቸው።'),
  ('066bc767-314b-5799-aa77-9bf37fb8b3bf', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 9, 14, 'እንዲህም አላቸው፥ “ይህን ሰው ሕዝብን ያሳምፃል ብላችሁ ወደ እኔ አመጣችሁት፤ በፊታችሁም እነሆ፥ መረመርሁት፤ ግን እናንተ ካቀረባችሁት ክስ በዚህ ሰው ላይ ያገኘሁት አንዳች በደል የለም።'),
  ('4f8742dd-f2ab-5648-a336-543312106c09', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 10, 15, 'ወደ ሄሮድስም ሰድጃችሁ ነበር፤ እርሱም ምንም ስላላገኘበት ወደ እኛ መልሶታል፤ ለሞትም የሚያበቃ ያደረገው ነገር የለም።'),
  ('d9f61535-7d2f-5bd4-a018-59d1407d2bf3', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '9ef790d7-b01e-5405-a123-0d64913e2d39', 11, 16, 'እነሆ፥ እኔም እንግዲህ ገርፌ ልተወው” አለ።'),
  ('5dd6ec0e-e8fd-5388-af62-c19ffb0cb2a9', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 1, 17, 'በየበዓሉም ከእስረኞች አንድ ሊፈታላቸው ልማድ ነበር።'),
  ('b3610a5e-a2a0-5f39-aa38-a72b113a4bf3', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 2, 18, 'ሁሉም በሙሉ፥ “ይህን አስወግደው፥ ስቀለውም፥ በርባንን ግን ፍታልን” ብለው ጮሁ።'),
  ('aac73f07-dd0c-5e28-a974-ceb27f29e5fd', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 3, 19, 'ያ በርባን ግን በከተማ ሁከት ያደረገና ነፍስ በመግደል የታሰረ ነበር።'),
  ('07b1774c-749b-544e-a4c0-575171218acf', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 4, 20, 'ጲላጦስም ኢየሱስን ሊፈታው ወድዶ፥ “ ኢየሱስን ልፈታላችሁ ትወዳላችሁን?” ብሎ እንደ ገና ተናገራቸው።'),
  ('ca3f4075-b337-5e1a-aca6-ca7969a527ea', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 5, 21, 'እነርሱ ግን፥ “ስቀለው! ስቀለው!” እያሉ ይጮሁ ነበር።'),
  ('89e0c6c6-1e6f-5a0c-abd9-d6aa72932577', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 6, 22, 'ጲላጦስም ለሦስተኛ ጊዜ፥ “ምን ክፉ ነገር አደረገ? እነሆ፥ ለሞት የሚያበቃ ምክንያት አላገኘሁበትም፤ እንኪያስ ልግረፈውና ልተወው” አላቸው።'),
  ('bcf0093d-b7ae-5f4d-a348-be8630df6485', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 7, 23, 'እንዲሰቅሉትም ቃላቸውን ከፍ አድርገው እየጮሁ ለመኑ፤ ጩኸታቸውና የካህናት አለቆች ድምፅም በረታ።'),
  ('a5d4ba5a-300a-5319-a1a8-bf2c492be2a7', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 8, 24, 'ጲላጦስም የለመኑት ይሆንላቸው ዘንድ ፈረደበት።'),
  ('2aba6a1a-d483-5e7b-af63-775d4238da1e', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6006733f-9e1c-53b0-ad59-3de6ccfbf1fd', 9, 25, 'ያን የለመኑትን፥ ነፍስ በመግደልና ሁከት በማድረግ የታሰረውንም ሰው ፈታላቸው፤ ኢየሱስን ግን ለፈቃዳቸው አሳልፎ ሰጣቸው።'),
  ('9ae49b87-8758-53dd-a5f2-9e87f2b9021f', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '3c134ed5-6a6a-575c-ae0a-e1d93eb1a4d6', 1, 26, 'በወሰዱትም ጊዜ የቀሬና ሰው ስምዖንን ከዱር ሲመለስ ያዙት፤ ከጌታችን ከኢየሱስም በስተኋላ መስቀሉን አሸከሙት።'),
  ('58f5e9bd-4cca-5c1a-a511-e6ab0eb4a5d8', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '3c134ed5-6a6a-575c-ae0a-e1d93eb1a4d6', 2, 27, 'ብዙ ሰዎችም ተከተሉት፤ ሴቶችም “ዋይ ዋይ” እያሉ ያዝኑለትና ያለቅሱለት ነበሩ።'),
  ('fe1982e9-41e9-5243-ade1-91df6febc47f', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '3c134ed5-6a6a-575c-ae0a-e1d93eb1a4d6', 3, 28, 'ጌታችን ኢየሱስም መለስ ብሎ እንዲህ አላቸው፥ “እናንተ የኢየሩሳሌም ልጆች ሆይ፥ ለራሳችሁና ለልጆቻችሁ አልቅሱ እንጂ ለእኔስ አታልቅሱልኝ።'),
  ('27929808-ab7f-5118-a70f-26b42389ce06', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '3c134ed5-6a6a-575c-ae0a-e1d93eb1a4d6', 4, 29, 'መካኖች፥ ያልወለዱ ማኅፀኖችና ያላጠቡ ጡቶችም የተመሰገኑ ናቸው የሚሉበት ወራት ይመጣልና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('182cd644-fbd7-5454-abb8-48a7e6c21677', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '3c134ed5-6a6a-575c-ae0a-e1d93eb1a4d6', 5, 30, 'ያንጊዜም ተራሮችን ‘በላያችን ውደቁ፤ ኮረብቶችንም ሰውሩን’ ይሉአቸዋል።'),
  ('1a5749ab-8c8a-5b92-aa2e-350b8fb668a7', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '3c134ed5-6a6a-575c-ae0a-e1d93eb1a4d6', 6, 31, 'በዚህ ርጥብ ዕንጨት እንዲህ ያደረጉ በደረቁማ እንዴት ይሆን?”'),
  ('d20c06fd-d55c-55fa-a8e1-c851cb457726', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 1, 32, 'ሌሎች ሁለት ወንበዴዎችንም ከእርሱ ጋር ሊሰቅሉ ወሰዱ።'),
  ('b86b794c-c349-562c-a9e9-f37f8bc68fc1', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 2, 33, 'ቀራንዮ ወደሚባለው ቦታ በደረሱ ጊዜም፥ በዚያ ሰቀሉት፤ እነዚያንም ሁለት ወንበዴዎች አንዱን በቀኙ አንዱንም በግራው ሰቀሉ።'),
  ('1a098fdd-9428-5a28-a3bd-6049be3dd5bd', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 3, 34, 'ጌታችን ኢየሱስም፥ “አባት ሆይ፥ የሚያደርጉትን ኣያውቁምና ይቅር በላቸው” አለ፤ በልብሱም ላይ ዕጣ ተጣጣሉና ተካፈሉ።'),
  ('9f1da8da-dabc-53fd-a85e-3d107169ac4a', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 4, 35, 'ሕዝቡም ቆመው ይመለከቱ ነበር፤ አለቆችም፥ “ሌሎችን አዳነ፤ በእግዚአብሔር የተመረጠ ክርስቶስ ከሆነ ራሱን ያድን” እያሉ ያፌዙበት ነበር።'),
  ('03194350-5109-5c69-aa1b-dc6983ca4ce4', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 5, 36, 'ጭፍሮችም ይዘብቱበት ነበር፤ ወደ እርሱም ቀርበው ሆምጣጤ አመጡለት።'),
  ('262b4073-cec3-5082-a128-bb2a2605b198', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 6, 37, 'እንዲህም ይሉት ነበር፥ “አንተ የአይሁድ ንጉሥ ከሆንህስ ራስህን አድን።”'),
  ('75386a8b-49d6-5e3c-a671-a77af53bae30', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '239cea19-21f3-5d71-a001-865a5fc3248a', 7, 38, 'በራስጌውም ደብዳቤ ጻፉ፤ ጽሕፈቱም በሮማይስጥ፥ በጽርዕና በዕብራይስጥ ሆኖ “የአይሁድ ንጉሣቸው ይህ ነው” የሚል ነበር።'),
  ('f82ceb3f-61c9-5558-a208-6a8748505b7f', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'a36f57c9-7fbe-5592-aca6-2e2c462e6acf', 1, 39, 'አብረው ተሰቅለው ከነበሩት አንዱ ወንበዴ፥ “አንተስ ክርስቶስ ከሆንህ ራስህን አድን፤ እኛንም አድነን” ብሎ ተሳደበ።'),
  ('c49f6898-4143-5974-a662-767d6fd8132a', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'a36f57c9-7fbe-5592-aca6-2e2c462e6acf', 2, 40, 'ጓደኛውም መልሶ ገሠጸው፤ እንዲህም አለው፥ “አንተ በዚህ ፍርድ ውስጥ ሳለህ እግዚአብሔር አምላክህን አትፈራውምን?'),
  ('66aa1e49-d964-5b74-aaf6-f70c9c875eaf', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'a36f57c9-7fbe-5592-aca6-2e2c462e6acf', 3, 41, 'በእኛስ በሚገባ ተፈርዶብናል፤ እንደ ሥራችንም ፍዳችንን ተቀበልን፤ ይህ ግን ምንም የሠራው ክፉ ሥራ የለም።”'),
  ('e61be7c8-097a-53d7-a258-04f876ed7172', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'a36f57c9-7fbe-5592-aca6-2e2c462e6acf', 4, 42, 'ጌታችን ኢየሱስንም፥ “አቤቱ፥ በመንግሥትህ በመጣህ ጊዜ ዐስበኝ” አለው።'),
  ('9addd71a-6faf-5c2f-aa0a-ecce61ed7e4f', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', 'a36f57c9-7fbe-5592-aca6-2e2c462e6acf', 5, 43, 'ጌታችን ኢየሱስም መልሶ እንዲህ አለው፥ “እውነት እልሃለሁ፥ ዛሬ በገነት ከእኔ ጋር ትሆናለህ።”'),
  ('085a9361-6d1b-5275-aef0-3690953fb834', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '38952a9a-cf1f-527f-adb2-34f647727f4e', 1, 44, 'ቀትር በሆነ ጊዜም በስድስት ሰዓት ፀሐይ ጨለመ፤ እስከ ዘጠኝ ሰዓት ድረስም ዓለም ሁሉ ጨለማ ሆነ።'),
  ('0922227e-ffaa-5d9a-a305-53c71010dcd0', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '38952a9a-cf1f-527f-adb2-34f647727f4e', 2, 45, 'ፀሐዩም በጨለመ ጊዜ የቤተ መቅደሱ መጋረጃ ከላይ እስከ ታች ከመካከሉ ተቀደደ።'),
  ('f235d6fd-792c-5037-a0f1-96620ccb67b9', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '38952a9a-cf1f-527f-adb2-34f647727f4e', 3, 46, 'ያንጊዜም ጌታችን ኢየሱስ ድምፁን ከፍ አድርጎ፥ “አባት ሆይ፥ ነፍሴን በአንተ እጅ አደራ እሰጣለሁ” ብሎ ጮኸ፤ ይህንም ብሎ ነፍሱን ሰጠ።'),
  ('a683b848-2cb9-51b4-a209-ef7e087c2b3c', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '38952a9a-cf1f-527f-adb2-34f647727f4e', 4, 47, 'የመቶ አለቃውም የሆነውን ነገር አይቶ፥ “ይህ ሰው በእውነት ጻድቅ ነበረ”ብሎ እግዚአብሔርን አመሰገነው።'),
  ('28e616ae-c07f-5ca9-aad0-124f2076443a', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '38952a9a-cf1f-527f-adb2-34f647727f4e', 5, 48, 'ይህንም ለማየት ተሰብስበው የነበሩት ሕዝብ ሁሉ የሆነውን ባዩ ጊዜ፥ ደረታቸውን እየመቱ ወደ ቤታቸው ተመለሱ።'),
  ('26f2548a-b745-58a5-a3e1-a6a4e4293c50', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '38952a9a-cf1f-527f-adb2-34f647727f4e', 6, 49, 'የሚያውቁት ሁሉና ከገሊላ ጀምሮ የተከተሉትም ሴቶች በሩቁ ቆመው ይህን ያዩ ነበር።'),
  ('e390f8d7-ec4e-5f6f-ab65-56442e0c8be8', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6b645043-b3cb-5da5-a1eb-4adf1a8152e3', 1, 50, 'እነሆ፥ በጎና ጻድቅ ሰው፥ የሸንጎ አማካሪም የሆነ ዮሴፍ የሚባል ሰው መጣ።'),
  ('fb331529-24e7-54a8-afee-7d7daaa9aefc', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6b645043-b3cb-5da5-a1eb-4adf1a8152e3', 2, 51, 'እርሱም በአይሁድ በምክራቸውና በሥራቸው አልተባበረም ነበር፤ ሀገሩም የይሁዳ ዕጣ የሚሆን አርማትያስ ነበር፤ እርሱም የእግዚአብሔርን መንግሥት ተስፋ ያደርግ ነበር።'),
  ('8b468c71-1fb1-53cc-a2db-d3ac7ee525ae', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6b645043-b3cb-5da5-a1eb-4adf1a8152e3', 3, 52, 'ወደ ጲላጦስም ሄዶ የጌታችን የኢየሱስን ሥጋ ለመነ።'),
  ('cb0b6d50-e893-5b8c-a2c3-bdeef285b61c', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6b645043-b3cb-5da5-a1eb-4adf1a8152e3', 4, 53, 'ሥጋውንም አውርዶ በበፍታ ገነዘው፤ ማንም ባልተቀበረበት፥ ከድንጋይም በተፈለፈለ መቃብር ቀበረው፤ ታላቅ ድንጋይም አንከባልሎ መቃብሩን ገጥሞ ሄደ።'),
  ('20a0d403-d863-53a4-a465-bfce94e71826', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6b645043-b3cb-5da5-a1eb-4adf1a8152e3', 5, 54, 'ያም ቀን የሰንበት መግቢያ ዐርብ ነበር።'),
  ('8d5cdd82-5d51-5aa9-a9b2-c126479c6995', 'd5481a2f-76da-5ef4-a3bd-04eec522f5c5', '6b645043-b3cb-5da5-a1eb-4adf1a8152e3', 6, 55, 'ከገሊላም ከእርሱ ጋር የመጡ ሁለት ሴቶች ተከትለው፥ መቃብሩን፥ ሥጋውንም እንዴት እንዳኖሩት አዩ። ተመልሰውም ሽቱና ዘይት አዘጋጁ፤ ነገር ግን በሰንበት አልሄዱም፤ ሕጋቸው እንዲህ ነበርና።'),
  ('40ce9f51-676e-5b8b-a704-63cbef9a18f0', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 1, 1, 'ከሳምንቱም በመጀመሪያዪቱ ቀን ያዘጋጁትን ሽቶ ይዘው እጅግ ማልደው ወደ መቃብሩ ሄዱ፤ ሌሎች ሴቶችም አብረዋቸው ነበሩ።'),
  ('21089dc1-7e70-57e1-af8e-2b68515741e5', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 2, 2, 'ያቺንም ድንጋይ ከመቃብሩ ላይ ተንከባልላ አገኙአት።'),
  ('b2bc03f4-d6fe-59c1-aad1-5f1ea098356e', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 3, 3, 'ገብተውም የጌታችን የኢየሱስን ሥጋ አላገኙም።'),
  ('b875a197-2780-5edc-ad84-158aae982b49', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 4, 4, 'ስለዚህም ነገር የሚሉትን አጥተው ሲያደንቁ ሁለት ሰዎች ከፊታቸው ቆመው ታዩአቸው፤ ልብሳቸውም ያብረቀርቅ ነበር።'),
  ('44d8b12f-4eeb-5c50-aceb-5e63afb16311', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 5, 5, 'ፈርተውም ፊታቸውን ወደ ምድር አቀረቀሩ። እነርሱም እንዲህ አሉአቸው፥ “ሕያዉን ከሙታን ጋር ለምን ትሹታላችሁ?'),
  ('807a920f-ad72-56c4-adfa-31f1693e3277', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 6, 6, 'በዚህ የለም፤ ተነሥቶአል። በገሊላ ሳለ ለእናንተ እንዲህ ሲል የተናገረውን ዐስቡ፦'),
  ('6c9301a5-8bb2-5301-a4f2-63f93f7c5929', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 7, 7, 'የሰው ልጅ በኀጢኣተኞች ሰዎች እጅ ተላልፎ ይሰጥ ዘንድ አለው፤ ይሰቅሉታል፤ ይገድሉታል፤ በሦስተኛውም ቀን ይነሣል።” 10፥33-34፤ ሉቃ. 9፥22፤ 18፥31-33።'),
  ('ba7e73b5-c4d4-5191-a642-8ba17a5d4749', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 8, 8, 'ቃሉንም ዐሰቡ።'),
  ('1ea2e332-9277-536f-abc3-35e636ad64de', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 9, 9, 'ከመቃብርም ተመልሰው ለዐሥራ አንዱና ለቀሩት ባልንጀሮቻቸው ሁሉ ይህን ነገር ነገሩአቸው።'),
  ('38f5f2c8-5e4b-5331-ac56-69b2dc95943f', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 10, 10, 'እነዚያም መግደላዊት ማርያም፥ ዮሐና፥ የያዕቆብ እናት ማርያም፥ አብረዋቸው የነበሩት ባልንጀሮቻቸውም ይህን ለሐዋርያት ነገሩአቸው።'),
  ('286fd523-17e0-57c0-aea4-3b710921cb53', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 11, 11, 'ይህም ነገር በፊታቸው እንደ ተረት መሰላቸውና አላመኑአቸውም።'),
  ('d994208d-8690-5035-a52b-52620bd780f5', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '68230949-3272-5743-aa29-1f29b9297025', 12, 12, 'ጴጥሮስም ተነሣ፤ ወደ መቃብርም ፈጥኖ ሄደ፤ ዝቅ ብሎም በተመለከተ ጊዜ በፍታውን ለብቻው ተቀምጦ አየ፤ የሆነውንም እያደነቀ ተመለሰ።'),
  ('93447a9d-2909-522f-a0e5-ee5ce03557b4', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 1, 13, 'በዚያም ቀን ከመካከላቸው ሁለት ሰዎች ከኢየሩሳሌም ስድሳ ምዕራፍ ያህል ወደምትርቀው ኤማሁስ ወደምትባለው መንደር ሄዱ።'),
  ('588bc895-db7f-5404-af1c-8809fd166131', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 2, 14, 'እርስ በርሳቸውም ስለ ሆነው ነገር ሁሉ ይነጋገሩ ነበር።'),
  ('b17314f6-9d6d-56f0-a771-e26742e410f8', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 3, 15, 'እነርሱም ይህን ሲነጋገሩና ሲመራመሩ ጌታችን ኢየሱስ ወደ እነርሱ ቀረበ፤ አብሮአቸውም ሄደ።'),
  ('da678507-c48a-5801-a549-80457e03286d', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 4, 16, 'እንዳያውቁትም ዐይናቸው ተይዞ ነበር።'),
  ('bcf2dbc6-e6ea-5b36-a5da-47c30eeb8ff7', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 5, 17, 'ጌታችንም፥ “በትካዜ እየሄዳችሁ እርስ በርሳችሁ የምትነጋገሩት ይህ ነገር ምንድን ነው?” አላቸው።'),
  ('4d4e4580-a4f2-5742-a9e5-24f17ca9c698', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 6, 18, 'ከእነርሱም ቀለዮጳ የሚባለው አንዱ መልሶ፥ “አንተ ብቻ ለኢየሩሳሌም እንግዳ ነህን? በእነዚህ ቀኖችስ በውስጥዋ የተደረገውን አታውቅምን?” አለው።'),
  ('653af806-7ea6-5400-a2c5-f9d3e870eb9f', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 7, 19, 'ጌታችን ኢየሱስም፥ “ይህ ምንድነው?” አላቸው፤ እነርሱም እንዲህ አሉት፥ “በእግዚአብሔር ፊትና በሕዝቡ ሁሉ ፊት በቃሉና በሥራው ብርቱ ነቢይና እውነተኛ ሰው ስለነበረው ስለ ናዝሬቱ ስለ ኢየሱስ፥'),
  ('233daed0-818e-52d0-ad32-053c354b4563', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 8, 20, 'የካህናት አለቆችና መኳንንቶቻችን አሳልፈው እንደ ሰጡት፥ ሞትም እንደ ፈረዱበትና እንደ ሰቀሉት ነው።'),
  ('d51d5fc9-1206-5cb2-afb4-467c255dfcb7', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 9, 21, 'እኛ ግን እስራኤልን ያድናቸው ዘንድ ያለው እርሱ እንደ ሆነ ተስፋ እናደርግ ነበር፤ ከዚህም ሁሉ ጋር ይህ ነገር ከሆነ ዛሬ ሦስተኛ ቀን ነው።'),
  ('42259654-0dfb-522f-a3cc-d1b6a4a6062d', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 10, 22, 'ደግሞም ሴቶች ከእኛ ዘንድ ወደ መቃብር ገስግሠው ሄደው ነበርና አስደንቀው ነገሩን።'),
  ('94790229-d11c-54ae-aec8-28962a7afecf', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 11, 23, 'ሥጋውንም በአላገኙ ጊዜ ተመልሰው፦ ተነሥቶአል ያሉአቸውን የመላእክትን መልክ እንደ አዩ ነገሩን።'),
  ('322155da-319b-585a-ace9-8b989f3336cd', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 12, 24, 'ከእኛም ዘንድ ወደ መቃብር ሄደው እንዲሁ ሴቶች እንደ ተናገሩት ሆኖ ያገኙት አሉ፤ እርሱን ግን አላዩትም።”'),
  ('058d30aa-3fee-5d38-a935-836c4ee31712', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 13, 25, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “እናንተ ሰነፎች፥ ነቢያትም የተናገሩትን ነገር ሁሉ ከማመን ልባችሁ የዘገየ፥'),
  ('912a171e-5ae5-52f0-ac88-4dadf536ba3f', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 14, 26, 'ክርስቶስ እንዲህ ይሞት ዘንድ ወደ ክብሩም ይመለስ ዘንድ ያለው አይደለምን?”'),
  ('15b73efa-1097-52dc-a2ea-f1a5c235eadd', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 15, 27, 'እርሱም ከሙሴና ከነቢያት፥ ከመጻሕፍትም ሁሉ ስለ እርሱ የተነገረውን ይተረጕምላቸው ጀመር።'),
  ('bab35ca9-a39d-5b57-a911-c06a1cba364b', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 16, 28, 'ሊሄዱባት ወደ ነበረችው መንደርም ተቃረቡ፤ እርሱ ግን ይርቃቸው ጀመር።'),
  ('101f78d9-8c80-514b-ae32-cf3cc0d5434f', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 17, 29, 'እነርሱም፥ “መሽቶአልና፥ ፀሐይም ተዘቅዝቆአልና፥ ከእኛ ጋር እደር” ብለው ግድ አሉት፤ ከእነርሱም ጋር ሊያድር ገባ።'),
  ('c9fed943-6e78-5201-a2fa-43217d37a9a5', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 18, 30, 'ከዚህም በኋላ አብሮአቸው ለማዕድ ተቀምጦ ሳለ እንጀራውን አንሥቶ ባረከ፤ ቈርሶም ሰጣቸው።'),
  ('21af467b-17d9-5779-a9af-af7909fc8f5a', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 19, 31, 'ዐይናቸውም ተገለጠና ዐወቁት፤ ወዲያውኑም ከእነርሱ ተሰወረ።'),
  ('7ab9b25f-0ac0-51c9-a579-cf7dcf458194', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b3cd1c00-45c5-5388-a2a3-c294de62badf', 20, 32, 'እርስ በርሳቸውም እንዲህ አሉ፥ “በመንገድ ሲነግረን፥ መጻሕፍትንም ሲተረጕምልን ልባችን ይቃጠልብን አልነበረምን?”'),
  ('beabf980-b4f6-59a5-a7ce-34dc1b5d2ba0', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '4e95fba4-8713-5baa-ad9b-b72b57abe961', 1, 33, 'በዚያችም ሰዓት ተነሥተው ወደ ኢየሩሳሌም ተመለሱ፤ ዐሥራ አንዱን ደቀ መዛሙርትና አብረዋቸው የነበሩትንም ተሰብስበው አገኙአቸው፤'),
  ('334a12fc-e1b3-5d35-a3ba-45ec8a7ee908', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '4e95fba4-8713-5baa-ad9b-b72b57abe961', 2, 34, 'እንዲህ እያሉ፥ “ጌታችን በእውነት ተነሥቶአል፤ ለስምዖንም ታይቶታል።”'),
  ('52030f92-da1c-5ca6-a873-c108608f8941', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '4e95fba4-8713-5baa-ad9b-b72b57abe961', 3, 35, 'እነርሱም በመንገድ የሆነውንና እንጀራውን ሲቈርስ ጌታችንን እንዴት እንዳወቁት ነገሩአቸው።'),
  ('f6e45c04-e25d-56b8-a96a-6a64f91ece3a', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 1, 36, 'ይህንም ሲነጋገሩ ጌታችን ኢየሱስ በመካከላቸው ቆመና፥ “ሰላም ለእናንተ ይሁን፤ አትፍሩ፤ እኔ ነኝ” አላቸው።'),
  ('67b6c4ae-ad5e-5d85-a2ee-bb65ad283572', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 2, 37, 'እነርሱ ግን ፈሩ፤ ደነገጡም፤ ምትሐትንም የሚያዩ መሰላቸው።'),
  ('6c111320-e037-560e-a947-dab3f95fe753', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 3, 38, 'እርሱም እንዲህ አላቸው፥ “ምን ያስደነግጣችኋል? በልባችሁስ እንዲህ ያለ ዐሳብ ለምን ይነሣሣል?'),
  ('6cb630d6-a3bb-5442-a0ae-4d9770e2f230', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 4, 39, 'እጄንና እግሬን እዩ፤ ዳስሱኝም፤ እኔ እንደ ሆንሁም ዕወቁ፤ በእኔ እንደምታዩት ለምትሐት አጥንትና ሥጋ የለውምና።”'),
  ('9ad40153-694f-58b7-a142-bfd55325bedd', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 5, 40, 'ይህንም ብሎ እጆቹንና እግሮቹን አሳያቸው።'),
  ('40facc24-351e-5b77-ac08-7daf557b57ae', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 6, 41, 'ከድንጋጤ የተነሣም ገና ሳያምኑ ደስ ብሎአቸውም ሲያደንቁ ሳሉ፥ “በዚህ አንዳች የሚበላ አላችሁን?” አላቸው።'),
  ('434566c4-5d67-5724-a92d-71dc169e8685', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 7, 42, 'እነርሱም ከተጠበሰ ዓሣ አንድ ቁራጭ፤ ከማር ወለላም ጥቂት ሰጡት።'),
  ('569e120b-c4bd-5489-a71b-87798ff2e563', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 8, 43, 'ተቀብሎም በፊታቸው በላ፤ የተረፈውንም አንሥቶ ሰጣቸው።'),
  ('e0b9bf51-2061-5a22-a124-637cbfd22f85', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 9, 44, 'እርሱም፥ “በሙሴ ኦሪት፥ በነቢያትና በመዝሙርም ስለ እኔ የተነገረው ይፈጸም ዘንድ እንዳለው፥ ከእናንተ ጋር ሳለሁ የነገርኋችሁ ነገሬ ይህ ነው” አላቸው።'),
  ('27b29cab-7545-5c65-aefb-87a54bce78ea', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 10, 45, 'ከዚህም በኋላ መጻሕፍትን እንዲያስተውሉ አእምሮአቸውን ከፈተላቸው።'),
  ('e863f55a-4acc-58bd-a5dd-f5204ebac99d', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 11, 46, 'እንዲህም አላቸው፥ “ክርስቶስ እንዲሞት በሦስተኛውም ቀን ከሙታን ተለይቶ እንዲነሣ፥'),
  ('0195ecf3-9cf5-554c-aead-2a8d4887a278', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 12, 47, 'ንስሓና የኀጢኣት ስርየት ከኢየሩሳሌም ጀምሮ በአሕዛብ ሁሉ እንዲሰበክ እንዲሁ ተጽፎአል።'),
  ('6d4531e7-3514-52a1-a4d5-2c4efbb9e8bd', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 13, 48, 'እናንተም ለዚህ ነገር ምስክሮች ናችሁ።'),
  ('2f63be4a-1828-53af-a858-383108c03d7a', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', '5e6bf492-c6fd-5c58-a83a-415e966d483f', 14, 49, 'እነሆ፥ እኔ የአባቴን ተስፋ ለእናንተ እልካለሁ፤ እናንተ ግን ከአርያም ኀይልን እስክትለብሱ ድረስ በኢየሩሳሌም ከተማ ተቀመጡ።”'),
  ('c9e0e248-5d26-539d-ad34-3eb58f7b641d', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b99006c5-a5e8-5520-a0ec-5c87d812e39d', 1, 50, 'እስከ ቢታንያም ወደ ውጭ አወጣቸው፤ እጁንም አንሥቶ በላያቸውም ጭኖ ባረካቸው።'),
  ('e42b6956-e64c-507b-a200-ceeb74c5ed0b', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b99006c5-a5e8-5520-a0ec-5c87d812e39d', 2, 51, 'እየባረካቸውም ራቃቸው፤ ወደ ሰማይም ዐረገ።'),
  ('fec730f2-12c9-5a59-a50f-4250386a24e0', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b99006c5-a5e8-5520-a0ec-5c87d812e39d', 3, 52, 'እነርሱም ሰገዱለትና በታላቅ ደስታ ወደ ኢየሩሳሌም ተመለሱ።'),
  ('f413cf37-5649-50eb-ad15-fbccc28f210d', 'e8286e65-40cf-5e5f-ab0f-1247699f62fd', 'b99006c5-a5e8-5520-a0ec-5c87d812e39d', 4, 53, 'በቤተ መቅደስም ዘወትር እግዚአብሔርን እያመሰገኑና እያገለገሉ ኖሩ።'),
  ('31a6dc70-8e13-5f1d-a085-7e4909c90dfb', '36951e8a-febf-5cd2-a018-e684a28ff569', '8b6e569e-d6ef-5a7a-ad4c-95157a1cbf76', 1, 1, 'በመጀመሪያ ቃል ነበረ፤ ቃልም በእግዚአብሔር ዘንድ ነበረ፤ ቃልም እግዚአብሔር ነበረ።'),
  ('b19aed69-1b9f-5245-a8d2-4f8c05e2d9ef', '36951e8a-febf-5cd2-a018-e684a28ff569', '8b6e569e-d6ef-5a7a-ad4c-95157a1cbf76', 2, 2, 'ይህም በመጀመሪያ በእግዚአብሔር ዘንድ ነበረ።'),
  ('9620d817-cf11-56e6-aa07-6f533d66fb55', '36951e8a-febf-5cd2-a018-e684a28ff569', '8b6e569e-d6ef-5a7a-ad4c-95157a1cbf76', 3, 3, 'ሁሉም በእርሱ ሆነ፤ ከሆነውም ሁሉ ያለ እርሱ ምንም የሆነ የለም።'),
  ('6d21d9d3-7197-547f-ad68-f5fcb02c0c48', '36951e8a-febf-5cd2-a018-e684a28ff569', '8b6e569e-d6ef-5a7a-ad4c-95157a1cbf76', 4, 4, 'ሕይወት በእርሱ ነበረ፥ ሕይወትም የሰው ብርሃን ነበረ፤'),
  ('10b3e176-be90-5bc2-ae7b-5d7a69684de7', '36951e8a-febf-5cd2-a018-e684a28ff569', '8b6e569e-d6ef-5a7a-ad4c-95157a1cbf76', 5, 5, 'ብርሃንም በጨለማ ያበራል፤ ጨለማም አላገኘውም።'),
  ('3c2cf11a-5caa-5b59-a440-6874952e6ef3', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 1, 6, 'ከእግዚአብሔር ዘንድ የተላከ ስሙ ዮሐንስ የሚባል አንድ ሰው ነበር።'),
  ('41ee77f2-4f69-5ad3-a20f-d126315f9c44', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 2, 7, 'እርሱም ሁሉ በእርሱ በኩል እንዲያምን ስለ ብርሃን ይመሰክር ዘንድ ለምስክርነት መጣ።'),
  ('522d985e-3239-55e9-a83a-2ca4622269ab', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 3, 8, 'ስለ ብርሃን ምስክር ሊሆን መጣ እንጂ እርሱ ራሱ ብርሃን አልነበረም።'),
  ('b8ec750b-746e-59ab-a92d-a7bc471331ca', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 4, 9, 'ለሰው ሁሉ የሚያበራው እውነተኛው ብርሃንስ ወደ ዓለም የመጣው ነው።'),
  ('072f5e49-024d-521f-add8-b57d632e0e3c', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 5, 10, 'በዓለም ነበረ፤ ዓለሙም በእርሱ ሆነ፤ ዓለሙ ግን አላወቀውም።'),
  ('09142414-e735-5162-a634-2e2a7bbe1168', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 6, 11, 'ወደ ወገኖቹ መጣ፤ ወገኖቹ ግን አልተቀበሉትም።'),
  ('9c80df1f-d8ac-511e-a2ca-f0ab05ca19b1', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 7, 12, 'ለተቀበሉት ሁሉ ግን በስሙ ለሚያምኑ የእግዚአብሔር ልጆች እንዲሆኑ ሥልጣንን ሰጣቸው።'),
  ('40963d2e-2b04-5c42-adae-888ccf1501ba', '36951e8a-febf-5cd2-a018-e684a28ff569', 'd537f64f-661f-5ecf-a6e8-a8f1640268cc', 8, 13, 'እነርሱም ከእግዚአብሔር ተወለዱ እንጂ ከሥጋዊና ከደማዊ ግብር ወይም ከወንድና ከሴት ፈቃድ አልተወለዱም።'),
  ('169ee102-1209-59a5-a853-89b4d5f61a22', '36951e8a-febf-5cd2-a018-e684a28ff569', '5a493244-625c-5fbd-a285-928e44491fc0', 1, 14, 'ያም ቃል ሥጋ ሆነ፤ በእኛም አደረ፤ ለአባቱ አንድ እንደ ሆነ ልጅ ክብር ያለ ክብሩን አየን፤ ጸጋንና እውነትን የተመላ ነው።'),
  ('cc10607f-2725-566e-aa17-030a483e93d5', '36951e8a-febf-5cd2-a018-e684a28ff569', '5a493244-625c-5fbd-a285-928e44491fc0', 2, 15, 'ምስክሩ ዮሐንስ ስለ እርሱ ድምፁን ከፍ አድርጎ ተናገረ፤ እንዲህም አለ፥ “እኔ ስለ እርሱ ከእኔ በፊት የነበረ ከእኔ በኋላ ይመጣል ያልኋችሁ ሰው ይህ ነው፥ እርሱ ከእኔ አስቀድሞ ነበረና።”'),
  ('5e92fe18-aeb0-52cd-afa2-ab5d0691fe04', '36951e8a-febf-5cd2-a018-e684a28ff569', '5a493244-625c-5fbd-a285-928e44491fc0', 3, 16, 'እኛም ሁላችን ከሙላቱ በጸጋ ላይ ጸጋን ተቀበልን።'),
  ('9fff708a-c305-5185-a423-63f5d6206e87', '36951e8a-febf-5cd2-a018-e684a28ff569', '5a493244-625c-5fbd-a285-928e44491fc0', 4, 17, 'ኦሪት በሙሴ ተሰጥታን ነበርና፤ ጸጋና እውነት ግን በኢየሱስ ክርስቶስ ሆነልን።'),
  ('1b920684-ff66-5635-a5b0-1e55fcce80ca', '36951e8a-febf-5cd2-a018-e684a28ff569', '5a493244-625c-5fbd-a285-928e44491fc0', 5, 18, 'በአባቱ ዕቅፍ ያለ አንድ ልጅ እርሱ ገለጠልን እንጂ እግዚአብሔርንስ ከቶ ያየው የለም።'),
  ('fd99411e-84a3-5c11-af00-20ea8f396c85', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 1, 19, 'አይሁድ፥ “አንተ ማን ነህ?” ብለው ይጠይቁት ዘንድ ካህናትንና ሌዋውያንን ከኢየሩሳሌም በላኩ ጊዜ የዮሐንስ ምስክርነት ይህ ነው።'),
  ('4e68d0da-7b68-58e6-aa5c-981ad69dcbb6', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 2, 20, 'እርሱም፥ “እኔ ክርስቶስ አይደለሁም” ብሎ አመነ እንጂ አልካደም።'),
  ('d359e17d-2bb2-5d4c-a92b-d7bb4f43824f', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 3, 21, '“እንኪያ አንተ ማነህ? አንተ ኤልያስ ነህን?” ብለው ጠየቁት፤ “አይደለሁም” አለ፤ “እንኪያ አንተ ነቢዩ ነህን?” አሉት፤ “አይደለሁም” አለ።'),
  ('86754b7b-c16b-5552-aa5b-3ae3f7dada84', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 4, 22, '“እንኪያስ አንተ ማነህ? ለላኩንም መልስ እንድንሰጥ ስለ ራስህ ማን ትላለህ?” አሉት።'),
  ('b84f8050-b6ab-5a90-a26c-9bb4657dcd76', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 5, 23, 'እርሱም፥ “ነቢዩ ኢሳይያስ እንደ ተናገረ የእግዚአብሔርን መንገድ ጥረጉ እያለ በምድረ በዳ የሚሰብክ የዐዋጅ ነጋሪ ድምፅ እኔ ነኝ” አለ።'),
  ('85728c4f-dcd4-5eb4-ae0b-c9d595257a0b', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 6, 24, 'የተላኩትም ከፈሪሳውያን ነበሩ።'),
  ('3dd66bcf-f3b8-5563-a46c-e995c9fef2d4', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 7, 25, '“እንኪያስ ክርስቶስን ካልሆንህ፥ ኤልያስንም ካልሆንህ፥ ነቢይንም ካልሆንህ ለምን ታጠምቃለህ?” ብለው ጠየቁት።'),
  ('f6f8831a-406b-5bb8-ac9e-f13d66c53964', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 8, 26, 'ዮሐንስም መልሶ እንዲህ አላቸው፥ “እኔ በውኃ አጠምቃችኋለሁ፤ ነገር ግን እናንተ የማታውቁት በመካከላችሁ ቆሞአል።'),
  ('1e31ef45-e23b-5823-a621-25a9f8ad887f', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 9, 27, 'ከእኔ በኋላ የሚመጣው፥ ከእኔ በፊት የነበረው፥ የጫማውን ጠፍር ልፈታ እንኳ የማይገባኝ ነው።”'),
  ('184a2a73-2e8f-5d34-ac50-4135bbdd3609', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 10, 28, 'ዮሐንስ ያጠምቅበት በነበረው በዮርዳኖስ ማዶ በቢታንያ በቤተ ራባ እንዲህ ሆነ።'),
  ('cc1db0e8-4a29-5ae0-ac62-a15e208149fa', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 11, 29, 'በማግሥቱም ዮሐንስ ወደ እርሱ ሲመጣ ጌታችን ኢየሱስን አይቶ እንዲህ አለ፤ “እነሆ፥ የዓለሙን ኀጢኣት የሚያስወግድ የእግዚአብሔር በግ።'),
  ('87d13519-2bc3-5d81-af70-6b3d3b856588', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 12, 30, 'ከእኔ በፊት የነበረ ሰው ከእኔ በኋላ ይመጣል ብዬ ስለ እርሱ የነገርኋችሁ ይህ ነው፤ እርሱ ከእኔ አስቀድሞ ነበርና።'),
  ('f8f358ca-b56a-5453-a373-62e20f2381d6', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 13, 31, 'እኔ አላውቀውም ነበር፤ ነገር ግን እስራኤል እንዲያውቁት ስለዚህ እኔ በውኃ ላጠምቅ መጣሁ።”'),
  ('f2100222-ac98-5c92-a593-8078e57226e9', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 14, 32, 'ዮሐንስም ምስክርነቱን እንዲህ ብሎ ተናገረ፥ “መንፈስ ቅዱስ ከሰማይ እንደ ርግብ ወርዶ በራሱ ላይ ሲቀመጥ አየሁ።'),
  ('8b6dc966-f631-547b-a292-148f0a8b2166', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 15, 33, 'እኔም አላውቀውም ነበር፤ ነገር ግን በውኃ እንዳጠምቅ የላከኝ እርሱ መንፈስ ቅዱስ ወርዶ ሲቀመጥበት የምታየው በመንፈስ ቅዱስ የሚያጠምቅ እርሱ ነው አለኝ።'),
  ('bf3705ff-24a7-5001-a6b6-bf9a766079fa', '36951e8a-febf-5cd2-a018-e684a28ff569', 'c77bd088-2792-526c-a712-73cc1194e5fe', 16, 34, 'እኔም ራሴ አይቻለሁ፤ እርሱም የእግዚአብሔር ልጅ እንደ ሆነ እኔ ምስክሩ ነኝ።”'),
  ('1885feef-2df2-57cf-a19d-9d5518bb5060', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 1, 35, 'በማግሥቱም ደግሞ ዮሐንስ ከሁለቱ ደቀ መዛሙርቱ ጋር ቆሞ ሳለ፥'),
  ('4cd7252e-21dc-5678-a370-735e3e13fc76', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 2, 36, 'ጌታችን ኢየሱስን ሲሄድ አይቶ “እነሆ፥ የዓለሙን ኀጢኣት የሚያስወግድ የእግዚአብሔር በግ” አለ።'),
  ('19c638d1-b6ae-5584-ab27-dcc1956c27f9', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 3, 37, 'ሁለቱ ደቀ መዛሙርቱም እንዲህ ሲል ሰምተው ጌታችን ኢየሱስን ተከተሉት።'),
  ('33fa11ce-0890-5918-a3fd-71c55d9aa478', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 4, 38, 'ጌታችን ኢየሱስም ዘወር ብሎ ሲከተሉት አየና፥ “ምን ትሻላችሁ?” አላቸው።'),
  ('3694a6ed-b599-5e3d-aa0f-f24bdfa734af', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 5, 39, 'እነርሱም፥ “ረቢ፥ ትርጓሜውም መምህር ሆይ፥ ማለት ነው፤ ወዴት ትኖራለህ?” አሉት።'),
  ('7d3c51e4-0134-59b9-a5d5-45e462591df4', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 6, 40, 'እርሱም “መጥታችሁ እዩ” አላቸው፤ ሄደውም የሚኖርበትን አዩ፤ ያን ዕለትም እስከ ዐሥር ሰዓት ድረስ በእርሱ ዘንድ ዋሉ።'),
  ('603404e2-66b2-53d7-a4ec-8c9e7cb3264a', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 7, 41, 'ከዮሐንስ ዘንድ ሰምተው ጌታችን ኢየሱስን ከተከተሉት ከሁለቱም አንዱ የስምዖን ጴጥሮስ ወንድም እንድርያስ ነበር።'),
  ('8827d39a-5091-57c4-aa32-d5fc5921bbdc', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 8, 42, 'እርሱም መጀመሪያ ወንድሙ ስምዖንን አግኝቶ “በትርጓሜው ክርስቶስ የሚሉት መሲሕን አገኘነው” አለው።'),
  ('5788ac9c-26d0-54d6-a7d1-cf515970a028', '36951e8a-febf-5cd2-a018-e684a28ff569', 'a55a3047-78f3-56f5-adf4-0ee150655c56', 9, 43, 'እርሱም ወደ ጌታችን ወደ ኢየሱስ ወሰደው፤ ጌታችን ኢየሱስም ባየው ጊዜ፥ “ አንተ የዮና ልጅ ስምዖን ነህን? አንተ ኬፋ ትባላለህ፤” አለው፤ ትርጓሜውም ጴጥሮስ ማለት ነው።'),
  ('5b2ebe83-8bf2-5309-aa7c-98ddd342656a', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 1, 44, 'በማግሥቱም ጌታችን ኢየሱስ ወደ ገሊላ ሊሄድ ወደደ፤ ፊልጶስንም አገኘውና “ተከተለኝ” አለው።'),
  ('1cef8edb-77a2-53ee-aeb2-c895ebbff131', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 2, 45, 'ፊልጶስ ግን ከእንድርያስና ከጴጥሮስ ከተማ ከቤተ ሳይዳ ነበር።'),
  ('a01e7bbb-7720-57f4-ac5e-32b3002dcd46', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 3, 46, 'ፊልጶስም ናትናኤልን አገኘውና፥ “ሙሴ በኦሪት፥ ነቢያትም ስለ እርሱ የጻፉለትን የዮሴፍን ልጅ የናዝሬቱን ኢየሱስን አገኘነው” አለው።'),
  ('85a9df72-c04f-5cd2-a261-142745ad84d6', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 4, 47, 'ናትናኤልም፥ “በውኑ ከናዝሬት ደግ ሰው ሊወጣ ይቻላልን?” አለው፤ ፊልጶስም፥ “መጥተህ እይ” አለው።'),
  ('5bd81a26-62bc-520e-ad9b-fd3054b3d40b', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 5, 48, 'ጌታችን ኢየሱስም ናትናኤልን ወደ እርሱ ሲመጣ ባየው ጊዜ ስለ እርሱ “እነሆ፥ በልቡ ተንኰል የሌለበት እውነተኛ እስራኤላዊ ይህ ነው” አለ።'),
  ('9a07464c-eb88-58dd-a8d5-74f34e146f11', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 6, 49, 'ናትናኤልም፥ “በየት ታውቀኛለህ?” አለው፤ ጌታችን ኢየሱስም መልሶ፥ “ገና ፊልጶስ ሳይጠራህ በበለስ ዛፍ ሥር ሳለህ አይችሃለሁ” አለው።'),
  ('55649705-e556-532a-a3d0-facc65415854', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 7, 50, 'ናትናኤልም መልሶ፥ “መምህር ሆይ፥ በእውነት አንተ የእግዚአብሔር ልጅ ነህ፤ የእስራኤልም ንጉሥ አንተ ነህ” አለው።'),
  ('85346c1e-2910-5ac7-ad04-6c9e091aa8b6', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 8, 51, 'ጌታችን ኢየሱስም መልሶ፥ “በበለስ ዛፍ ሥር አየሁህ ስለ አልሁህ አመንህን? ከዚህ የሚበልጥ ታያለህ” አለው።'),
  ('e65d8ab7-245b-51a3-abd5-aed7c2c912cb', '36951e8a-febf-5cd2-a018-e684a28ff569', '0653ac8d-4539-59e4-a0c4-b8fbae5c4e18', 9, 52, '“እውነት እውነት እላችኋለሁ፤ ከእንግዲህ ወዲህ ሰማያት ሲከፈቱ፥ የእግዚአብሔርም መላእክት ወደ ሰው ልጅ ሲወርዱና ሲወጡ ታያላችሁ” አላቸው።'),
  ('8e8571a2-e53a-5c4b-ab17-e9f641079fc8', '79384d41-f3a7-51bc-a50b-a64a564e9649', 'a402b176-4c38-5d29-a9dc-2e7f403ad121', 1, 1, 'በሦስተኛውም ቀን የገሊላ ክፍል በምትሆን በቃና ሰርግ ሆነ፤ የጌታችን የኢየሱስ እናትም በዚያ ነበረች።'),
  ('8b32dedb-cfb5-5887-a653-8f7026964bd7', '79384d41-f3a7-51bc-a50b-a64a564e9649', 'a402b176-4c38-5d29-a9dc-2e7f403ad121', 2, 2, 'ጌታችን ኢየሱስና ደቀ መዛሙርቱም ወደ ሰርጉ ታደሙ።'),
  ('aa720b95-7e04-50ab-a674-ba6709b40610', '79384d41-f3a7-51bc-a50b-a64a564e9649', '67192a61-bf5a-5182-a29c-4a48abd5def5', 1, 3, 'የወይን ጠጃቸውም ባለቀ ጊዜ እናቱ ጌታችን ኢየሱስን፥ “የወይን ጠጅ እኮ የላቸውም” አለችው።'),
  ('32346bed-0f2d-50e1-a770-4c32f557b158', '79384d41-f3a7-51bc-a50b-a64a564e9649', '67192a61-bf5a-5182-a29c-4a48abd5def5', 2, 4, 'ጌታችን ኢየሱስም፥ “አንቺ ሆይ ካንቺ ጋር ምን አለኝ? ጊዜዬ ገና አልደረሰም” አላት።'),
  ('3c7f4acd-ebc8-5b71-a374-75c75103fcf9', '79384d41-f3a7-51bc-a50b-a64a564e9649', '67192a61-bf5a-5182-a29c-4a48abd5def5', 3, 5, 'እናቱም ለአሳላፊዎቹ፥ “የሚላችሁን ሁሉ አድርጉ” አለቻቸው።'),
  ('8129a787-a697-5819-ab11-931d0baae51c', '79384d41-f3a7-51bc-a50b-a64a564e9649', '0434326c-11c5-57ec-ac83-415850c03477', 1, 6, 'በዚያም እንደ አይሁድ ልማድ የሚያነጹባቸው ስድስት የድንጋይ ጋኖች ነበሩ፤ ከእነርሱም እያንዳንዱ ሁለት ወይም ሦስት እንስራ ይይዙ ነበር።'),
  ('413ea0fd-2bf8-5ee6-a7df-739a39ae7a86', '79384d41-f3a7-51bc-a50b-a64a564e9649', '0434326c-11c5-57ec-ac83-415850c03477', 2, 7, 'ጌታችን ኢየሱስም፥ “ጋኖቹን ውኃ ሙሉአቸው” አላቸው፤ እስከ አፋቸውም እስከ ላይ ሞሉአቸው።'),
  ('dcce7333-856b-549d-af6c-bab58af73ee4', '79384d41-f3a7-51bc-a50b-a64a564e9649', '0434326c-11c5-57ec-ac83-415850c03477', 3, 8, '“አሁንም ቅዱና ወስዳችሁ ለአሳዳሪው ስጡት” አላቸው፤ ወስደውም ሰጡት።'),
  ('fb69357d-8b6f-5155-a2b4-4945eb2ea230', '79384d41-f3a7-51bc-a50b-a64a564e9649', '0434326c-11c5-57ec-ac83-415850c03477', 4, 9, 'አሳዳሪውም ያን የወይን ጠጅ የሆነውን ውኃ ቀምሶ አደነቀ፤ ከወዴት እንደ መጣም አላወቀም፤ የቀዱት አሳላፊዎች ግን የወይን ጠጅ የሆነውን ያን ውኃ ያውቁ ነበር። ውኃዉን የሞሉ እነርሱ ነበሩና።'),
  ('f9e9af18-1fab-5d1c-a984-41bc07033ad4', '79384d41-f3a7-51bc-a50b-a64a564e9649', '0434326c-11c5-57ec-ac83-415850c03477', 5, 10, 'አሳዳሪውም ሙሽራውን ጠርቶ፥ “ሰው ሁሉ መልካሙን የወይን ጠጅ አስቀድሞ ያጠጣል፤ ከጠገቡ በኋላም ተርታውን ያመጣል፤ አንተ ግን መልካሙን የወይን ጠጅ እስካሁን አቈየህ” አለው።'),
  ('88ecf9b5-84b9-5585-a472-a0df1e8e9694', '79384d41-f3a7-51bc-a50b-a64a564e9649', '0434326c-11c5-57ec-ac83-415850c03477', 6, 11, 'ጌታችን ኢየሱስም በቃና ዘገሊላ ያደረገው የተአምራት መጀመሪያ ይህ ነው፤ ክብሩንም ገለጠ፤ ደቀ መዛሙርቱም አመኑበት።'),
  ('603d8750-9818-50bd-a459-d658adf5ef55', '79384d41-f3a7-51bc-a50b-a64a564e9649', '31a78a30-d702-5990-a85d-602793faa9a5', 1, 12, 'ከዚህም በኋላ እርሱና እናቱ፥ ወንድሞቹና ደቀ መዛሙርቱም ወደ ቅፍርናሆም ወረዱ፤ በዚያም ብዙ ያይደለ ጥቂት ቀን ተቀመጡ።'),
  ('023e0957-8d52-5aaf-a2f1-953c1312603f', '79384d41-f3a7-51bc-a50b-a64a564e9649', '31a78a30-d702-5990-a85d-602793faa9a5', 2, 13, 'የአይሁድም የፋሲካቸው በዓል ቀርቦ ነበር፤ ጌታችን ኢየሱስም ወደ ኢየሩሳሌም ወጣ።'),
  ('a8effd98-50b3-5b5d-a91e-0301ce362a94', '79384d41-f3a7-51bc-a50b-a64a564e9649', '31a78a30-d702-5990-a85d-602793faa9a5', 3, 14, 'በቤተ መቅደስም በሬዎችንና በጎችን፥ ርግቦችንም የሚሸጡትን፥ ገንዘብ ለዋጮችንም ተቀምጠው አገኘ።'),
  ('f186ef6f-05ea-5e87-affa-fedaf20ea0fa', '79384d41-f3a7-51bc-a50b-a64a564e9649', '31a78a30-d702-5990-a85d-602793faa9a5', 4, 15, 'የገመድም ጅራፍ አበጀ፤ በጎችንና በሬዎችን፥ ሁሉንም ከቤተ መቅደስ አስወጣ፤ የለዋጮችንም ገንዘብ በተነ፤ ገበታዎቻቸውንም ገለበጠ።'),
  ('5072034d-8ddd-518d-ab1a-d2f2bad4b89a', '79384d41-f3a7-51bc-a50b-a64a564e9649', '31a78a30-d702-5990-a85d-602793faa9a5', 5, 16, 'ርግብ ሻጮችንም፥ “ይህን ከዚህ አውጡ፤ የአባቴን ቤት የንግድ ቤት አታድርጉ” አላቸው።'),
  ('e49ee63d-f035-54d1-a99d-b6e7d54d562a', '79384d41-f3a7-51bc-a50b-a64a564e9649', '31a78a30-d702-5990-a85d-602793faa9a5', 6, 17, 'ደቀ መዛሙርቱም፥ “የቤትህ ቅናት በላኝ” የሚል ቃል ተጽፎ እንዳለ ዐሰቡ።'),
  ('2873fe26-7304-59aa-a805-bcf6bc596b76', '79384d41-f3a7-51bc-a50b-a64a564e9649', '298d956e-f6d2-52fc-a03f-ebe9fdc336d5', 1, 18, 'አይሁድም መልሰው፥ “ይህን የምታደርግ ምን ምልክት ታሳያለህ?” አሉት።'),
  ('74c24839-1f58-5eda-acaa-69fde3093bc3', '79384d41-f3a7-51bc-a50b-a64a564e9649', '298d956e-f6d2-52fc-a03f-ebe9fdc336d5', 2, 19, 'ጌታችን ኢየሱስም፥ “ይህን ቤተ መቅደስ አፍርሱት፤ በሦስተኛውም ቀን አነሣዋለሁ” ብሎ መለሰላቸው።'),
  ('9ce8a3c2-8550-5f9a-a8e4-6adaa5276d8e', '79384d41-f3a7-51bc-a50b-a64a564e9649', '298d956e-f6d2-52fc-a03f-ebe9fdc336d5', 3, 20, 'አይሁድም፥ “ይህ ቤተ መቅደስ በአርባ ስድስት ዓመት ተሠራ፤ አንተስ በሦስት ቀኖች ውስጥ ታነሣዋለህን?” አሉት።'),
  ('cd3a1894-12a7-50a0-a104-228b3e86a7b3', '79384d41-f3a7-51bc-a50b-a64a564e9649', '298d956e-f6d2-52fc-a03f-ebe9fdc336d5', 4, 21, 'እርሱ ግን ይህን የተናገረው ቤተ መቅደስ ስለ ተባለ ሰውነቱ ነበር።'),
  ('9f6cffb5-1a83-5fb5-a50a-2d6a7e0c41d6', '79384d41-f3a7-51bc-a50b-a64a564e9649', '298d956e-f6d2-52fc-a03f-ebe9fdc336d5', 5, 22, 'ከሙታን በተነሣ ጊዜም ደቀ መዛሙርቱ ስለዚህ እንደ ነገራቸው ዐሰቡ፤ በመጻሕፍት ቃልና ጌታችን ኢየሱስ በነገራቸውም ነገር አመኑ።'),
  ('4f4a20ab-dcbe-5a74-a810-a527716751d8', '79384d41-f3a7-51bc-a50b-a64a564e9649', '9e9fa2a4-0612-545c-a3dc-0c0ce07228f0', 1, 23, 'ጌታችን ኢየሱስም በፋሲካ በዓል በኢየሩሳሌም ሳለ ብዙ ሰዎች ያደረገውን ተአምራት ባዩ ጊዜ በስሙ አመኑ።'),
  ('dc5aa6c8-140f-5cf7-a498-54915a6a352d', '79384d41-f3a7-51bc-a50b-a64a564e9649', '9e9fa2a4-0612-545c-a3dc-0c0ce07228f0', 2, 24, 'እርሱ ጌታችን ኢየሱስ ግን አያምናቸውም ነበር፤ ሁሉን እያንዳንዱን ያውቀዋልና።'),
  ('79d2df39-808d-55d2-a6ef-5f7460cfe385', '79384d41-f3a7-51bc-a50b-a64a564e9649', '9e9fa2a4-0612-545c-a3dc-0c0ce07228f0', 3, 25, 'የሰውንም ግብሩን ሊነግሩት አይሻም፤ እርሱ በሰው ያለውን ያውቅ ነበርና።'),
  ('41dc82a4-84af-5c17-afff-9a93b634b367', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 1, 1, 'ከፈሪሳውያን ወገን የአይሁድ አለቃ የሆነ ኒቆዲሞስ የተባለ አንድ ሰው ነበረ።'),
  ('1f6f14d5-47c8-5d4d-aae8-b3a7e591987e', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 2, 2, 'እርሱም በሌሊት ወደ ጌታችን ኢየሱስ መጥቶ እንዲህ አለው፥ “መምህር ሆይ፥ ልታስተምር ከእግዚአብሔር ዘንድ እንደ መጣህ እናውቃለን፤ እግዚአብሔር ከእርሱ ጋር ከሆነ በቀር አንተ የምታደርገውን ይህን ተአምር ሊያደርግ የሚችል የለምና።”'),
  ('e8ec453d-1b08-56ea-a5b6-1179b2a564f4', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 3, 3, 'ጌታችን ኢየሱስም መልሶ፥ “እውነት እውነት እልሀለሁ፤ ዳግመኛ ያልተወለደ ሰው የእግዚአብሔርን መንግሥት ለማየት አይችልም” አለው።'),
  ('8a83c91c-8e3a-5903-a8e6-3100e00a0ba2', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 4, 4, 'ኒቆዲሞስም፥ “ሰው ከሸመገለ በኋላ ዳግመኛ መወለድ እንደምን ይችላል? ዳግመኛ ይወለድ ዘንድ ወደ እናቱ ማኅፀን ተመልሶ መግባት ይችላልን?” አለው።'),
  ('23d98b92-a26a-50d2-a985-fd39f77b2da4', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 5, 5, 'ጌታችን ኢየሱስም መልሶ እንዲህ አለው፥ “እውነት እውነት እልሀለሁ፤ ዳግመኛ ከውኃና ከመንፈስ ቅዱስ ያልተወለደ ሰው ወደ እግዚአብሔር መንግሥት ሊገባ አይችልም።'),
  ('d5e6bfc7-60ef-5a8d-a221-66e23586fd0a', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 6, 6, 'ከሥጋ የተወለደ ሥጋ ነውና፤ ከመንፈስም የተወለደ መንፈስ ነውና።'),
  ('25f1843c-aa1a-5f90-ad6b-07b1c6a506e1', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 7, 7, 'ስለዚህም ዳግመኛ ልትወለዱ ይገባችኋል ስለ አልሁህ አታድንቅ።'),
  ('7aeb3f37-fdc3-5379-a306-2167a40bebd7', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 8, 8, 'ነፋስ ወደ ወደደው ይነፍሳልና፤ ድምፁንም ትሰማለህ፤ ነገር ግን ከየት እንደሚመጣ ወዴትም እንደሚሄድ አታውቅም፤ ከመንፈስ የሚወለድ ሁሉ እንዲሁ ነው።”'),
  ('178586c2-48ad-55f7-a8a0-29ec36dee47b', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 9, 9, 'ኒቆዲሞስም መልሶ፥ “ይህ ሊሆን እንዴት ይቻላል?” አለው።'),
  ('8be1a256-fe53-54ba-a46a-935c91ef0bd7', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 10, 10, 'ጌታችን ኢየሱስም መልሶ፥ “አንተ የእስራኤል መምህራቸው ነህ፤ ነገር ግን እንዴት ይህን አታውቅም?” አለው።'),
  ('1493a045-f5b7-53fc-abe7-b60ac694e2f7', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 11, 11, 'እውነት እውነት እልሃለሁ፤ የምናውቀውን እንናገራለን፤ ያየነውንም እንመሰክራለን፤ ነገር ግን ምስክርነታችንን አትቀበሉንም።'),
  ('d53cde8a-6147-50f1-ad4d-ea4c149a0f97', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 12, 12, 'በምድር ያለውን ስነግራችሁ ካላመናችሁኝ በሰማይ ያለውን ብነግራችሁ እንዴት ታምኑኛላችሁ?'),
  ('5bde96af-7ee3-5723-a55e-d6255d664b0e', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 13, 13, 'ከሰማይ ከወረደው የሰው ልጅ በቀር ወደ ሰማይ የወጣ የለም፤ እርሱም በሰማይ የሚኖረው ነው።'),
  ('e6bb7680-76b8-5498-a8e2-73a39bd09f05', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 14, 14, 'ሙሴ በምድረ በዳ እባቡን እንደ ሰቀለው የሰው ልጅ እንዲሁ ይሰቀል ዘንድ አለው።'),
  ('754f658d-09f4-5e16-aea0-0b567b274309', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 15, 15, 'ያመነበት ሁሉ ለዘለዓለም ሕያው ሆኖ እንዲኖር እንጂ እንዳይጠፋ።'),
  ('612e52fd-4d32-5f65-aa67-f156038741d4', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 16, 16, 'በእርሱ የሚያምን ሁሉ የዘለዓለም ሕይወትን እንዲያገኝ እንጂ እንዳይጠፋ እግዚአብሔር አንድያ ልጁን ቤዛ አድርጎ እስኪሰጥ ድረስ ዓለሙን እንዲህ ወዶታልና።'),
  ('0003e9b1-35e0-5ba3-a15b-46105d41f548', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 17, 17, 'ዓለም በእርሱ ይድን ዘንድ ነው እንጂ በዓለም እንዲፈርድ እግዚአብሔር ልጁን ወደዚህ ዓለም አልላከውምና።'),
  ('184d1fe2-f40e-5d6a-a2d0-569de20e2e02', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 18, 18, 'በእርሱ ያመነ አይፈረድበትም፤ በእርሱ ያላመነ ግን ፈጽሞ ተፈርዶበታል፤ በአንዱ በእግዚአብሔር ልጅ ስም አላመነምና።'),
  ('0d16bcf2-8f1f-5f4f-a48f-b93a3f8436b1', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 19, 19, 'ፍርዱም ይህ ነው፤ ብርሃን ወደ ዓለም መጥቶአልና፤ ሰውም ሥራው ክፉ ስለሆነ ከብርሃን ይልቅ ጨለማን መርጦአልና።'),
  ('106e2126-404b-517f-af35-53cd39d4fea3', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 20, 20, 'ሥራው ክፉ የሆነ ሁሉ ብርሃንን ይጠላልና፤ ክፉም ስለሆነ ሥራው እንዳይገለጥበት ወደ ብርሃን አይመጣም።'),
  ('763f0b20-6e0b-5f31-aaf1-3baf78a930fb', '256def84-aebc-58c8-aa81-004dd21221e1', '7fa6882a-4479-5ef5-ad77-1bf8f929d5dc', 21, 21, 'እውነትን የሚሠራ ግን ሥራው ይገለጥ ዘንድ ወደ ብርሃን ይመጣል፤ ስለ እግዚአብሔር ብሎ ይሠራልና።'),
  ('bba5272f-3bc3-5686-a0b5-55e22c3a445d', '256def84-aebc-58c8-aa81-004dd21221e1', 'df5a9fc4-1aa8-51d6-a340-d3f18850ed04', 1, 22, 'ከዚህም በኋላ ጌታችን ኢየሱስ ከደቀ መዛሙርቱ ጋር ወደ ይሁዳ ምድር ሄደ፤ በዚያም እያጠመቀ አብሮአቸው ተቀመጠ።'),
  ('030c5ed9-7548-573a-a56e-863c337258d0', '256def84-aebc-58c8-aa81-004dd21221e1', 'df5a9fc4-1aa8-51d6-a340-d3f18850ed04', 2, 23, 'ዮሐንስም በዮርዳኖስ ማዶ በሳሌም አቅራቢያ በሄኖን ያጠምቅ ነበር፤ በዚያ ብዙ ውኃ ነበርና፤ ብዙ ሰዎችም ወደ እርሱ እየመጡ ያጠምቃቸው ነበር።'),
  ('38d40aa4-9708-548d-a88d-5c84e5300ad2', '256def84-aebc-58c8-aa81-004dd21221e1', 'df5a9fc4-1aa8-51d6-a340-d3f18850ed04', 3, 24, 'ዮሐንስ ገና ወደ ወኅኒ ቤት አልገባም ነበርና።'),
  ('de783c5e-2ed2-57b7-aeb9-a60d6da66270', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 1, 25, 'ከዚህም በኋላ በዮሐንስ ደቀ መዛሙርትና በአይሁድ መካከል ስለ ማንጻት ክርክር ሆነ፤'),
  ('960a988a-962e-5fd7-a7d8-be8b451ba349', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 2, 26, 'ወደ ዮሐንስም ሄደው፥ “መምህር ሆይ፥ በዮርዳኖስ ማዶ ካንተ ጋር የነበረው፥ አንተም የመሰከርህለት እርሱ እነሆ፥ ያጠምቃል፤ ሁሉም ወደ እርሱ ይሄዳል” አሉት።'),
  ('f78c5702-741a-5da6-ad9a-46136c59ce39', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 3, 27, 'ዮሐንስም መልሶ እንዲህ አለ፥ “ሰው ከሰማይ ካልተሰጠው በስተቀር እርሱ ራሱ ጸጋን ገንዘብ ሊያደርግ ምንም አይችልም።'),
  ('6a739e69-e82e-5691-a15a-f22422157916', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 4, 28, 'እኔ ክርስቶስ አይደለሁም፤ ነገር ግን እንድሰብክለት ከእርሱ በፊት ተልኬአለሁ እንዳልኋችሁ እናንተ ራሳችሁ ምስክሮች ናችሁ።'),
  ('2d865e49-1f59-579f-a50e-3f08aad7d7d6', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 5, 29, 'ሙሽራ ያለችው ሙሽራ ነው፤ ቆሞ የሚሰማው የሙሽራው ሚዜ ግን በሙሽራው ቃል እጅግ ደስ ይለዋል፤ የእኔ ደስታ አሁን ተፈጸመች።'),
  ('4c6ab710-c2e8-59fd-a4ae-45fc4541ae8b', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 6, 30, 'የእርሱ ትበዛለች፤ የእኔ ግን ታንስ ዘንድ ይገባል።”'),
  ('4dcdcd4f-d0b0-55dd-a461-e8fb9905d0b3', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 7, 31, 'ከላይ የመጣው ከሁሉ በላይ ነው፤ ከምድር የተገኘውም ምድራዊ ነው፤ የምድሩንም ይናገራል፤ ከሰማይ የመጣው ግን ከሁሉ በላይ ነው።'),
  ('e3939ca6-1db8-5631-a906-d651203ece20', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 8, 32, 'ባየውና በሰማው ይመሰክራል፤ ነገር ግን ምስክርነቱን የሚቀበለው የለም።'),
  ('a1e02dfe-384f-57cc-a3c7-0eee45c26309', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 9, 33, 'ምስክርነቱን የተቀበለ ግን እግዚአብሔር እውነተኛ እንደ ሆነ አተመ።'),
  ('b3a2e202-a19f-5884-aa0b-83b5f5032c19', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 10, 34, 'እግዚአብሔር የላከው የእግዚአብሔርን ቃል ይናገራል፤ እግዚአብሔር መንፈሱን ሰፍሮ አይሰጥምና።'),
  ('06f32ce1-67f2-5fbf-afe7-77807fe79095', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 11, 35, 'አብ ልጁን ይወዳልና፥ ሁሉን በእጁ ሰጠው።'),
  ('4ae29235-c57b-5ae1-a227-3869f1c2cc8b', '256def84-aebc-58c8-aa81-004dd21221e1', '780b77a7-5722-5d0a-ab6d-89e5ea94140e', 12, 36, 'በወልድ የሚያምን የዘለዓለም ሕይወት አለው፤ በወልድ የማያምን ግን የእግዚአብሔር የቍጣ መቅሠፍት በላዩ ይኖራል እንጂ ሕይወትን አያይም።'),
  ('d62dd44f-4964-5f1a-ab76-288497f15022', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '9cd2f9a9-d910-5230-ae51-e7a43e516cc9', 1, 1, 'ጌታችን ኢየሱስ ከዮሐንስ ይልቅ ደቀ መዛሙርትን እንደ አበዛና እንደሚያጠምቅ ፈሪሳውያን መስማታቸውን ዐወቀ።'),
  ('21220c5f-a688-53fb-a8c6-481e0a7d1b1a', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '9cd2f9a9-d910-5230-ae51-e7a43e516cc9', 2, 2, 'ነገር ግን ደቀ መዛሙርቱ እንጂ እርሱ ራሱ ጌታችን ኢየሱስ አላጠመቀም።'),
  ('f1bbbec3-a6e6-5d1e-a157-38b0c987ecb2', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '9cd2f9a9-d910-5230-ae51-e7a43e516cc9', 3, 3, 'የይሁዳንም ምድር ትቶ ዳግመኛ ወደ ገሊላ ሄደ።'),
  ('aefeff15-4a88-5286-a444-62102218ccbd', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '9cd2f9a9-d910-5230-ae51-e7a43e516cc9', 4, 4, 'በሰማርያ በኩልም ሲያልፍ ሳለ፥'),
  ('41f25d0e-417a-5bd6-aa37-d0f0577c2476', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '9cd2f9a9-d910-5230-ae51-e7a43e516cc9', 5, 5, 'ያዕቆብ ለልጁ ለዮሴፍ በሰጠው በወይን ቦታ አቅራቢያ ወደ አለችው ሲካር ወደምትባለው የሰማርያ ከተማ ደረሰ።'),
  ('48a3ed45-dbf2-5aea-a12a-585139c26061', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '9cd2f9a9-d910-5230-ae51-e7a43e516cc9', 6, 6, 'በዚያም የያዕቆብ የውኃ ጕድጓድ ነበረ። ጌታችን ኢየሱስም መንገድ በመሄድ ደክሞ በዚያ ጕድጓድ አጠገብ ተቀመጠ፤ ጊዜውም ስድስት ሰዓት ያህል ነበር።'),
  ('c476d3f3-9e8d-51ec-a66d-94b1b7199e8d', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 1, 7, 'እነሆ፥ ከሰማርያ አንዲት ሴት ውኃ ልትቀዳ መጣች፤ ጌታችን ኢየሱስም፥ “ውኃ አጠጪኝ” አላት።'),
  ('1a80eb4e-c7b2-510b-ac6b-a31b4b067267', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 2, 8, 'ደቀ መዛሙርቱ ምግብ ሊገዙ ወደ ከተማ ሄደው ነበርና።'),
  ('39171ccc-0e25-5120-adeb-4d4169c2b996', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 3, 9, 'ያቺ የሰማርያ ሴትም፥ “አንተ አይሁዳዊ ስትሆን፥ እኔም ሳምራዊት ስሆን እንዴት ከእኔ ዘንድ ውኃ ልትጠጣ ትለምናለህ?” አለችው፤ አይሁድ ከሳምራውያን ጋር በሥርዐት አይተባበሩም ነበርና።'),
  ('12a10792-accd-581b-aa5c-3205dc0d2878', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 4, 10, 'ጌታችን ኢየሱስም፥ “የእግዚአብሔርን ስጦታና ውኃ አጠጪኝ ብሎ የሚለምንሽ ማን እንደ ሆነ ብታውቂስ አንቺ ደግሞ በለመንሺው ነበር፤ እርሱም የሕይወትን ውኃ በሰጠሽ ነበር” ብሎ መለሰላት።'),
  ('331f5226-4156-5c94-a2d2-9d3f0f305d1c', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 5, 11, 'ያቺ ሴትም እንዲህ አለችው፥ “ጌታዬ መቅጃ እንኳ የለህም፤ ጕድጓዱም ጥልቅ ነው፤ እንግዲህ የሕይወት ውኃ ከወዴት ታገኛለህ?'),
  ('7f2fabd3-9e03-55c5-a605-7d35dc9c9a66', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 6, 12, 'ይህን ጕድጓድ ከሰጠን ከአባታችን ከያዕቆብ አንተ ትበልጣለህን? እርሱም ልጆቹም፥ ከብቶቹም ከእርሱ ጠጥተዋል።”'),
  ('0aea4334-8568-5dca-a347-61159493b190', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 7, 13, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላት፥ “ከዚህ ውኃ የሚጠጣ ሁሉ ዳግመኛ ይጠማል።'),
  ('dde30c33-2b31-5463-a083-8f3bbf02b722', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 8, 14, 'እኔ ከምሰጠው ውኃ የሚጠጣ ግን ለዘለዓለም አይጠማም፤ እኔ የምሰጠው ውኃ በውስጡ ለዘለዓለም ሕይወት የሚፈልቅ የውኃ ምንጭ ይሆንለታል እንጂ።”'),
  ('a8008087-ae49-52c0-acde-5257433e49a8', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 9, 15, 'ሴቲቱም፥ “ጌታዬ ሆይ፥ እንዳልጠማ፥ ዳግመኛም ውኃ ልቀዳ ወደዚህ እንዳልመጣ እባክህ ከዚህ ውኃ ስጠኝ፤” አለችው።'),
  ('ad00df96-ab30-506d-a9a5-c95abfd811a0', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 10, 16, 'ጌታችን ኢየሱስም፥ “ሂደሽ ባልሽን ጥሪና ወደዚህ ነይ” አላት።'),
  ('4854feae-b39d-5b13-aae1-f37329d0ce45', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 11, 17, 'ሴቲቱም፥ “ባል የለኝም” ብላ መለሰችለት፤ ጌታችን ኢየሱስም እንዲህ አላት፥ “ባል የለኝም በማለትሽ መልካም ተናገርሽ።'),
  ('871429da-fad2-570b-a76d-de8ba86b25d1', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 12, 18, 'ቀድሞ አምስት ባሎች ነበሩሽ፤ ዛሬ አብሮሽ ያለው ግን ባልሽ አይደለም፤ ይህንስ እውነት አልሽ።”'),
  ('80ab19e7-e869-57a6-ac56-8773cb529a8e', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 13, 19, 'ሴቲቱም እንዲህ አለችው፥ “ጌታዬ፥ አንተ ነቢይ እንደ ሆንህ አያለሁ።'),
  ('f25ed85b-4d60-5a63-aaa9-6de72a78bcc5', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 14, 20, 'አባቶቻችን በዚህ ተራራ ሰገዱ፤ እናንተ ግን ይሰግዱበት ዘንድ የሚገባው ስፍራ በኢየሩሳሌም ነው ትላላችሁ።”'),
  ('ae419c49-fbe3-5260-a8e1-4be3024fdcbc', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 15, 21, 'ጌታችን ኢየሱስም እንዲህ አላት፥ “አንቺ ሴት በዚህ ተራራ ወይም በኢየሩሳሌም ብቻ ለአብ የማይሰግዱበት ሰዓት እንደምትመጣ እመኝኝ።'),
  ('57212161-437e-51b8-a5ba-9626b4ac655d', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 16, 22, 'እናንተ ለማታውቁት ትሰግዳላችሁ፤ እኛ ግን ለምናውቀው እንሰግዳለን፤ መድኀኒት ከአይሁድ ወገን ነውና።'),
  ('8ddb0583-c541-5b71-a5d8-d5d65f6d324e', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 17, 23, 'ነገር ግን በእውነት የሚሰግዱ በመንፈስና በእውነት ለአብ የሚሰግዱባት ጊዜ ትመጣለች፤ እርስዋም አሁን ናት። አብ እንዲህ የሚሰግዱለትን ይሻልና።'),
  ('6017ec40-eb21-51a6-a313-83a5222d718f', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 18, 24, 'እግዚአብሔር መንፈስ ነውና፤ የሚሰግዱለትም በመንፈስና በእውነት ይሰግዱለት ዘንድ ይገባል።”'),
  ('4ddcb1a9-a64a-581d-a7a2-d9e8a292b179', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 19, 25, 'ሴቲቱም፥ “ክርስቶስ የሚሉት መሲሕ እንደሚመጣ እናውቃለን፤ እርሱም በሚመጣ ጊዜ ሁሉን ይነግረናል” አለችው።'),
  ('487fe3c0-20eb-5755-a0b0-00881bf14f81', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 20, 26, 'ጌታችን ኢየሱስም፥ “የማነጋግርሽ እኔ እርሱ ነኝ” አላት።'),
  ('62c0f6b6-131b-5e76-af6d-62caaa4828c2', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 21, 27, 'በዚያም ጊዜ ደቀ መዛሙርቱ መጡ፤ ከሴት ጋርም ይነጋገር ነበርና ተደነቁ፤ ነገር ግን፥ “ምን ትሻለህ? ወይስ ከእርስዋ ጋር ለምን ትነጋገራለህ?” ያለው የለም።'),
  ('a4c1987d-4a75-5dd7-ad6e-506d5b36c3d7', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 22, 28, 'ሴቲቱም እንስራዋን ትታ ወደ ከተማ ገባች፤ ለሰዎችም ነገረች።'),
  ('f7f59645-31af-56dd-afce-a64f97f5c024', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 23, 29, '“የሠራሁትን ሁሉ የነገረኝን ሰው ታዩ ዘንድ ኑ፤ እንጃ፥ እርሱ ክርስቶስ ይሆን?”'),
  ('73412534-ba55-54da-a5d4-731425d3d88d', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 24, 30, 'ከከተማም ወጥተው ወደ እርሱ ሄዱ።'),
  ('54355808-467c-51d2-ae29-f75085088f8b', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 25, 31, 'በዚህም ጊዜ ደቀ መዛሙርቱ፥ “መምህር ሆይ፥ እህል ብላ” ብለው ለመኑት።'),
  ('76833041-ed85-5c37-a983-21dbe408af3f', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 26, 32, 'ጌታችን ኢየሱስም፥ “እኔ የምበላው እናንተ የማታውቁት ምግብ አለኝ” አላቸው።'),
  ('eba4e966-daa6-50c8-a9ff-8d2a2b4979d1', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 27, 33, 'ደቀ መዛሙርቱም እርስ በርሳቸው፥ “አንዳች የሚበላው ምግብ ያመጣለት ሰው ይኖር ይሆን?” ተባባሉ።'),
  ('fe470b86-7d48-5d69-a131-75ddbe4906e5', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 28, 34, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “የእኔስ መብል የላከኝን የአባቴን ፈቃድ አደርግ ዘንድ፥ ሥራውንም እፈጽም ዘንድ ነው።'),
  ('8e97cca5-2e9e-58a2-ae58-b05ed4f108a9', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 29, 35, 'እናንተ እስከ አራት ወር ድረስ መከር ይሆናል የምትሉ አይደለምን? እነሆ፥ እላችኋለሁ፤ ዐይናችሁን አንሡ፤ መከሩም ሊደርስ እንደ ገረጣ ምድሩን ተመልከቱ።'),
  ('c38307a6-5b63-522b-af0e-ca2db467199c', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 30, 36, 'አጫጅም ዋጋውን ያገኛል፤ የሚዘራና የሚያጭድም በአንድነት ደስ እንዲላቸው ለዘለዓለም ሕይወት ፍሬን ይሰበስባል።'),
  ('b1073d29-e7f6-599c-a58c-fe4112bfa2fa', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 31, 37, 'አንዱ ይዘራል፥ ሌላውም ያጭዳል የሚለው ቃል በዚህ እውነት ሆኖአል።'),
  ('1f9e4cc4-9736-5c62-ada6-796f271f65e6', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'a55e09ce-30ac-58cf-af78-949037aed947', 32, 38, 'እኔም ያልደከማችሁበትን እንድታጭዱ ላክኋችሁ፤ ሌሎች ደከሙ፤ እናንተም በድካማቸው ገባችሁ።”'),
  ('548fcb79-9992-5c0b-a2d3-f216b2b26e2d', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'ead03694-c0c8-5025-ac2c-8b77ed6a37a7', 1, 39, '“የሠራሁትን ሁሉ ነገረኝ” ብላ የመሰከረችው ሴት ስለ ነገረቻቸውም ከዚያች ከሰማርያ ከተማ ብዙዎች አመኑበት።'),
  ('0815fdfa-2d7f-54ce-ad5a-404fd7460ea1', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'ead03694-c0c8-5025-ac2c-8b77ed6a37a7', 2, 40, 'ሳምራውያንም ሁሉ ወደ እርሱ መጥተው በእነርሱ ዘንድ እንዲኖር ማለዱት፤ ሁለት ቀንም ያህል በዚያ ተቀመጠ።'),
  ('b30c6c95-3cf5-525a-a61a-04464519eaf1', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'ead03694-c0c8-5025-ac2c-8b77ed6a37a7', 3, 41, 'ስለ ቃሉም እጅግ ብዙዎች አመኑበት።'),
  ('557637dd-3016-52f6-af3a-db19fc7521db', '617c56d4-48f2-5d64-a62c-e8509c5f9560', 'ead03694-c0c8-5025-ac2c-8b77ed6a37a7', 4, 42, 'ሴቲቱንም፥ “እኛ ራሳችን ይህ በእውነት የዓለም መድኀኒት ክርስቶስ እንደ ሆነ ሰምተንና ተረድተን ነው እንጂ በአንቺ ቃል ያመንበት አይደለም” አሏት።'),
  ('4fffd108-8dcc-5c10-afaa-d24a9a75b748', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 1, 43, 'ከሁለት ቀንም በኋላ ጌታችን ኢየሱስ ከዚያ ወጥቶ ወደ ገሊላ ሄደ።'),
  ('16676022-aad3-5edd-aef2-88016e82a808', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 2, 44, 'ነቢይ በገዛ ሀገሩ እንደማይከብር እርሱ ራሱ ጌታችን ኢየሱስ መሰከረ።'),
  ('a1628bf9-946c-54a6-aa00-56de86154aae', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 3, 45, 'ወደ ገሊላም ደግሞ በገባ ጊዜ ገሊላውያን ሁሉ ተቀበሉት፤ እነርሱ ለበዓል ሄደው ስለ ነበር በበዓሉ ቀን በኢየሩሳሌም ያደረገውን ተአምር አይተው ነበርና።'),
  ('4fa9cdee-e76f-599c-a743-d0b8f04f972b', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 4, 46, 'ጌታችን ኢየሱስም ውኃውን የወይን ጠጅ ወደ አደረገበት የገሊላ ክፍል ወደምትሆን ወደ ቃና ዳግመኛ ሄደ። በቅፍርናሆም ልጁ የታመመበት የንጉሥ ወገን የሆነ አንድ ሰው ነበረ፤'),
  ('1963c0c0-b1b6-5bbe-a04f-5808df266f2a', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 5, 47, 'እርሱም ጌታችን ኢየሱስ ከይሁዳ ወደ ገሊላ እንደ መጣ በሰማ ጊዜ ወደ እርሱ ሄደ፤ ሊሞት ቀርቦ ነበርና ወርዶ ልጁን ያድንለት ዘንድ ለመነው፤'),
  ('96a7ce90-5e91-57a4-ab72-8bfdc2bd26bc', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 6, 48, 'ጌታችን ኢየሱስም፥ “ምልክትንና ድንቅ ሥራን ካላያችሁ አታምኑም” አለው።'),
  ('9fd95707-e435-5131-abc2-922d8d11211f', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 7, 49, 'ያም የንጉሥ ወገን የሆነ ሰው፥ “አቤቱ፥ ልጄ ሳይሞት ፈጥነህ ውረድ” አለው።'),
  ('ad64af04-7a70-5b17-ac0c-011abf5bdf84', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 8, 50, 'ጌታችን ኢየሱስም፥ “ሂድ፤ ልጅህስ ድኖአል” አለው፤ ያም ሰው፦ ጌታችን ኢየሱስ በነገረው ቃል አምኖ ሄደ።'),
  ('aeee9ff0-8265-5a84-a39a-978de6e3409d', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 9, 51, 'ሲወርድም አገልጋዮቹ ተቀበሉትና፥ “ልጅህስ ድኖአል” ብለው ነገሩት።'),
  ('1fc534c6-e214-544e-a486-d9c8b405d908', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 10, 52, 'የዳነባትን ሰዓቷንም ጠየቃቸው፤ “ትናንትና በሰባት ሰዓት ንዳዱ ተወው” አሉት።'),
  ('a1ec12fd-b8a5-5e68-ab12-87b2a9759401', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 11, 53, 'አባቱም፥ ጌታችን ኢየሱስ፥ “ልጅህ ድኖአል” ባለበት ሰዓት እንደ ሆነች ዐወቀ፤ እርሱም፥ ቤተ ሰቦቹም ሁሉ አመኑ።'),
  ('254e5962-564e-5598-a5a1-c0785e460a88', '617c56d4-48f2-5d64-a62c-e8509c5f9560', '8af8c9b6-4616-5b03-a437-bb267b5401c4', 12, 54, 'ዳግመኛም ጌታችን ኢየሱስ ከይሁዳ ወደ ገሊላ መጥቶ ያደረገው ሁለተኛው ተአምር ይህ ነው።'),
  ('b2d3b09b-6ffa-5dda-a954-7f36731219b6', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 1, 1, 'ከዚህም በኋላ በአይሁድ በዓል እንዲህ ሆነ፤ ጌታችን ኢየሱስ ወደ ኢየሩሳሌም ወጣ።'),
  ('3bf25352-29fc-5017-a747-b9745c6fcc8b', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 2, 2, 'በኢየሩሳሌምም በበጎች በር አጠገብ መጠመቂያ ነበረች፤ ስምዋንም በዕብራይስጥ ቤተ ሳይዳ ይሉአታል፤ አምስት እርከኖችም ነበሩአት።'),
  ('4ce5b077-0712-52d6-a13d-0d499d7f3cc7', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 3, 3, 'በዚያም ዕውሮችና አንካሶች፥ ሰውነታቸውም የሰለለ ብዙ ድውያን ተኝተው የውኃዉን መናወጥ ይጠባበቁ ነበር።'),
  ('03e1362b-7603-56cb-a29c-82eb1314242e', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 4, 4, 'የእግዚአብሔር መልአክ ወደ መጠመቂያዉ ወርዶ ውኃዉን በሚያናውጠው ጊዜ፥ ከውኃዉ መናወጥ በኋላ በመጀመሪያ ወርዶ የሚጠመቅ ካለበት ደዌ ሁሉ ይፈወስ ነበርና።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('80c08a15-1cbf-52f7-acdb-0727190d29df', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 5, 5, 'በዚያም ከታመመ ሠላሳ ስምንት ዓመት የሆነው አንድ ሰው ነበር።'),
  ('27777349-f2d3-5a28-a7b5-4a78f835ad06', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 6, 6, 'ጌታችን ኢየሱስም ያን ሰው በአልጋዉ ተኝቶ ባየ ጊዜ በደዌ ብዙ ዘመን እንደ ቈየ ዐውቆ፥ “ልትድን ትወዳለህን?” አለው።'),
  ('b8967cfd-658b-55f1-ae6b-e9fffa19d281', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 7, 7, 'ድውዩም መልሶ፥ “አዎን ጌታዬ ሆይ፥ ነገር ግን ውኃዉ በተናወጠ ጊዜ ወደ መጠመቂያዉ የሚያወርደኝ ሰው የለኝም፤ እኔ በምመጣበት ጊዜ ሌላው ቀድሞኝ ይወርዳል” አለው።'),
  ('66716785-4688-5c1e-aeb8-f0165ec956e6', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 8, 8, 'ጌታችን ኢየሱስም፥ “ተነሥና አልጋህን ተሸክመህ ሂድ” አለው።'),
  ('654fb995-d28b-5abe-ab0d-8b0b1a4b2228', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 9, 9, 'ወዲያውኑም ያ ሰው ድኖ አልጋውን ተሸክሞ ሄደ፤ ያች ቀንም ሰንበት ነበረች።'),
  ('6279e70f-22ab-5b72-a717-1181e5eb39c4', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 10, 10, 'አይሁድም የዳነውን ሰው፥ “ዛሬ ሰንበት ነው፤ አልጋህን ልትሸከም አይገባህም” አሉት።'),
  ('6d01e09b-0981-5ff4-aa7a-01988f53e53e', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 11, 11, 'እርሱም መልሶ፥ “ያዳነኝ እርሱ፦ አልጋህን ተሸክመህ ሂድ አለኝ” አላቸው።'),
  ('a0c30987-d0b5-5a07-a5da-d56bf6859b69', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 12, 12, 'አይሁድም፥ “አልጋህን ተሸክመህ ሂድ ያለህ ሰውዬው ማነው?” ብለው ጠየቁት።'),
  ('0b0c1220-0a3d-567f-af58-9efb2319fa82', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 13, 13, 'ያ የተፈወሰው ግን ያዳነው ማን እንደ ሆነ አላወቀም፤ ጌታችን ኢየሱስ በዚያ ቦታ በነበሩት ብዙ ሰዎች መካከል ተሰውሮ ነበርና።'),
  ('f1632912-2d95-5c5e-a9df-35a69c04e933', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 14, 14, 'ከዚህም በኋላ ጌታችን ኢየሱስ ያን የዳነውን ሰው በቤተ መቅደስ አገኘውና፥ “እነሆ፥ ድነሃል፤ ግን ከዚህ የባሰ እንዳያገኝህ ዳግመኛ እንዳትበድል ተጠንቀቅ” አለው።'),
  ('548a8355-ef1a-527c-a8b2-a3d47a455ea8', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 15, 15, 'ያም ሰው ሄዶ ያዳነው ጌታችን ኢየሱስ እንደ ሆነ ለአይሁድ ነገራቸው።'),
  ('e3320dab-80c6-5c55-a217-630b3bebb76d', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 16, 16, 'ስለዚህም አይሁድ ጌታችን ኢየሱስን ያሳድዱትና ሊገድሉትም ይሹ ነበር፤ በሰንበት እንዲህ ያደርግ ነበርና።'),
  ('2379e067-f577-588a-a07b-0cba75dd5f80', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 17, 17, 'ጌታችን ኢየሱስም መልሶ፥ “አባቴ እስከ ዛሬ ይሠራል፤ እኔም እሠራለሁ” አላቸው።'),
  ('c13fbc81-2adb-5f67-a645-99d3dc7e290c', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 18, 18, 'ስለዚህም አይሁድ ሊገድሉት በጣም ይፈልጉ ነበር፤ “ሰንበትን የሚሽር ነው” በማለት ብቻ አይደለም፤ ደግሞም እግዚአብሔርን “አባቴ ነው ይላል፤ ራሱንም ከእግዚአብሔር ጋር ያስተካክላል” በማለት ነው እንጂ።'),
  ('fae83214-64de-5965-a600-91d0b38de898', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 19, 19, 'ከዚህም በኋላ ጌታችን ኢየሱስ መልሶ እንዲህ አላቸው፥ “እውነት እውነት እላችኋለሁ፤ ወልድ ከራሱ ብቻ ምንም ሊያደርግ አይችልም፤ አብ ሲያደርግ ያየውን ነው እንጂ፤ ወልድም አብ የሚሠራውን ያንኑ እንዲሁ ይሠራል።'),
  ('0dd86db5-d8c2-525b-aa38-41aee9e0b661', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 20, 20, 'አብ ልጁን ይወዳልና የሚሠራውንም ሥራ ሁሉ ያሳየዋል፤ እናንተም ታደንቁ ዘንድ ከዚህ የሚበልጥ ሥራን ያሳየዋል።'),
  ('74e2f2ab-acbb-59a9-a403-36f074b83e01', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 21, 21, 'አብ ሙታንን እንደሚያስነሣቸው፥ ሕይወትንም እንደሚሰጣቸው እንዲሁ ወልድም ለሚወድዳቸው ሕይወትን ይሰጣል።'),
  ('4982c3b4-ef42-532f-a75c-1a6df9804217', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 22, 22, 'አብ ከቶ በማንም አይፈርድም፤ ፍርዱን ሁሉ ለወልድ ሰጠው እንጂ።'),
  ('3d536733-cf49-5cdb-ae0d-ed4fe3c1a188', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 23, 23, 'ሰዎች ሁሉ አብን እንደሚያከብሩ ወልድን ያከብሩ ዘንድ፤ ወልድን የማያከብር ግን የላከውን አብን አያከብርም።'),
  ('f30016e1-23a0-559d-a53c-c8f089e43245', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 24, 24, 'እውነት እውነት እላችኋለሁ፤ ቃሌን የሚሰማ በላከኝም የሚያምን የዘለዓለም ሕይወትን ያገኛል፤ ከሞትም ወደ ሕይወት ተሻገረ እንጂ ወደ ፍርድ አይሄድም።'),
  ('26b3c00a-05a0-515f-a3dd-321c66dc7cfb', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 25, 25, '“እውነት እውነት እላችኋለሁ፤ ሙታን የእግዚአብሔርን ልጅ ቃል የሚሰሙበት ሰዓት ይመጣል፤ እርሱም አሁን ነው፤ የሚሰሙትም ይድናሉ።'),
  ('9ae525f7-e0ce-5b5c-a5dc-fce09d8d0613', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 26, 26, 'ለአብ በራሱ ሕይወት እንዳለው፥ እንዲሁም ደግሞ ለወልድ በራሱ ሕይወት እንዲኖረው ሰጠው።'),
  ('e5940029-6528-5908-ab55-9fc2195c7888', '2155a608-b423-51e5-abc8-d72bd6297cf8', '9788fc66-5c15-5391-a18a-363d3db89df0', 27, 27, 'የእግዚአብሔር ልጅ የሰው ልጅ ነውና ይፈርድ ዘንድ ሥልጣንን ሰጠው።'),
  ('32945aa5-30b7-517a-ab32-c766198029db', '2155a608-b423-51e5-abc8-d72bd6297cf8', '54c572a8-fc95-550c-ae12-6ed63cc1fdd9', 1, 28, '“በመቃብር ያሉ ሁሉ ቃሉን የሚሰሙባት ጊዜ ትመጣለችና ስለዚህ አታድንቁ።'),
  ('53fa52fc-6803-5133-a829-8540dc400379', '2155a608-b423-51e5-abc8-d72bd6297cf8', '54c572a8-fc95-550c-ae12-6ed63cc1fdd9', 2, 29, 'መልካም የሠሩ ለሕይወት ትንሣኤ፥ ክፉ የሠሩም ለፍርድ ትንሣኤ ይነሣሉ።'),
  ('065cc5db-3122-5795-a36d-c48d36117593', '2155a608-b423-51e5-abc8-d72bd6297cf8', '54c572a8-fc95-550c-ae12-6ed63cc1fdd9', 3, 30, 'እኔ ከራሴ አንዳች አደርግ ዘንድ አልችልም፤ እንደ ሰማሁ እፈርዳለሁ እንጂ፤ ፍርዴም እውነት ነው፤ የላከኝን ፈቃድ እንጂ የእኔን ፈቃድ አልሻምና።'),
  ('e4d6e23a-508e-5802-a332-ea51e4d26e87', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 1, 31, '“እኔ ለራሴ ብመሰክር ምስክርነቴ እውነት አይደለም።'),
  ('f088226c-c8e2-5e85-a03a-03b311029848', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 2, 32, 'ነገር ግን ለእኔ የሚመሰክር ሌላ ነው፤ ስለ እኔ የመሰከረው ምስክርነቱም እውነት እንደሆነ አውቃለሁ።'),
  ('24942441-26a5-5750-acb9-febb6b6cd538', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 3, 33, 'እናንተ ወደ ዮሐንስ ልካችሁ አልነበረምን? እርሱም ምስክርነቱን በእውነት ነገራችሁ።'),
  ('565e4f1c-285e-51a3-ab3c-165eb2a475b0', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 4, 34, 'እኔ ግን የሰውን ምስክርነት የምሻ አይደለሁም፤ ነገር ግን እናንተ ትድኑ ዘንድ ይህን እላለሁ።'),
  ('45becc9d-ac95-59da-ae84-0c8461d3c37b', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 5, 35, 'እርሱ የሚነድና የሚያበራ መብራት ነበረ፤ እናንተም አንዲት ሰዓት በብርሃኑ ደስ ሊላችሁ ወደዳችሁ።'),
  ('0c49e2b0-b3ff-5845-a0c5-d4d806789cfe', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 6, 36, 'እኔ ግን ከዮሐንስ ምስክርነት የሚበልጥ ምስክር አለኝ፤ ልሠራውና ልፈጽመው አባቴ የሰጠኝ ሥራ፥ አብ እንደ ላከኝ ያ የምሠራው ሥራ ምስክሬ ነውና።'),
  ('88ae6724-0fc9-5956-a475-f54cbda277ff', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 7, 37, 'የላከኝ አብም ስለ እኔ መስክሮአል፤ ከሆነም ጀምሮ ቃሉን አልሰማችሁም፤ መልኩንም አላያችሁም።'),
  ('bb85371c-0648-51b1-a1b0-d60bb56c5a60', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 8, 38, 'ቃሉም የላችሁም፤ በእናንተ ዘንድም አይኖርም፤ እርሱ የላከውን አላመናችሁምና።'),
  ('1e24a260-1a5a-5497-a9a2-0b503d1fd7c4', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 9, 39, 'መጻሕፍትን መርምሩ፤ በእነርሱ የዘለዓለም ሕይወትን የምታገኙ ይመስላችኋልና፤ እነርሱም የእኔ ምስክሮች ናቸው።'),
  ('314cde6c-4670-5f30-a155-5069d4731c40', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 10, 40, 'ሕይወትን ታገኙ ዘንድ ወደ እኔ ልትመጡ አትወዱም።'),
  ('fea813a4-79e6-54a3-abae-f0afdca9e89c', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 11, 41, 'እኔ ከሰው ክብርን ልቀበል አልሻም።'),
  ('5642a459-4ac8-5f35-a539-893db0d61b11', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 12, 42, 'ነገር ግን የእግዚአብሔር ፍቅር በእናንተ እንደሌለባችሁ ዐወቅሁ።'),
  ('11c28c63-52e7-5c1f-a356-4471c19e9c14', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 13, 43, 'እኔ በአባቴ ስም መጣሁ፥ አልተቀበላችሁኝምም፤ ሌላው ግን በራሱ ስም ቢመጣ እርሱን ትቀበሉታላችሁ።'),
  ('8ee1eba7-ba53-5a59-a79a-f5da0db9bc7e', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 14, 44, 'ከባልንጀራችሁ ክብርን የምትመርጡ፥ ከአንድ እግዚአብሔርም ክብርን የማትሹ እናንተ እንዴት ልታምኑ ትችላላችሁ?'),
  ('d337e722-f4d6-5fd2-a604-604cd701f8bf', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 15, 45, 'እኔ በአብ ዘንድ የምከስሳችሁ አይምሰላችሁ፤ የሚከስሳችሁስ አለ፤ እርሱም እናንተ ተስፋ የምታደርጉት ሙሴ ነው።'),
  ('19d3821f-9b35-5a40-a2fc-34d3ed346288', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 16, 46, 'ሙሴንስ አምናችሁት ቢሆን እኔንም ባመናችሁኝ ነበር፤ እርሱ ስለ እኔ ጽፎአልና።'),
  ('d28e7192-7bd9-5112-aeea-2caf87d43f76', '2155a608-b423-51e5-abc8-d72bd6297cf8', '8e02e99a-af47-5620-ab79-9ac4f9572b02', 17, 47, 'ሙሴ የጻፈውን ካላመናችሁ ግን የእኔን ቃል እንዴት ታምናላችሁ?”'),
  ('2ba10775-fd27-5739-abe9-3552d874511d', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '6b82a348-9b25-5eb1-a1ed-a742c2dc3c51', 1, 1, 'ከዚህ በኋላ ጌታችን ኢየሱስ ወደ ገሊላ ባሕር ማዶ ወደ ጥብርያዶስ ሄደ።'),
  ('394e6629-f350-5ee3-a095-8f6a7b367867', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '6b82a348-9b25-5eb1-a1ed-a742c2dc3c51', 2, 2, 'በበሽተኞችም ላይ ያደረገውን ተአምራት ስለ አዩ ብዙ ሰዎች ተከተሉት፤'),
  ('e3f9b812-97c2-5d2d-a9e3-c910e9043ea9', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '6b82a348-9b25-5eb1-a1ed-a742c2dc3c51', 3, 3, 'ጌታችን ኢየሱስም ወደ ተራራ ወጣ፤ ከደቀ መዛሙርቱም ጋር በዚያ ተቀመጠ።'),
  ('64de0b7b-b77c-5f8e-aa7f-928520df76d0', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '6b82a348-9b25-5eb1-a1ed-a742c2dc3c51', 4, 4, 'የአይሁድ የፋሲካ በዓልም ቀርቦ ነበር።'),
  ('001e88d5-88e1-561f-aedf-eb3e42e5f9a2', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 1, 5, 'ጌታችን ኢየሱስም ዐይኖቹን አንሥቶ ብዙ ሰዎች ወደ እርሱ ሲመጡ አየና ፊልጶስን፥ “ለእነዚህ ሰዎች የምናበላቸው እንጀራ ከወዴት እንግዛ?” አለው።'),
  ('6414f9f4-6ca4-5f5c-a590-9b44b2a0ecc2', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 2, 6, 'ሲፈትነው ይህን አለ እንጂ፥ እርሱስ የሚያደርገውን ያውቅ ነበር።'),
  ('cb254a45-7f14-5ab3-ac37-a6ca264ccad2', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 3, 7, 'ፊልጶስም መልሶ እንዲህ አለው፥ “ከእነርሱ ለእያንዳንዱ ጥቂት ጥቂት ይወስዱ ዘንድ የሁለት መቶ ዲናር እንጀራ አይበቃቸውም።”'),
  ('9b1d52c7-3f86-52d1-a52f-b4a42307286e', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 4, 8, 'ከደቀ መዛሙርቱም አንዱ የስምዖን ጴጥሮስ ወንድም እንድርያስ እንዲህ አለው፥'),
  ('7a3855e1-2d02-5c06-addf-eb9c26aae821', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 5, 9, '“አምስት የገብስ እንጀራና ሁለት ዓሣ የያዘ ብላቴና በዚህ አለ፤ ነገር ግን እነዚህ ይህን ለሚያህል ሰው ምን ይበቃሉ?”'),
  ('71eaeb6a-9cde-5791-a1a4-da83fb1bd3b8', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 6, 10, 'ጌታችን ኢየሱስም፥ “ሰዎቹን እንዲቀመጡ አድርጉ” አለ፤ የዚያ ቦታም ሣሩ ብዙ ነበር፤ ወንዶቹም በመስኩ ላይ ተቀመጡ፤ ቍጥራቸውም አምስት ሺህ ያህል ነበር።'),
  ('4a847f59-6051-562d-a856-c6455eb55713', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 7, 11, 'ጌታችን ኢየሱስም ያን እንጀራ ይዞ አመሰገነ፤ ቈርሶም ለደቀ መዛሙርቱ ሰጣቸው፤ ደቀ መዛሙርቱም ለተቀመጡት ሰዎች ሰጡአቸው፤ ከዓሣውም እንዲሁ የፈለጉትን ያህል ሰጡአቸው።'),
  ('665c2ebb-7f4d-5420-a222-217fbcfe9269', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 8, 12, 'ከጠገቡም በኋላ ደቀ መዛሙርቱን፥ “ከቍርስራሹ ምንም የሚወድቅ እንዳይኖር የተረፈውን ቍርስራሽ አንሡ፤” አላቸው።'),
  ('fbf90e07-10d7-52d3-a325-7e830096a6dd', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 9, 13, 'እነርሱም ሰበሰቡ፥ በልተው ከጠገቡ በኋላም ከአምስቱ የገብስ እንጀራ የተረፈው ቍርስራሽ ዐሥራ ሁለት መሶብ ሞላ።'),
  ('82969dd1-8287-5ad5-aba3-92f1ed8a39ab', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 10, 14, 'ሕዝቡም ጌታችን ኢየሱስ ያደረገውን ተአምራት አይተው፥ “ይህ በእውነት ወደ ዓለም የሚመጣው ነቢይ ነው” አሉ።'),
  ('7c767f81-15d1-5ee6-acb9-fabd1bc035a6', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '78440ba6-2947-5d64-ae6d-aeaf69b554bc', 11, 15, 'ጌታችን ኢየሱስም መጥተው ነጥቀው ሊያነግሡት እንደሚሹ ዐወቀባቸውና ብቻውን ወደ ተራራ ሄደ።'),
  ('0ea3012b-431a-59e8-affe-afe0e57927d2', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 1, 16, 'በመሸም ጊዜ ደቀ መዛሙርቱ ወደ ባሕር ወረዱ።'),
  ('8f8b8cc8-0284-5582-a88e-79e8bb4cde52', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 2, 17, 'ወደ ታንኳም ወጡ፤ ወደ ባሕር ማዶ ወደ ቅፍርናሆምም ሄዱ፤ እነሆም፥ ፈጽሞ ጨለማ ሆነ፤ ጌታችን ኢየሱስም ወደ እነርሱ ገና አልመጣም ነበር።'),
  ('80d8bca8-6c27-5705-ad91-7db3d6237de1', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 3, 18, 'ባሕሩ ግን ይታወክ ነበር፤ ጽኑ ነፋስ ይነፍስ ነበርና።'),
  ('ffbfedaa-7269-50f5-ac5a-77c7407557d5', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 4, 19, 'ሃያ አምስት ወይም ሠላሳ ምዕራፍ ያህል ከሄዱ በኋላ ጌታችን ኢየሱስን በባሕር ላይ ሲሄድ አዩት፤ ወደ ታንኳዉ በቀረበ ጊዜም ፈሩ።'),
  ('dc1ba383-7810-5469-a5da-73a6e6fec028', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 5, 20, 'እርሱም፥ “እኔ ነኝ፤ አትፍሩ” አላቸው።'),
  ('b9ced654-3e27-542c-ae70-667a8846cf61', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 6, 21, 'ወደ ታንኳውዪቱ ሊያወጡት ሲሹም ታንኳዪቱ ወዲያውኑ ሊሄዱ ወደ ወደዱበት ወደብ ደረሰች።'),
  ('a0ab86e8-988e-57b8-ab92-a7364663c880', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 7, 22, 'በማግሥቱም ከባሕሩ ዳር ቆመው የነበሩ ሰዎች ከአንዲት ታንኳ በቀር ከዚያ ሌላ ታንኳ እንዳልነበረ፥ ደቀ መዛሙርቱም ለብቻቸው ሄዱ እንጂ ጌታችን ኢየሱስ ከደቀ መዛሙርቱ ጋር ወደ ታንኳ እንዳልወጣ አዩ።'),
  ('cd843686-4a70-5c60-a280-352f949c73d6', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 8, 23, 'ደግሞም ጌታችን የባረከውን እንጀራ ከበሉበት ቦታ አቅራቢያ ከጥብርያዶስ ሌሎች ታንኳዎች መጥተው ነበር።'),
  ('df198c79-9804-536f-a358-09dd2f13930f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 9, 24, 'እነዚያ ሰዎችም ጌታችን ኢየሱስ፥ ደቀ መዛሙርቱም በዚያ እንዳልነበሩ ባዩ ጊዜ ጌታችን ኢየሱስን ይፈልጉት ዘንድ በእነዚያ ታንኳዎች ገብተው ወደ ቅፍርናሆም መጡ።'),
  ('56b4a5db-7693-5b3e-a77c-856fb8e52300', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '08173246-7b34-5fb9-a855-b08cc95afe8f', 10, 25, 'በባሕሩ ዳርም ባገኙት ጊዜ፥ “መምህር ሆይ፥ ወደዚህ መቼ መጣህ?” አሉት።'),
  ('abdda7fb-b626-560e-aba6-bb590078f144', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '1088eca0-c5b5-5022-a8d8-8646fe9e77e2', 1, 26, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እውነት እውነት እላችኋለሁ፤ እናንተ የምትፈልጉኝ እንጀራ ስለ በላችሁና ስለ ጠገባችሁ ነው እንጂ ተአምራት ስለ አያችሁ አይደለም።'),
  ('b6e1b2f1-213a-55de-af86-b45928d6848a', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '1088eca0-c5b5-5022-a8d8-8646fe9e77e2', 2, 27, 'የሰው ልጅ ለሚሰጣችሁ ለዘለዓለም ሕይወት ለሚኖር መብል ሥሩ እንጂ ለሚጠፋው መብል አይደለም፤ ይህን እግዚአብሔር አብ አትሞታልና።”'),
  ('9c0fa52a-847e-5f7b-a007-49cd72360eef', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '1088eca0-c5b5-5022-a8d8-8646fe9e77e2', 3, 28, '“እንግዲህ የእግዚአብሔርን ሥራ እንሠራ ዘንድ ምን እናድርግ?” አሉት።'),
  ('402d10c7-9101-5398-a980-b8143cbeb703', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '1088eca0-c5b5-5022-a8d8-8646fe9e77e2', 4, 29, 'ጌታችን ኢየሱስም መልሶ፥ “ይህ የእግዚአብሔር ሥራ እርሱ በላከው ታምኑ ዘንድ ነው፤” አላቸው።'),
  ('4ade46b5-dc05-5280-af0a-c19e0d43f900', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'c0f6ad15-72f3-5f45-a0e4-e37a3beca2a9', 1, 30, 'እነርሱም እንዲህ አሉት፥ “የምትሠራውን አይተን በአንተ እናምን ዘንድ ምን ተአምራት ታደርጋለህ?'),
  ('748a8a40-40c7-58ed-a9bb-fe98544bcba7', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'c0f6ad15-72f3-5f45-a0e4-e37a3beca2a9', 2, 31, 'አባቶቻችንስ ‘ሊበሉ እንጀራ ከሰማይ ሰጣቸው’ ተብሎ እንደ ተጻፈ በምድረ በዳ መና በሉ።'),
  ('5cf7f2a4-2c31-539a-aaa8-3f80dc1123fc', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'c0f6ad15-72f3-5f45-a0e4-e37a3beca2a9', 3, 32, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “እውነት እውነት እላችኋለሁ፤ ያን እንጀራ ከሰማይ የሰጣችሁ ሙሴ አይደለም፤ አባቴ ከሰማይ የእውነት እንጀራን ሰጥቶአችኋል እንጂ።'),
  ('4491427f-85b4-5432-a83f-92c93cc6e4ed', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'c0f6ad15-72f3-5f45-a0e4-e37a3beca2a9', 4, 33, 'የእግዚአብሔር እንጀራ ከሰማይ የሚወርድ፤ ለዓለምም ሕይወትን የሚሰጥ ነውና።”'),
  ('cb656f0f-11e4-56ea-a5d1-e6af67eabd3c', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'c0f6ad15-72f3-5f45-a0e4-e37a3beca2a9', 5, 34, 'እነርሱም፥ “አቤቱ ከዚያ እንጀራ ሁልጊዜ ስጠን” አሉት።'),
  ('33f9372e-10bc-58fc-af6c-491c115c0733', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd484e5d6-4d0b-58ea-a806-2fe27735a8af', 1, 35, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “የሕይወት እንጀራ እኔ ነኝ፤ ወደ እኔ የሚመጣ ከቶ አይራብም፤ በእኔ የሚያምንም ለዘለዓለም አይጠማም።'),
  ('97658e67-cdc9-5e0a-a929-7babd98860bf', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd484e5d6-4d0b-58ea-a806-2fe27735a8af', 2, 36, 'ነገር ግን እላችኋለሁ፤ አያችሁኝ፤ አላመናችሁብኝምም።'),
  ('66c33a55-80f9-599c-a097-d0e911f4479f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd484e5d6-4d0b-58ea-a806-2fe27735a8af', 3, 37, 'አብ የሚሰጠኝ ሁሉ ወደ እኔ ይመጣል፤ ወደ እኔ የሚመጣውንም ከቶ ወደ ውጭ አላወጣውም።'),
  ('e8b342ea-2a47-5ceb-a843-a860a1a833c6', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd484e5d6-4d0b-58ea-a806-2fe27735a8af', 4, 38, 'ከሰማይ የወረድሁ የላከኝን ፈቃድ እንጂ፥ ፈቃዴን ላደርግ አይደለምና።'),
  ('e79fefb1-23fb-5066-ae85-dd6051599dcc', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd484e5d6-4d0b-58ea-a806-2fe27735a8af', 5, 39, 'የላከኝ የአብ ፈቃድም ይህ ነው፤ ከሰጠኝ ሁሉ አንድስ እንኳ ቢሆን እንዳይጠፋ ነው፤ ነገር ግን እኔ በኋለኛዪቱ ቀን አስነሣዋለሁ።'),
  ('cd57230e-facf-5780-a351-332f0be38be1', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd484e5d6-4d0b-58ea-a806-2fe27735a8af', 6, 40, 'የአባቴ ፈቃዱ ይህ ነው፤ ወልድን አይቶ የሚያምንበት ሁሉ የዘለዓለም ሕይወትን እንዲያገኝ ነው፤ እኔም በመጨረሻዪቱ ቀን አስነሣዋለሁ።”'),
  ('bfd643ad-0ca5-500c-a168-c622fa879c9c', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 1, 41, 'አይሁድም ስለ እርሱ አንጐራጐሩ፤ “ከሰማይ የወረደ የሕይወት እንጀራ እኔ ነኝ” ብሎአቸዋልና።'),
  ('5ebdeb8b-af88-5e4f-affe-07d64f6325c9', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 2, 42, '“እኛ አባቱንና እናቱን የምናውቃቸው ይህ የዮሴፍ ልጅ ኢየሱስ አይደለምን? እንግዲህ እንዴት ከሰማይ ወረድሁ ይለናል?” አሉ።'),
  ('c76caed3-ef5a-52df-abff-de93001eb8f3', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 3, 43, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እርስ በርሳችሁ አታንጐራጕሩ።'),
  ('5d98ec33-d2d8-5111-a430-096cb420f506', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 4, 44, 'የላከኝ አብ ካልሳበው በቀር ወደ እኔ መምጣትን የሚችል የለም፤ እኔም በመጨረሻዪቱ ቀን አስነሣዋለሁ።'),
  ('b57d475c-4ab7-5c13-a005-b0adddbd6bf4', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 5, 45, '‘ሁሉም ከእግዚአብሔር ዘንድ የተማሩ ይሆናሉ’ ተብሎ በነቢያት መጽሐፍ ተጽፎአል፤ እንግዲህ ከአባቴ የሰማ ሁሉ ተምሮ ወደ እኔ ይመጣል።'),
  ('97b9e7df-68ee-5336-ada1-e1e45c9fd26e', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 6, 46, 'ከእግዚአብሔር ከሆነው በቀር አብን ያየው ማንም የለም፤ እርሱም አብን አየው።'),
  ('3ef22591-1066-511a-ae16-28c72558b593', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 7, 47, 'እውነት እውነት እላችኋለሁ፤ በእኔ የሚያምን የዘለዓለም ሕይወት አለው።'),
  ('e89555a2-356d-5017-a9ce-cdbe464ed9ba', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 8, 48, 'የሕይወት እንጀራ እኔ ነኝ።'),
  ('19528018-df57-5cb0-a759-b007e027d619', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 9, 49, 'አባቶቻችሁስ በምድረ በዳ መና በሉ፥ ሞቱም።'),
  ('a3a65a61-1457-522f-a099-ae7fecc8f850', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'b0f4b245-25a1-5d1d-adf1-f394a25c97c8', 10, 50, 'ከእርሱ የበላ ሁሉ እንዳይሞት ከሰማይ የወረደ እንጀራ ይህ ነው።”'),
  ('2917da01-792c-5672-a1e1-d899f0b8556b', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 1, 51, '“ከሰማይ የወረደ የሕይወት እንጀራ እኔ ነኝ፤ ከዚህ እንጀራ የሚበላ ለዘለዓለም ይኖራል፤ ስለ ዓለም ሕይወት የምሰጠው ይህ እንጀራ ሥጋዬ ነው።”'),
  ('11a25f32-1410-5cd6-a034-1c692e198324', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 2, 52, 'አይሁድም፥ “ይህ እንበላ ዘንድ ሥጋውን ሊሰጠን እንዴት ይችላል?” ብለው እርስ በርሳቸው ተከራከሩ።'),
  ('86408359-2678-5121-a706-8955a4ca5943', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 3, 53, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “እውነት እውነት እላችኋለሁ፤ የሰውን ልጅ ሥጋ ካልበላችሁ፥ ደሙንም ካልጠጣችሁ የዘለዓለም ሕይወት የላችሁም።'),
  ('a2dcde3c-7b24-5fc9-af79-2f94b5db2a24', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 4, 54, 'ሥጋዬን የሚበላ፥ ደሜንም የሚጠጣ የዘለዓለም ሕይወት አለው፤ እኔም በኋለኛዪቱ ቀን አነሣዋለሁ።'),
  ('3e6701aa-4dbc-5b3b-af2b-dd3315b058af', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 5, 55, 'ሥጋዬ እውነተኛ መብል ነውና፤ ደሜም እውነተኛ መጠጥ ነውና።'),
  ('e298a0df-0b72-5a41-a499-d12a8b112c94', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 6, 56, 'ሥጋዬን የሚበላ፥ ደሜንም የሚጠጣ በእኔ ይኖራል፤ እኔም በእርሱ እኖራለሁ።'),
  ('fe3535b7-b737-5c4e-a5df-c51220763cb0', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 7, 57, 'የላከኝ አብ ሕያው እንደ ሆነ፥ እኔም ስለ አብ ሕያው ነኝ፤ ሥጋዬንም የሚበላ እርሱ ደግሞ ስለ እኔ ሕያው ሆኖ ይኖራል።'),
  ('49918a41-4f1a-50f4-ac2f-51fff88ff18a', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 8, 58, 'ከሰማይ የወረደ እንጀራ ይህ ነው፤ አባቶቻችሁ በልተውት እንደሞቱበት ያለ መና አይደለም፤ ይህን እንጀራ የሚበላ ግን ለዘለዓለም ሕያው ሆኖ ይኖራል።”'),
  ('6963add3-be08-5c5d-a6ff-651adceeb91f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', '242c711a-8689-5ee5-a5a1-9cab46b02425', 9, 59, 'በቅፍርናሆምም በምኵራብ ሲያስተምራቸው ይህን ተናገረ፤'),
  ('3f88802f-e8a9-59e1-a319-cbd29de49f12', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 1, 60, 'ከደቀ መዛሙርቱም ብዙዎቹ ይህን ሰምተው፥ “ይህ ነገር የሚያስጨንቅ ነው፤ ማንስ ሊሰማው ይችላል?” አሉ።'),
  ('a6ce1f98-b034-50fd-aeb5-d7c651162f59', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 2, 61, 'ጌታችን ኢየሱስም ደቀ መዛሙርቱ ስለዚህ ነገር እንደ አንጐራጐሩ በልቡ ዐወቀባቸውና እንዲህ አላቸው፥ “ይህ ያሰናክላችኋልን?'),
  ('2f103fb3-01f8-5996-a2cf-c445a7a80733', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 3, 62, 'እንግዲህ የሰው ልጅ ቀድሞ ወደ ነበረበት ሲያርግ ብታዩት እንዴት ይሆን?'),
  ('03445531-a2d2-5974-a562-9a0ce1f26515', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 4, 63, 'ሕይወትን የሚሰጥ መንፈስ ነው፤ ሥጋ ግን አንዳች አይጠቅምም፤ ይህም እኔ የምነግራችሁ ቃል መንፈስ ነው፤ ሕይወትም ነው።'),
  ('c9e7e368-48d0-55e2-af3d-223caced282b', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 5, 64, 'ነገር ግን ከእናንተ ውስጥ የማያምኑ አሉ፤” ጌታችን ኢየሱስ ከጥንት ጀምሮ የማያምኑበት እነማን እንደ ሆኑ፥ የሚያሲዘውም ማን እንደ ሆነ ያውቅ ነበርና።'),
  ('10b04595-a5e3-513b-a92d-f447f20555f7', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 6, 65, 'እንዲህም አላቸው፥ “ስለዚህ እላችኋለሁ፤ ከአብ ካልተሰጠው በቀር ወደ እኔ መምጣት የሚቻለው የለም።”'),
  ('29a4ca71-11df-5582-a9cf-5e4fbcd4221f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 7, 66, 'ስለዚህም ከደቀ መዛሙርቱ ወደ ኋላቸው የተመለሱ ብዙዎች ናቸው፤ ከዚያም ወዲህ አብረውት አልሄዱም።'),
  ('cbe2cbe8-b698-5dc9-ae99-3eba55b2e57d', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 8, 67, 'ጌታችን ኢየሱስም ዐሥራ ሁለቱን፥ “እናንተ ደግሞ ልትሄዱ ትሻላችሁን?” አላቸው።'),
  ('9f615746-fd25-5ec8-ae3e-dba054fa9c4f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 9, 68, 'ስምዖን ጴጥሮስም መልሶ እንዲህ አለው፥ “አቤቱ፥ የዘለዓለም የሕይወት ቃል እያለህ ወደ ማን እንሄዳለን?'),
  ('231604d3-d415-5e4e-ab95-90977d2c561f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 10, 69, 'እኛስ የሕያው እግዚአብሔር ልጅ ክርስቶስ አንተ እንደ ሆንህ አምነናል፤ አውቀናልም።”'),
  ('1964129e-d823-57e4-afc3-d9e450e44ace', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 11, 70, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እኔ እናንተን ዐሥራ ሁለታችሁን መርጫችሁ የለምን? ነገር ግን ከእናንተ አንዱ ሰይጣን ነው።”'),
  ('392cbfca-0318-54ac-a34d-32c67365306f', 'd9a1586d-a0d3-53e6-a4ac-2ffcebfb3fe8', 'd4d9defd-b302-553a-aaec-0033a12a0313', 12, 71, 'ይህንም ስለ ስምዖን ልጅ ስለ አስቆሮታዊው ይሁዳ ተናገረ፤ እርሱ ያሲዘው ዘንድ አለውና፤ እርሱም ከዐሥራ ሁለቱ አንዱ ነበር።'),
  ('fce2f0ba-383d-56f2-acab-96b63ead855f', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 1, 1, 'ከዚህ በኋላም ጌታችን ኢየሱስ በገሊላ ይመላለስ ነበረ፤ ወደ ይሁዳ ምድርም ሊሄድ አልወደደም፤ አይሁድ ሊገድሉት ይሹ ነበርና።'),
  ('ddf6f0e7-f9e8-5585-a431-6a7078432c40', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 2, 2, 'የአይሁድም የዳስ በዓላቸው ደርሶ ነበር።'),
  ('bf16db37-8b39-5623-ad8a-e82f40dca779', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 3, 3, 'ወንድሞቹም ጌታችን ኢየሱስን እንዲህ አሉት- “ደቀ መዛሙርትህ የምትሠራውን ሥራህን እንዲያዩ ከዚህ ወጥተህ ወደ ይሁዳ ሀገር ሂድ።'),
  ('657ba93d-8c35-53e2-ac01-35bdd15b178a', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 4, 4, 'ሊገለጥ ወድዶ ሳለ በስውር አንዳች ነገር የሚያደርግ ማንም የለምና፤ አንተ ግን ይህን የምታደርግ ከሆነ ራስህን ለዓለም ግለጥ።'),
  ('e090d97a-1a61-5c65-a234-a73fdfd86d5f', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 5, 5, 'ወንድሞቹ ገና አላመኑበትም ነበርና።'),
  ('a59d4215-4005-54b1-a971-482fa2625ead', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 6, 6, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “ጊዜዬ ገና አልደረሰም፤ የእናንተ ጊዜ ግን ዘወትር የተዘጋጀ ነው።'),
  ('7f33cc00-c4cf-5c38-a332-bddfd28d7c7d', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 7, 7, 'ዓለም እናንተን ሊጠላችሁ አይችልም፤ እኔን ግን ይጠላኛል፤ ሥራዉ ክፉ እንደ ሆነ እኔ እመሰክርበታለሁና።'),
  ('bb9c5e55-e3de-5e62-aacb-d2b181cf64ad', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 8, 8, 'እናንተም ወደዚህ በዓል ውጡ፤ እኔ አሁን ወደዚህ በዓል አልወጣም፤ ጊዜዬ ገና አልደረሰምና።”'),
  ('6e2055ee-ec0a-5c64-a703-db7f1b5b8d3f', '89b34566-2f30-5a13-a188-e923d93be45d', 'f4239a8f-513f-531f-a546-718d6bce24ff', 9, 9, 'እርሱም እንዲህ ብሎአቸው በገሊላ ቀረ።'),
  ('b1473c0f-5358-588e-ae67-d8a8653fc2f7', '89b34566-2f30-5a13-a188-e923d93be45d', '03fd6d2a-0d17-5bda-a9df-10d39e00aca2', 1, 10, 'ወንድሞቹ ለበዓል ከወጡ በኋላ፥ እርሱም ያንጊዜ በግልጥ ሳይሆን ተሰውሮ ወጣ።'),
  ('b1363f93-d9ca-57a3-a883-f750c0f3e1a2', '89b34566-2f30-5a13-a188-e923d93be45d', '03fd6d2a-0d17-5bda-a9df-10d39e00aca2', 2, 11, 'አይሁድም፥ “ያ ወዴት ነው?” እያሉ በበዓሉ ይፈልጉት ጀመር።'),
  ('c4f08948-8b08-5339-a68b-b6cd9bea210f', '89b34566-2f30-5a13-a188-e923d93be45d', '03fd6d2a-0d17-5bda-a9df-10d39e00aca2', 3, 12, 'ሕዝቡም ስለ እርሱ ብዙ አንጐራጐሩ፥ “ደግ ሰው ነው” ያሉ ነበሩ፤ ሌሎች ግን፥ “አይደለም፤ ሕዝቡን ያስታል እንጂ” አሉ።'),
  ('05615880-9a47-59c8-a82b-13c2838bfc5c', '89b34566-2f30-5a13-a188-e923d93be45d', '03fd6d2a-0d17-5bda-a9df-10d39e00aca2', 4, 13, 'ነገር ግን፥ አይሁድን በመፍራት የእርሱን ነገር ገልጦ የተናገረ አልነበረም።'),
  ('b393d994-7bbf-5373-a8eb-ec0e7dc1bac6', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 1, 14, 'በበዓሉ ቀኖች እኩሌታም ጌታችን ኢየሱስ ወደ መቅደስ ወጥቶ ያስተምር ጀመረ።'),
  ('6f2bf16b-a8ce-5d3d-a268-fece68b03a4a', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 2, 15, 'አይሁድም፥ “ይህ ሳይማር መጽሐፍን እንዴት ያውቃል?” እያሉ ትምህርቱን አደነቁ።'),
  ('b688b201-bc23-5ff3-ab11-4524788f7b5d', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 3, 16, 'ስለዚህም ጌታችን ኢየሱስ መልሶ እንዲህ አላቸው፥ “ትምህርቴ የላከኝ ናት እንጂ የእኔ አይደለችም።'),
  ('06e95883-9a94-5ebb-afb1-b3946744f24c', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 4, 17, 'ፈቃዱን ሊያደርግ የሚወድድ ግን ትምህርቴ ከእግዚአብሔር ዘንድ እንደ ሆነች፥ የምናገረውም ከራሴ እንዳይደለ እርሱ ያውቃል።'),
  ('10c15e7d-0440-5884-aa27-86cf2c619209', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 5, 18, 'ከራሱ የሚናገር የራሱን ክብር ይሻል፤ የላከውን ያከብር ዘንድ የሚፈልግ ግን እውነተኛ ነው፤ ሐሰትም የለበትም።'),
  ('a21de1c5-ca8a-5aff-ab6d-48e4ab438164', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 6, 19, 'ሙሴ ኦሪትን ሰጥቶአችሁ የለምን? ከእናንተ አንዱ ስንኳ ኦሪትን የሚያደርግ የለም፤ እንግዲህ ልትገድሉኝ ለምን ትሻላችሁ?”'),
  ('1e5518f1-8d01-54d7-a40c-8837b5f8d04a', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 7, 20, 'ሕዝቡም፥ “ጋኔን አለብህን? ማን ሊገድልህ ይሻል?” ብለው መለሱለት።'),
  ('34d3c371-cedb-57d1-ab9a-001f1472f250', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 8, 21, 'ጌታችን ኢየሱስም መልሶ አላቸው፥ “አንድ ሥራ ሠራሁ፤ ሁላችሁም አደነቃችሁ።'),
  ('bfb04be2-c389-5c03-a8fa-9cebdf2d603a', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 9, 22, 'ስለዚህ ሙሴ ግዝረትን ሰጥቶአችሁ ነበር፤ ነገር ግን ከአባቶች ናት እንጂ ከሙሴ አይደለችም፤ በሰንበትም ሰውን ትገዝሩታላችሁ።'),
  ('453a83ed-9486-5039-a166-3e6cf924191c', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 10, 23, 'የሙሴ ሕግ እንዳይሻር ሰው በሰንበት የሚገዘር ከሆነ እንግዲያ ሰውን ሁለንተናውን በሰንበት ባድነው ለምን ትነቅፉኛላችሁ?'),
  ('1f9a2200-bd6e-5266-ae2a-bdff7a6aa037', '89b34566-2f30-5a13-a188-e923d93be45d', 'bd738b38-1a44-5f3c-a9e7-49b8ed8c8e2b', 11, 24, 'የእውነት ፍርድ ፍረዱ እንጂ ለሰው ፊት በማድላት አትፍረዱ።”'),
  ('94231675-a256-5321-aecd-9a05d47a3876', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 1, 25, 'ከኢየሩሳሌም ሰዎችም እንዲህ የሚሉ ነበሩ፥ “ይህ አይሁድ ሊገድሉት የሚሹት አይደለምን?'),
  ('aef07411-4f94-5600-a6c8-8dda9e553257', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 2, 26, 'እነሆ፥ እርሱ በገሀድ ይናገራል፤ እነርሱ ግን ምንም የሚሉት የለም፤ ይህ በእውነት ክርስቶስ እንደ ሆነ ምናልባት አለቆች ዐውቀው ይሆን?'),
  ('4fda7ad5-09bf-5c5d-aa9e-cea2f83f9c70', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 3, 27, 'ነገር ግን ይህን ከየት እንደ ሆነ እናውቃለን፤ ክርስቶስ በሚመጣበት ጊዜስ ከወዴት እንደ ሆነ ማንም አያውቅም”።'),
  ('ea51b8bf-0fef-5aa0-a875-92cfe59f81f3', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 4, 28, 'ጌታችን ኢየሱስም በመቅደስ ሲያስተምር ቃሉን ከፍ አድርጎ እንዲህ አለ፥ “እኔን ታውቁኛላችሁ፤ ከወዴትም እንደ ሆንሁ ታውቃላችሁ፤ እኔ ራሴ የመጣሁ አይደለሁም፤ ነገር ግን እናንተ የማታውቁት የላከኝ እውነተኛ አለ።'),
  ('24f28af3-9acb-5a19-a186-3ee86bda34de', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 5, 29, 'እኔ ግን አውቀዋለሁ፤ እኔ ከእርሱ ነኝና፥ እርሱም ልኮኛልና።'),
  ('e871c670-656a-5a4d-a21d-b65f98d6807f', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 6, 30, 'ስለዚህም ሊይዙት ወደው ነበር፤ ነገር ግን እጁን በእርሱ ላይ ያነሣ የለም፤ ጊዜዉ ገና አልደረሰም ነበርና።'),
  ('8ef82c2f-51d4-59d2-ac7b-e8eed1cca299', '89b34566-2f30-5a13-a188-e923d93be45d', 'fca881b8-0f58-5a51-a6c4-005dac299381', 7, 31, 'ከሕዝቡም ብዙዎች አመኑበትና፥ “በውኑ ክርስቶስ በሚመጣበት ጊዜ ይህ ሰው ካደረገው ተአምራት የሚበልጥ ያደርጋልን?” አሉ።'),
  ('7e8efb16-3f99-544f-a63b-dc969972112d', '89b34566-2f30-5a13-a188-e923d93be45d', '5811967d-80a7-56cd-ad52-bf713981c714', 1, 32, 'ፈሪሳውያንም ሕዝቡ በእርሱ ምክንያት እንደ አጕረመረሙ ሰሙ፤ የካህናት አለቆችና ፈሪሳውያንም ይይዙት ዘንድ ሎሌዎቻቸውን ላኩ።'),
  ('bf4c3992-8f6e-573a-a18f-108c5dfab53a', '89b34566-2f30-5a13-a188-e923d93be45d', '5811967d-80a7-56cd-ad52-bf713981c714', 2, 33, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “ጥቂት ቀን አብሬአችሁ እኖራለሁ፤ ከዚህም በኋላ ወደ ላከኝ እሄዳለሁ።'),
  ('602be2a6-2462-5847-ade0-0123f577cd30', '89b34566-2f30-5a13-a188-e923d93be45d', '5811967d-80a7-56cd-ad52-bf713981c714', 3, 34, 'ትሹኛላችሁ፤ አታገኙኝምም፤ እኔ ወደምሄድበትም እናንተ መምጣት አትችሉም።”'),
  ('d2c5c74f-13eb-5a15-ade9-6e1ad3987037', '89b34566-2f30-5a13-a188-e923d93be45d', '5811967d-80a7-56cd-ad52-bf713981c714', 4, 35, 'አይሁድም እርስ በርሳቸው እንዲህ አሉ፥ “እኛ ልናገኘው የማንችል ይህ ወዴት ይሄዳል? ወይስ የግሪክን ሰዎች ለማስተማር በግሪክ ሀገር ወደ ተበተኑት ይሄዳልን?'),
  ('9b8fec76-c35c-5241-a65b-25d08e884d12', '89b34566-2f30-5a13-a188-e923d93be45d', '5811967d-80a7-56cd-ad52-bf713981c714', 5, 36, '‘ትሹኛላችሁ፤ አታገኙኝምም፤ እኔ ወደምሄድበት እናንተ መምጣት አትችሉም’ የሚለን ይህ ነገር ምንድን ነው?”'),
  ('e613c49b-7fbf-5543-aa77-695c68681bfa', '89b34566-2f30-5a13-a188-e923d93be45d', 'd5007978-c197-57ab-a2ed-a73f4465783a', 1, 37, 'በኋለኛዪቱ በታላቅዋ የበዓል ቀንም ጌታችን ኢየሱስ ቆመና ድምፁን ከፍ አድርጎ እንዲህ አለ፥ “የተጠማ ወደ እኔ ይምጣና ይጠጣ።'),
  ('5a576090-506a-593e-a128-419a290a6cd6', '89b34566-2f30-5a13-a188-e923d93be45d', 'd5007978-c197-57ab-a2ed-a73f4465783a', 2, 38, 'በእኔም የሚያምን መጽሐፍ እንደ ተናገረ የሕይወት ውኃ ወንዝ ከሆዱ ይፈስሳል።”'),
  ('8bb983d2-ff89-5507-ac4d-bd026bb8b18c', '89b34566-2f30-5a13-a188-e923d93be45d', 'd5007978-c197-57ab-a2ed-a73f4465783a', 3, 39, 'ይህንም የሚያምኑበት ሰዎች ይቀበሉት ዘንድ ስለ አላቸው ስለ መንፈስ ቅዱስ ተናገረ፤ ጌታችን ኢየሱስ ገና ስላልከበረ መንፈስ ቅዱስ ገና አልወረደም ነበርና።'),
  ('044141f2-a1e7-503b-aaa1-e449f21169f4', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 1, 40, 'ከሕዝቡም ብዙ ሰዎች ይህን ነገር ሰምተው “በእውነት ይህ ነቢይ ነው” አሉ።'),
  ('4a9fd916-024f-510e-ab7c-018858d465ae', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 2, 41, '“ክርስቶስ ነው” ያሉም አሉ፤ እኩሌቶቹም እንዲህ አሉ፥ “በውኑ ክርስቶስ ከገሊላ ይወጣልን?'),
  ('ac5a16bc-8f2f-5835-a348-9f5e40c7f5b0', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 3, 42, 'መጽሐፍ ‘ክርስቶስ ከዳዊት ዘርና ከዳዊት ከተማ ከቤተ ልሔም ይመጣል’ ይል የለምን?”'),
  ('986e1859-716b-5f13-a11d-7b2e07a02ac4', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 4, 43, 'ስለ እርሱም ሕዝቡ እርስ በርሳቸው ተለያዩ።'),
  ('de78903f-d2e5-50c5-aa7f-6a9d6a26ce33', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 5, 44, 'ከእነርሱም ሊይዙት የወደዱ ነበሩ፤ ነገር ግን በእርሱ ላይ እጁን ያነሣ የለም።'),
  ('ec248f81-773f-57c6-a10e-cf25890e42f2', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 6, 45, 'ሎሌዎቹም ወደ ካህናት አለቆችና ወደ ፈሪሳውያን ተመለሱ፤ እነርሱም፥ “ያላመጣችሁት ለምንድን ነው?” አሉአቸው።'),
  ('079d1567-8455-5522-af34-80408c4d78d0', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 7, 46, 'ሎሌዎቻቸውም መልሰው፥ “ያ ሰው እንደ ተናገረው ያለ ከቶ ሰው አልተናገረም” አሉአቸው።'),
  ('91861802-b7cc-5cd3-a4a8-b01561a36031', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 8, 47, 'ፈሪሳውያንም መልሰው እንዲህ አሉአቸው፥ “እናንተም ደግሞ ተሳሳታችሁን?'),
  ('45f5509b-6e75-5de3-a533-9725483596de', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 9, 48, 'ከአለቆች ወይም ከፈሪሳውያን ያመነበት አለን?'),
  ('facb7f23-e544-5adf-abeb-44e0bddd1b14', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 10, 49, 'ኦሪትን ከማያውቁ ከእነዚህ ስሑታን ሕዝብ በቀር፤ እነርሱም የተረገሙ ናቸው።”'),
  ('505cacef-92a3-571b-af92-d7c061bca9c7', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 11, 50, 'ከእነርሱም አንዱ ቀድሞ በሌሊት ወደ ጌታችን ኢየሱስ የሄደው ኒቆዲሞስ እንዲህ አላቸው።'),
  ('3bf6e758-1b6a-5cf3-a5b5-9adcf112f52e', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 12, 51, '“ሕጋችን አስቀድሞ ሳይሰማ፤ የሠራውንም ሳያውቅ በሰው ይፈርዳልን?”'),
  ('752a17c7-dab7-5409-a866-01c6baa0f36e', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 13, 52, 'እነርሱም መልሰው፥ “አንተም ደግሞ ከገሊላ ነህን? ከገሊላ ነቢይ እንደማይነሣ መርምርና እይ” አሉት።'),
  ('6a6ef058-170e-5c2a-aa45-c1bfca6be27f', '89b34566-2f30-5a13-a188-e923d93be45d', 'f49af632-7628-51a8-adfc-df0fc780bfe8', 14, 53, 'ሁሉም እያንዳንዳቸው ወደ ቤታቸው ሄዱ።'),
  ('a9a1a2ef-c485-56b7-a739-7943a1a168fe', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 1, 1, 'ጌታችን ኢየሱስም ወደ ደብረ ዘይት ሄደ።'),
  ('aba50131-912b-59d7-a79e-ea7e60c7af59', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 2, 2, 'በጥዋትም ገስግሦ ዳግመኛ ወደ ቤተ መቅደስ ገባ፤ ሕዝቡም ሁሉ ወደ እርሱ ተሰበሰቡ፤ እርሱም ተቀምጦ ያስተምራቸው ጀመር።'),
  ('f4dd5297-3327-5c7a-a74c-d80a0b70502d', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 3, 3, 'ጻፎችና ፈሪሳውያንም በዝሙት የተያዘች ሴት ወደ እርሱ አምጥተው በመካከል አቆሙአት።'),
  ('6747eef7-b6b6-5e19-a958-53b19784608d', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 4, 4, 'እንዲህም አሉት፥ “መምህር ሆይ፥ ይቺን ሴት ስታመነዝር አግኝተን ያዝናት።'),
  ('2f561b25-c21c-5bad-a328-fe7deac97528', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 5, 5, 'እንደዚችም ያለችው በድንጋይ እንድትደበደብ ሙሴ በኦሪት አዘዘን፤ እንግዲህ አንተ ስለ እርስዋ ምን ትላለህ?”'),
  ('17870dd7-4fef-5f99-ae78-526a5bafce2c', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 6, 6, 'በእርሱም ላይ ምክንያት ሊያገኙ ሲፈትኑት ይህን አሉ፤ ጌታችን ኢየሱስም ጐንበስ ብሎ በጣቱ በምድር ላይ ጻፈ።'),
  ('7872df0b-d9f5-5e5c-aa81-1f9a44b15ab6', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 7, 7, 'ብዙ ጊዜ መላልሰው በጠየቁት ጊዜም ዐይኖቹን አንሥቶ፥ “ከእናንተ ኀጢኣት የሌለበት አስቀድሞ ድንጋይ ይጣልባት” አላቸው።'),
  ('dd4635cf-a085-5fdd-a5d0-9fb39778d5df', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 8, 8, 'ዳግመኛም ጐንበስ ብሎ በጣቱ በምድር ላይ ጻፈ።'),
  ('d60af557-04b2-5fa6-a123-a0394d75e403', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 9, 9, 'እነርሱ ግን ይህን በሰሙ ጊዜ ኅሊናቸው ወቅሶአቸው ከሽማግሌዎች ጀምሮ እስከ ኋለኞቹ ድረስ፥ አንዳንድ እያሉ ወጡ፤ ጌታችን ኢየሱስም ብቻውን ቀረ፤ ሴትዮዪቱም በመካከል ቆማ ነበር።'),
  ('b0de6563-b8a3-5585-aad1-53908d280790', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 10, 10, 'ጌታችን ኢየሱስም ቀና ብሎ ወደ እርስዋ ተመለከተና እንዲህ አላት፥ “አንቺ ሴት፥ የሚከሱሽ ወዴት አሉ?”'),
  ('373385c1-99e0-5d60-ab7b-f80cc3a28550', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1a71d152-69ab-50fc-ac50-22c9e07fb1ab', 11, 11, 'እርስዋም፥ “ጌታ ሆይ፥ የማየው የለም” ብላ መለሰችለት፤ ጌታችን ኢየሱስም፥ “እኔም አልፈርድብሽም፤ ወደ ቤትሽ ሂጂ፤ ከእንግዲህ ወዲህ ዳግመኛ ኀጢኣት አትሥሪ” አላት።'),
  ('fa144406-8487-58d0-aa6d-cf914d924271', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 1, 12, 'ዳግመኛም ጌታችን ኢየሱስ፥ “የዓለም ብርሃን እኔ ነኝ፤ የሚከተለኝ የሕይወት ብርሃንን ያገኛል እንጂ በጨለማ ውስጥ አይመላለስም” ብሎ ተናገራቸው።'),
  ('867e771d-c23b-53c2-a33e-cf4f14e7d196', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 2, 13, 'ፈሪሳውያንም፥ “አንተ ስለ ራስህ ትመሰክራለህ፤ እንግዲያስ ምስክርነትህ እውነት አይደለም” አሉት።'),
  ('a151c684-9b74-5dfb-a540-909689bb7b5e', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 3, 14, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እኔ ስለራሴ ብመሰክርም ምስክርነቴ እውነት ነው፤ ከየት እንደመጣሁ፥ ወዴት እንደምሄድም አውቃለሁና፤ እናንተ ግን ከየት እንደ መጣሁ ወዴት እንደምሄድም አታውቁም።'),
  ('76648cda-f7cd-5dba-a1e4-37cc86c90cce', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 4, 15, 'እናንተ ሥጋዊ ፍርድን ትፈርዳላችሁ፤ እኔ ግን በማንም አልፈርድም።'),
  ('305171b3-9e1e-5f29-a0e6-475d554d3f75', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 5, 16, 'እኔ ብፈርድም እውነትን እፈርዳለሁ፤ እኔና የላከኝ አብ ነን እንጂ አንድ ብቻዬን አይደለሁምና።'),
  ('802b4960-a395-5d76-a1fb-4ef23d29c4fa', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 6, 17, 'የሁለት ሰዎች ምስክርነት የታመነ እንደ ሆነ በሕጋችሁ ተጽፎአል።'),
  ('10abc04e-537c-5c10-ae16-3a30e1f19ea9', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 7, 18, 'እኔ ስለ ራሴ ምስክር ነኝ፤ የላከኝ አብም ይመሰክርልኛል።”'),
  ('4fa97c53-5c11-5f06-a625-1e9790d850ee', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 8, 19, 'እነርሱም፥ “አባትህ የት ነው?” አሉት፤ ጌታችን ኢየሱስም፥ “እኔን አታውቁም፤ አባቴንም አታውቁም፤ እኔንስ ብታውቁ አባቴንም ባወቃችሁት ነበር” ብሎ መለሰላቸው።'),
  ('2ed63309-daa7-5271-a82f-c01195c24cec', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1d9f4a81-05be-5a67-aa7a-3b1b1e331eb4', 9, 20, 'ጌታችን ኢየሱስም በቤተ መቅደስ ሲያስተምራቸው በሙዳየ ምጽዋት አጠገብ ይህን ተናገራቸው፤ ነገር ግን አልያዙትም፤ ጊዜው ገና አልደረሰም ነበርና።'),
  ('1057f88f-d3eb-55e1-a0c5-14a43137d50c', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 1, 21, 'ዳግመኛም ጌታችን ኢየሱስ፥ “እኔ እሄዳለሁ ትሹኛላችሁም፤ ነገር ግን አታገኙኝም፤ በኀጢኣታችሁም ትሞታላችሁ፤ እኔ ወደምሄድበትም እናንተ መምጣት አይቻላችሁም” አላቸው።'),
  ('093e3aed-3222-549b-a4b3-47666d6b9bb2', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 2, 22, 'አይሁድም፥ “እኔ ወደምሄድበት እናንተ መምጣት አትችሉም የሚለን እርሱ ራሱን ይገድል ይሆን? እንጃ!” አሉ።'),
  ('12ebb700-7279-596c-a7fd-a4aa0d762951', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 3, 23, 'እርሱም እንዲህ አላቸው፥ “እናንተስ ከታች ናችሁ፤ እኔ ግን ከላይ ነኝ፤ እናንተ ከዚህ ዓለም ናችሁ፤ እኔ ግን ከዚህ ዓለም አይደለሁም።'),
  ('7b5ca4cd-f29d-5af0-ae30-e7fe98cd3477', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 4, 24, 'እነሆ፥ በኀጢኣታችሁ ትሞታላችሁ እንዳልኋችሁ፥ እኔ እንደ ሆንሁ ባታምኑ በኀጢኣትችሁ ትሞታላችሁ።”'),
  ('c17ebe6c-65cb-56b8-a687-a798c0363cd7', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 5, 25, 'እነርሱም፥ “አንተ ማነህ?” አሉት፤ ጌታችን ኢየሱስም እንዲህ አላቸው፥ “በመጀመሪያ ነግሬአችኋለሁ።'),
  ('ee4703fc-b2bc-5d9c-a039-9276e2e82e73', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 6, 26, 'ስለ እናንተ የምናገረውና የምፈርደው ብዙ አለኝ፤ የላከኝም እውነተኛ ነው፤ እኔ በእርሱ ዘንድ የሰማሁትን ለዓለም እናገራለሁ።”'),
  ('c47498dc-9ad0-52fb-a2a2-82bf3989b207', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 7, 27, 'ነገር ግን ስለ አብ እንደ ነገራቸው አላስተዋሉም።'),
  ('e0edb399-41c6-5b65-a383-1edc49a6d38c', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 8, 28, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “የሰውን ልጅ ከፍ ከፍ በአደረጋችሁት ጊዜ እኔ እንደ ሆንሁ ያንጊዜ ታውቃላችሁ፤ አባቴ እንደ አስተማረኝም እንዲሁ እናገራለሁ እንጂ የምናገረው ከእኔ አይደለም።'),
  ('06e04763-f4f3-5ef2-a063-1b92f3d69ff0', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 9, 29, 'የላከኝም ከእኔ ጋር አለ፤ አብ ብቻዬን አይተወኝም፤ እኔም ዘወትር ደስ የሚያሰኘውን አደርጋለሁ።”'),
  ('d4838bdf-e71c-5dee-a1c7-44650b54bb24', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', 'a97462b3-1209-5eb1-adc3-ee10cff57b34', 10, 30, 'ይህንም በተናገረ ጊዜ ብዙዎች በእርሱ አመኑ።'),
  ('f7e6d359-7900-5ead-abaf-afbe34feda9e', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 1, 31, 'ጌታችን ኢየሱስም ያመኑበትን አይሁድ እንዲህ አላቸው፥ “እናንተም በቃሌ ጸንታችሁ ብትኖሩ በእውነት ደቀ መዛሙርቴ ናችሁ።'),
  ('04a436b1-f2cf-5d1a-af3f-8a146bdd5f83', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 2, 32, 'እውነትንም ታውቋታላችሁ፤ እውነትም አርነት ታወጣችኋለች።”'),
  ('b00caa54-0b70-5695-ac4b-de0fd2257052', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 3, 33, 'እነርሱም መልሰው፥ “እኛ የአብርሃም ዘር ነን፤ ከሆነ ጀምሮ ለማንም ከቶ ባሮች አልሆንም፤ እንግዲህ እንዴት አርነት ትወጣላችሁ ትለናለህ?” አሉት።'),
  ('6f790e5d-4789-59ea-a286-0795495aeb74', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 4, 34, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እውነት እውነት እላችኋለሁ፤ ኀጢኣትን የሚሠራ ሁሉ የኀጢኣት ባርያ ነው።'),
  ('f5aff551-d997-5de1-ad00-add42e841b6f', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 5, 35, 'ባርያ ዘወትር በቤት አይኖርም፤ ልጅ ግን ለዘለዓለም ይኖራል።'),
  ('abde71c4-7ba7-5a3f-a77b-26b46008be13', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 6, 36, 'ወልድ አርነት ካወጣችሁ በእውነት አርነት የወጣችሁ ናችሁ።'),
  ('4a8bd291-eac5-5527-a151-1c8e963f07ad', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 7, 37, 'የአብርሃም ዘር እንደ ሆናችሁስ አውቃለሁ፤ ነገር ግን ቃሌ በእናንተ ዘንድ አይኖርምና ልትገድሉኝ ትሻላችሁ።'),
  ('0e28a199-ed77-5069-a646-d37733334ddf', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 8, 38, 'እኔ በአባቴ ዘንድ ያየሁትን እናገራለሁ፤ እናንተም በአባታችሁ ያያችሁትን ታደርጋላችሁ።”'),
  ('c0ed895e-93ef-5b07-a745-f78081fb7106', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 9, 39, 'እነርሱም መልሰው፥ “የእኛስ አባታችን አብርሃም ነው” አሉት፤ ጌታችን ኢየሱስም እንዲህ አላቸው፥ “የአብርሃም ልጆች ብትሆኑስ የአብርሃምን ሥራ በሠራችሁ ነበር።'),
  ('855d748b-c34d-5d7d-ae78-0309f10419ae', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 10, 40, 'አሁንም በእግዚአብሔር ዘንድ የሰማሁትን እውነት የምነግራችሁን ሰው ልትገድሉኝ ትሻላችሁ፤ አብርሃምስ እንዲህ አላደረገም።'),
  ('04358790-5613-54b5-ac79-ab1790611021', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 11, 41, 'እናንተ ግን የአባታችሁን ሥራ ትሠራላችሁ።” እነርሱም፥ “እኛ ከዝሙት አልተወለድንም፤ ነገር ግን አንድ አባት አለን፤ እርሱም እግዚአብሔር ነው” አሉት።'),
  ('a43f0f21-b1db-53a9-aa49-f5a626838122', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 12, 42, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “እግዚአብሔር አባታችሁ ቢሆንስ እኔን በወደዳችሁኝ ነበር፤ እኔ ከእግዚአብሔር ዘንድ ወጥቼ መጥቻለሁና፤ እኔ በገዛ እጄ የመጣሁ አይደለሁም፤ እርሱ ላከኝ እንጂ።'),
  ('db0f2f33-25f1-5430-a75e-aabdd31f0543', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 13, 43, 'እንግዲህ ቃሌን ለምን አታስተውሉም? ቃሌን መስማት ስለማትችሉ ነው።'),
  ('1cedc372-db34-5150-adf4-4b50804d8224', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 14, 44, 'እናንተስ ከአባታችሁ ከሰይጣን ናችሁ፤ የአባታችሁንም ፈቃድ ልታደርጉ ትወዳላችሁ፤ እርሱ ከጥንት ጀምሮ ነፍሰ ገዳይ ነው፤ በእውነትም አይቆምም፤ በእርሱ ዘንድ እውነት የለምና፤ ሐሰትንም በሚናገርበት ጊዜ ከራሱ አንቅቶ ይናገራል፤ ሐሰተኛ ነውና፤ የሐሰትም አባት ነውና።'),
  ('3b86b78d-24e2-5a29-a675-9eb655b35af4', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 15, 45, 'እኔ ግን እውነትን እናገራለሁና አታምኑኝም።'),
  ('b7fdb80f-bfe6-51d9-a499-3493d9e19a59', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 16, 46, 'ስለ ኀጢኣት ከእናንተ የሚወቅሰኝ ማን ነው? እኔ እውነት የምናገር ከሆንሁ ለምን አታምኑኝም?'),
  ('70e7ed57-e3d1-5545-a6a7-3acf489c5ab9', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 17, 47, 'ከእግዚአብሔር የሆነ የእግዚአብሔርን ቃል ይሰማል፤ ስለዚህ እናንተ አትሰሙኝም፤ ከእግዚአብሔር አይደላችሁምና።”'),
  ('8dce0241-b8d1-55ef-ac08-fc455d0734d2', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 18, 48, 'አይሁድም፥ “አንተ ሳምራዊ እንደ ሆንህ፥ ጋኔንም እንደ አለብህ መናገራችን በሚገባ አይደለምን?” ብለው ጠየቁት።'),
  ('2dee7e44-6688-5ffb-ada7-da84e432dbc1', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 19, 49, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እኔ አባቴን አከብራለሁ እንጂ ጋኔን የለብኝም፤ እናንተ ግን ትንቁኛላችሁ።'),
  ('7851d52d-274d-5c49-a9b7-3eb596c2342d', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 20, 50, 'እኔ ለራሴ ክብርን አልሻም፤ የሚሻ፥ የሚፈርድም አለ።'),
  ('59dbef41-1d41-5986-aa23-8baef438fa85', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 21, 51, 'እውነት እውነት እላችኋለሁ፤ ቃሌን የሚጠብቅ ለዘለዓለም ሞትን አይቀምስም።”'),
  ('1a16bb90-f48e-5bca-a01b-401bde3cd194', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 22, 52, 'አይሁድም እንዲህ አሉት፥ “አሁን ጋኔን እንዳለብህ ዐወቅን፤ አብርሃም ስንኳ ሞቶአል፤ ነቢያትም ሞተዋል፤ አንተ ግን ቃሌን የሚጠብቅ ለዘለዓለም ሞትን አይቀምስም ትላለህ።'),
  ('0482e27c-9708-53bb-aa6d-259615383dd3', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 23, 53, 'በውኑ ከሞተው ከአባታችን ከአብርሃም፥ አንተ ትበልጣለህን? ነቢያትም ሞቱ፤ ራስህን ማን ታደርጋለህ?”'),
  ('4d121b2e-1356-54d7-a825-d4a970f46b6e', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 24, 54, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እኔ ራሴን ባከብር ክብሬ ምንም አይጠቅመኝም፤ የሚያከብረኝስ እናንተ አምላካችን የምትሉት አባቴ አለ።'),
  ('80921a1f-7bb8-5624-a977-8282f120e8e0', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 25, 55, 'እናንተም አታውቁትም፤ እኔ ግን ኣውቀዋለሁ፤ አላውቀውም ብልም እንደ እናንተ ሐሰተኛ እሆናለሁ፤ እኔ አውቀዋለሁ ቃሉንም እጠብቃለሁ።'),
  ('8135bb48-f8a4-5c70-a395-76769521e4f8', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 26, 56, 'አባታችሁ አብርሃም የእኔን ቀን ያይ ዘንድ ተመኘ፤ አይቶም ደስ አለው።”'),
  ('0df632a0-dacd-55de-af4f-cb7757c54d95', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 27, 57, 'አይሁድም፥ “ገና አምሳ ዓመት ያልሞላህ እንዴት አብርሃምን አየህ?” አሉት።'),
  ('78da59a9-2a87-5163-a5a8-b7b58bc24cf6', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 28, 58, 'ጌታችን ኢየሱስም፥ “እውነት እውነት እላችኋለሁ፤ አብርሃም ሳይወለድ እኔ አለሁ።” አላቸው።'),
  ('2420930c-b6f6-5ff8-a5eb-a333cebe3896', 'ee91678b-80e5-5fe2-a20b-2a1d521ef9e6', '1dfd4056-65d4-5afe-ae63-36f83c123f4a', 29, 59, 'ሊደበድቡትም ድንጋይ አነሡ፤ ጌታችን ኢየሱስ ግን ተሰወራቸው፤ ከቤተ መቅደስም ወጣ፤ በመካከላቸውም አልፎ ሄደ።'),
  ('842ef06c-21c0-554b-afed-2a9b187b8404', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 1, 1, 'ከዚያም ሲያልፍ ዕዉር ሆኖ የተወለደውን ሰው አየ።'),
  ('2ae93c70-e762-5cdd-aab6-e27d61de1d0d', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 2, 2, 'ደቀ መዛሙርቱም፥ “መምህር ሆይ፥ ይህ ሰው ዕዉር ሆኖ የተወለደው በማን ኀጢኣት ነው? በራሱ ነውን? ወይስ በወላጆቹ?” ብለው ጠየቁት።'),
  ('6ce3920b-0edc-5ac4-a625-9c3c546ca45c', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 3, 3, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “የእግዚአብሔር ሥራ ሊገለጥበት ነው እንጂ እርሱ አልበደለም፤ ወላጆቹም አልበደሉም።'),
  ('ffac6ab5-d6c9-590c-a967-1e8b720a3dfe', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 4, 4, 'ነገር ግን ቀን ሳለ የላከኝን ሥራ ልሠራ ይገባኛል፤ ማንም ሥራ ሊሠራ የማይችልባት ሌሊት ትመጣለችና።'),
  ('c7057898-3254-5aac-a55c-02a4d271afd0', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 5, 5, 'በዓለም ሳለሁ፤ የዓለም ብርሃን እኔ ነኝ።”'),
  ('bc6b92c8-81f5-5347-ae05-fdb1ed5ece17', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 6, 6, 'ይህንም ብሎ በምድር ላይ ምራቁን እንትፍ አለ፤ በምራቁም ጭቃ አድርጎ የዕዉሩን ዐይኖች ቀባው።'),
  ('fbcc0932-766f-5d56-a39a-bf199faa01e6', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 7, 7, 'እንዲህም አለው፥ “ሂድና በሰሊሆም መጠመቂያ ታጠብ” ትርጓሜውም የተላከ ማለት ነው፤ ሄዶም ታጠበና እያየ ተመለሰ።'),
  ('3310d843-7573-5e01-a025-e0bdb7ad8306', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 8, 8, 'ጎረቤቶቹና ቀድሞ የሚያውቁት፥ ሲለምንም ያዩት የነበሩት ግን፥ “ይህ በመንገድ ተቀምጦ ይለምን የነበረው አይደለም?” አሉ።'),
  ('4a8171f6-cde4-5c85-adb1-7683e7e5ab0c', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 9, 9, '“ይህ እርሱ ነው” ያሉ አሉ፤ ሌሎችም፥ “አይደለም፤ ይመስለዋል እንጂ” አሉ፤ እርሱ ራሱ ግን፥ “እኔ ነኝ” አለ።'),
  ('de813975-ecf7-51ed-aa79-df00cee98a45', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 10, 10, 'እነርሱም፥ “ዐይኖችህ እንዴት ተገለጡ?” አሉት።'),
  ('084068d9-e814-50cd-ab32-55238f896ce3', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 11, 11, 'እርሱም መልሶ፥ “ኢየሱስ የሚባለው ሰው በምራቁ ጭቃ አድርጎ ዐይኖችን ቀባኝና ሂደህ በሰሊሆም ውኃ ታጠብ አለኝ፤ ሄጄም ታጠብሁና አየሁ” አላቸው።'),
  ('6587d128-ecea-5637-a585-89677bd174d7', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 12, 12, 'አይሁድም፥ “ሰውየው የት አለ?” አሉት፤ እርሱም፥ “አላውቅም” አላቸው።'),
  ('699ec7c0-dac9-5331-ad5a-7663d9d8a28d', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 13, 13, 'ያን ዕዉር ሆኖ የተወለደውንም ሰው ወደ ፈሪሳውያን ወሰዱት።'),
  ('dc1b29f6-52ef-541f-a8dd-4dd082e7fab5', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 14, 14, 'ጌታችን ኢየሱስ በምራቁ ጭቃ አድርጎ ዐይኖቹን ያበራበት ቀኑ ሰንበት ነበርና።'),
  ('71e8c508-5b02-5005-a9bd-c99f5eb03cf8', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 15, 15, 'ፈሪሳውያንም እንዴት እንዳየ ዳግመኛ ጠየቁት፤ እርሱም፥ “በምራቁ ጭቃ አድርጎ በዐይኖች አኖረው፥ ታጥቤም አየሁ” አላቸው።'),
  ('09713eef-66d0-5e0e-a30c-76e790cca600', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 16, 16, 'ከፈሪሳውያንም አንዳንዶች፥ “ይህ ሰው ከእግዚአብሔር አይደለም፤ ሰንበትን አያከብርምና” አሉ፤ ሌሎች ግን “ኀጢኣተኛ ሰው እንዲህ ያለ ተአምራት ማድረግ እንዴት ይችላል?” አሉ፤ እርስ በርሳቸውም ተለያዩ።'),
  ('29b14076-d431-50f0-a9e7-17c425ad8b5a', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 17, 17, 'ዳግመኛም ዕዉሩን፥ “አንተ ስለ እርሱ ምን ትላለህ? ዐይኖችህን ከፍቶልሃልና” አሉት፤ እርሱም፥ “ነቢይ ነው” አላቸው።'),
  ('075aae14-3b0f-556d-a44c-0c2deee4ecdf', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 18, 18, 'አይሁድም የዚያን ያየውን ሰው ወላጆች እስኪጠሩ ድረስ ዕዉር ሆኖ እንደ ተወለደ፥ እንዳየም አላመኑም።'),
  ('fd089c00-b166-51c6-a395-1a38ce8d5cb2', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 19, 19, '“ዕዉር ሆኖ ተወለደ የምትሉት ልጃችሁ ይህ ነውን? እንግዲያ አሁን እንዴት ያያል?” ብለው ጠየቁአቸው።'),
  ('606474d7-c08b-56ee-a625-5e83e915c02b', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 20, 20, 'ወላጆቹም መልሰው እንዲህ አሉ፥ “ይህ ልጃችን እንደ ሆነ፥ ዕዉር ሆኖም እንደ ተወለደ እናውቃለን።'),
  ('5c72832e-0536-5ee2-ab57-a6ff3f17852b', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 21, 21, 'አሁን ግን እንዴት እንደሚያይ ዐይኖቹንም ማን እንደ አበራለት አናውቅም፤ እርሱን ጠይቁት፤ ዐዋቂ ነውና፤ ስለ ራሱም መናገር ይችላልና።”'),
  ('c12202f2-5d33-5a71-a8af-01da31ff8406', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 22, 22, 'ወላጆቹ አይሁድን ስለ ፈሩ ይህን አሉ፥ “እርሱ ክርስቶስ ነው ብሎ በእርሱ የሚያምን ቢኖር ከምኵራብ ይውጣ” ብለው አይሁድ ተስማምተው ነበርና።'),
  ('37920eb5-3768-5022-a6a0-fe2fecea0ecf', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 23, 23, 'ስለዚህም ወላጆቹ፥ “ዐዋቂ ነውና እርሱን ጠይቁት” አሉ።'),
  ('c24b8932-ab90-574e-af3d-b60f1eef70b2', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 24, 24, 'ዕውር የነበረውንም ሰው ዳግመኛ ጠርተው፥ “ሂድ ለእግዚአብሔር ምስጋና አቅርብ፤ ይህ ሰው ኀጢኣተኛ እንደ ሆነ እኛ እናውቃለን” አሉት።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('cebf0c68-e75f-5d41-a293-b5bee252e54d', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 25, 25, 'ያም ሰው መልሶ እንዲህ አላቸው፥ “እርሱ ኀጢኣተኛ እንደ ሆነ እኔ አላውቅም፤ እኔ ዕዉር እንደ ነበርሁ፤ አሁን ግን እንደማይ ይህን አንድ ነገር ብቻ አውቃለሁ።”'),
  ('565c9d28-2d74-5946-a29a-f278cac41fbe', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 26, 26, 'ዳግመኛም፥ “ምን አደረገልህ? ዐይኖችህንስ እንደምን አበራልህ?” አሉት።'),
  ('37b133da-c38f-5fb5-a221-dd8d34ac7776', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 27, 27, 'እርሱም መልሶ፥ “አትሰሙኝም እንጂ ነገርኋችሁ፤ እንግዲህ ደግሞ ምን ልትሰሙ ትሻላችሁ? እናንተም ደቀ መዛሙርቱ ልትሆኑ ትሻላችሁን?” አላቸው።'),
  ('dd173fbc-fb42-5d60-ac5e-00608c8929e2', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 28, 28, 'እነርሱም ሰደቡት፤ እንዲህም አሉት፥ “አንተ የእርሱ ደቀ መዝሙር ሁን፤ እኛስ የሙሴ ደቀ መዛሙርት ነን።'),
  ('8edb1551-7646-589b-aeb2-905c2e362ed7', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 29, 29, 'እግዚአብሔር ሙሴን እንደ ተነጋገረው እናውቃለን፤ ይህን ግን ከወዴት እንደ ሆነ አናውቅም።”'),
  ('3c80ac1b-9352-5901-a977-fa7c8bb32ced', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 30, 30, 'ያም ሰው መልሶ እንዲህ አላቸው፥ “ከወዴት እንደ ሆነ፥ አታውቁትምና ይህ እጅግ ድንቅ ነው፤ ነገር ግን ዐይኖችን አበራልኝ።'),
  ('621edfe6-29aa-5034-a2f3-e745cb9a8421', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 31, 31, 'እኛም እግዚአብሔርን የሚፈራውንና ፈቃዱን የሚያደርገውን እርሱን ይሰማዋል እንጂ ኃጥኣንን እንደማይሰማቸው እናውቃለን።'),
  ('d8ecc95b-c394-52cd-ac36-0edda1318a0f', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 32, 32, 'ዓለም ከተፈጠረ ጀምሮ ዕዉር ሆኖ የተወለደውን ዐይኖች ያበራ አልተሰማም።'),
  ('5e7c36e7-21c2-57e5-a93f-18f0ba7d2a17', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 33, 33, 'ይህ ሰው ከእግዚአብሔር ባይሆን ኖሮ ምንም ማድረግ ባልቻለም ነበር።”'),
  ('f660a706-ea6a-54f0-a9d8-3208fdf5411d', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 34, 34, 'እነርሱም መልሰው፥ “ራስህ በኀጢኣት የተወለድህ አንተ እኛን ታስተምረናለህን?” አሉት፤ ወደ ውጭም አወጡት።'),
  ('6891e89c-3a9e-533b-a5f6-ad297ae260c1', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 35, 35, 'ጌታችን ኢየሱስም ወደ ውጭ እንዳወጡት ሰማ፤ አገኘውምና፥ “አንተ በእግዚአብሔር ልጅ ታምናለህን?” አለው።'),
  ('9cc337ca-3131-5218-a7e1-520742a13a1e', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 36, 36, 'ያ ሰውም፥ “አቤቱ፥ አምንበት ዘንድ እርሱ ማነው?” ብሎ መለሰለት።'),
  ('4a97b75b-dd45-5eaa-ac8c-e87ac5ddf00e', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 37, 37, 'ጌታችን ኢየሱስም፥ “የምታየው፥ ከአንተ ጋርም የሚነጋገረው እርሱ ነው” አለው።'),
  ('1025ef0f-3f36-511e-a210-59ed3121a7f7', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 38, 38, 'እርሱም፥ “አቤቱ፥ አምናለሁ” ብሎ ሰገደለት።'),
  ('6fa9f9fb-f057-5269-a876-b2fdf03ff778', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 39, 39, 'ጌታችን ኢየሱስም፥ “እኔ የማያዩት እንዲያዩ፥ የሚያዩትም እንዲታወሩ ወደዚህ ዓለም ለፍርድ መጥቻለሁ” አለው።'),
  ('f1fb3848-3bd7-5ebb-a3e3-db58890f6499', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 40, 40, 'ከፈሪሳውያንም ከእርሱ ጋር የነበሩት ይህን ሲናገር ሰምተው፥ “እኛ ደግሞ ዕዉሮች ነን?” አሉት።'),
  ('bf22b575-5986-5a28-abe2-eb590be41d4e', '1d424773-c5e9-5166-abd2-32ef6d5e6f1b', 'b7ab2a07-be22-5344-af3d-b6f3533b75e7', 41, 41, 'ጌታችን ኢየሱስም፥ “ዕዉሮችስ ብትሆኑ ኀጢኣት ባልሆነባችሁም ነበር፤ አሁን ግን እናያለን ትላላችሁ፤ አታዩምም፤ ስለዚህም ኀጢኣታችሁ ጸንቶ ይኖራል” አላቸው።'),
  ('7c287d01-8435-5ed9-ace4-3bc1ecaad99c', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 1, 1, '“እውነት እውነት እላችኋለሁ፤ ወደ በጎች ስፍራ በበሩ የማይገባ፥ በሌላም በኩል የሚገባ ሌባ፥ ወንበዴም ነው።'),
  ('377e397d-d15a-5597-a962-831e6d175346', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 2, 2, 'በበሩ የሚገባ ግን የበጎች ጠባቂ ነው።'),
  ('8c3e545b-61c3-547d-a4f8-791bb2451a69', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 3, 3, 'ለእርሱ በረኛው ይከፍትለታል፤ በጎቹም ቃሉን ይሰሙታል፤ እርሱም በጎቹን በየስማቸው ይጠራቸዋል፤ አውጥቶም ያሰማራቸዋል።'),
  ('b2d0024c-cfe9-530f-aa1e-d39cb1be0cce', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 4, 4, 'ሁሉንም አውጥቶ ባሰማራቸው ጊዜ በፊት በፊታቸው ይሄዳል፤ በጎቹም ይከተሉታል፤ ቃሉን ያውቃሉና።'),
  ('e61376dd-dec9-5edd-a3ed-c69f3b1ffa8e', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 5, 5, 'ሌላውን ግን ይሸሹታል እንጂ አይከተሉትም፤ የሌላውን ቃሉን አያውቁምና።”'),
  ('5acb16e0-6e96-5896-a9e0-32d808bf83d6', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 6, 6, 'ጌታችን ኢየሱስም ይህን ምሳሌ ነገራቸው፤ እነርሱ ግን የነገራቸውን አላወቁም።'),
  ('70750e39-97da-5ed7-a491-2bb4fc15e644', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 7, 7, 'ዳግመኛም ጌታችን ኢየሱስ እንዲህ አላቸው፥ “እውነት እውነት እላችኋለሁ፤ የበጎች በር እኔ ነኝ።'),
  ('c25e5bb5-ee41-56f3-a2de-6599a1f9fae5', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 8, 8, 'ከእኔ በፊት የመጡ ሁሉ ሌቦችና ወንበዴዎች ናቸው፤ ነገር ግን፤ በጎች አልሰሙአቸውም።'),
  ('f90d8e5c-dcc1-5345-a791-52a3a677874f', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 9, 9, 'እውነተኛዉ የበጎች በር እኔ ነኝ፤ በእኔ በኩልም የሚገባ ይድናል፤ ይገባልም ይወጣልም፤ መሰማርያም ያገኛል።'),
  ('a9568edf-45ac-5f68-a245-f816f71a4f3d', '08eeb031-69cf-5c95-a027-51e4f56a379c', '691af4ae-c4ca-55fe-ac25-0562fd0b72a8', 10, 10, 'ሌባ ግን ሊሰርቅና ሊያርድ፥ ሊያጠፋም ካልሆነ በቀር አይመጣም፤ እኔ ግን የዘለዓለም ሕይወትን እንዲያገኙ፥ እጅግም እንዲበዛላቸው መጣሁ።'),
  ('2938eb15-db60-5295-a9d3-b585f96e29a3', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 1, 11, '“ቸር ጠባቂ እኔ ነኝ፤ ቸር ጠባቂ ስለ በጎቹ ነፍሱን ይሰጣል።'),
  ('57f7618c-1d73-58a8-a6ff-cefcf0e06234', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 2, 12, 'ጠባቂ ያይደለ፥ በጎቹም ገንዘቡ ያይደሉ ምንደኛ ግን፥ ተኵላ ሲመጣ ባየ ጊዜ በጎቹን ትቶ ይሸሻል፤ ተኵላም መጥቶ በጎችን ይነጥቃቸዋል፥ ይበትናቸዋልም።'),
  ('4a24027f-8a2e-5920-a87f-48c5baa93369', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 3, 13, 'ምንደኛስ ይሸሻል፤ ስለ በጎችም አያዝንም፤ ምንደኛ ነውና።'),
  ('0f8a7869-07bf-5ada-aed1-0af533068cb4', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 4, 14, 'ቸር ጠባቂ እኔ ነኝ፤ የእኔ የሆኑትን መንጋዎችን አውቃለሁ፤ የእኔ የሆኑትም ያውቁኛል።'),
  ('b9afbe22-bcf0-5dc9-aa5c-6d95866a69f6', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 5, 15, 'አብ እኔን እንደሚያውቀኝ እኔም አብን አውቀዋለሁ፤ ለበጎችም ቤዛ አድርጌ ሰውነቴን አሳልፌ እሰጣለሁ።'),
  ('f7bcf5e4-61ae-5b4e-a136-0e60db140d44', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 6, 16, 'ከዚህ ቦታ ያይደሉ ሌሎች በጎችም አሉኝ፤ እነርሱንም ወደዚህ አመጣቸው ዘንድ ይገባኛል፤ ቃሌንም ይሰሙኛል፤ ለአንድ እረኛም አንድ መንጋ ይሆናሉ።'),
  ('ec04f50b-a6bd-5ab8-aa3e-5f9206479753', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 7, 17, 'ስለዚህም፤ አብ ይወድደኛል፥ እንደ ገና አስነሣት ዘንድ እኔ ነፍሴን እሰጣለሁና።'),
  ('42a1e585-4377-538f-a881-aa65d929c66f', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'cd0d4cf1-9735-581c-a0fa-80ce64079fb1', 8, 18, 'ከእኔ ማንም አይወስዳትም፤ ነገር ግን እኔ በፈቃዴ እሰጣታለሁ፤ እኔ ላኖራት ሥልጣን አለኝ፤ መልሼ እወስዳት ዘንድ ሥልጣን አለኝና፤ ይህንም ትእዛዝ ከአባቴ ተቀበልሁ።”'),
  ('5f31d148-a572-53ad-a181-575544001669', '08eeb031-69cf-5c95-a027-51e4f56a379c', '03d933e7-e7ac-50b9-ab8f-a50c2c63cd9b', 1, 19, 'ስለዚህም ነገር አይሁድ እንደገና እርስ በርሳቸው ተለያዩ።'),
  ('e12c8d7d-8162-5ca7-a9f7-a13861b52a89', '08eeb031-69cf-5c95-a027-51e4f56a379c', '03d933e7-e7ac-50b9-ab8f-a50c2c63cd9b', 2, 20, 'ከእነርሱም ብዙዎች፥ “ጋኔን ይዞት ያብዳል፤ ለምንስ ታዳምጡታላችሁ?” አሉ።'),
  ('ae8767e3-581a-5d55-a76f-55ad04e4f8fc', '08eeb031-69cf-5c95-a027-51e4f56a379c', '03d933e7-e7ac-50b9-ab8f-a50c2c63cd9b', 3, 21, 'ሌሎችም ይህ ነገር ጋኔን ከያዘው ሰው የሚገኝ አይደለም፤ ጋኔን የዕዉሮችን ዐይን ማብራት ይችላልን?” አሉ።'),
  ('69f46580-2c69-53b7-a9a7-914c335041fa', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 1, 22, 'በዚያም ወራት በኢየሩሳሌም የመቅደስ መታደስ በዓል ሆነ፤ ክረምትም ነበር።'),
  ('65d0cba7-992e-5bca-ade9-e0cc1940aa31', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 2, 23, 'ጌታችን ኢየሱስም በቤተ መቅደስ በሰሎሞን ደጅ መመላለሻ ይመላለስ ነበር።'),
  ('7290c205-78bd-5bc9-add6-4e8156382971', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 3, 24, 'አይሁድም እርሱን ከብበው፥ “እስከ መቼ ድረስ ሰውነታችንን ታስጨንቀናለህ? አንተ ክርስቶስ እንደ ሆንህ ገልጠህ ንገረን” አሉት።'),
  ('cbdae079-ef7f-5595-a884-d2da9447aa24', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 4, 25, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “አታምኑኝም እንጂ ነገርኋችሁ፤ እኔ በአባቴ ስም የምሠራው ሥራ እርሱ ምስክሬ ነው።'),
  ('1e27c112-46a5-5d4e-a7aa-2eb2df2d7ec1', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 5, 26, 'እናንተ ግን አታምኑኝም፤ እንደ ነገርኋችሁ ከበጎች ውስጥ አይደላችሁምና።'),
  ('c26ff8a8-6c9f-5867-ac68-41f0a6ad736d', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 6, 27, 'የእኔ የሆኑ በጎች ግን ቃሌን ይሰሙኛል፤ እኔም አውቃቸዋለሁ፤ እነርሱም ይከተሉኛል።'),
  ('16897f59-caeb-512c-a0e6-6b76a09ecdc5', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 7, 28, 'እኔም የዘለዓለም ሕይወትን እሰጣቸዋለሁ፤ ለዘለዓለሙም አይጠፉም፤ ከእጄም የሚነጥቃቸው የለም።'),
  ('447c7556-4980-5f40-a538-b69d6999f627', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 8, 29, 'እነርሱን የሰጠኝ አባቴ እርሱ ከሁሉ ይበልጣልና፤ ከአባቴም እጅ መንጠቅ የሚችል የለም።'),
  ('55eee25a-8fdf-5c13-ad53-03196fd27447', '08eeb031-69cf-5c95-a027-51e4f56a379c', '6fc3bde2-c32a-5051-ab1f-2d245e81006d', 9, 30, 'እኔና አብ አንድ ነን።”'),
  ('e6e86909-53c2-5278-a0c5-ec0359d6fc5e', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 1, 31, 'ዳግመኛም አይሁድ ሊወግሩት ድንጋይ አነሡ።'),
  ('bae8a76b-6f2f-5b1e-a937-9146f83f2d7a', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 2, 32, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “ከአባቴ ብዙ መልካም ሥራ አሳየኋችሁ፤ ከእነርሱ በየትኛው ሥራ ምክንያት ትወግሩኛላችሁ?”'),
  ('a3040561-27cc-5e5d-ad62-beb52168ab63', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 3, 33, 'አይሁድም፥ “አንተ፥ ሰው ስትሆን ራስህን እግዚአብሔርን ታደርጋለህና፤ ስለ መሳደብህ ነው እንጂ ስለ መልካም ሥራህስ አንወግርህም” አሉት።'),
  ('e136c3d4-91d6-50f6-affa-b98b0ece4824', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 4, 34, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “እኔ አማልክት ናችሁ አልሁ ተብሎ በኦሪታችሁ ተጽፎ የለምን?'),
  ('409c73fa-c4bc-51fb-ad3f-e392a689f243', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 5, 35, 'የእግዚአብሔር ቃል የመጣላቸውን እነዚያን አማልክት ካላቸው፥ የመጽሐፉ ቃል ይታበል ዘንድ አይቻልም።'),
  ('653bb8df-5f22-5d2b-a73a-3fd05cf3ab29', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 6, 36, 'እኔ የእግዚአብሔር ልጅ ነኝ ብላችሁ፥ አብ የቀደሰውንና ወደ ዓለምም የላከውን እንዴት ትሳደባለህ? ትሉኛላችሁ።'),
  ('fca11d5b-0b74-5c78-a310-dbb9133675ee', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 7, 37, 'የአባቴን ሥራ ባልሠራ በእኔ አትመኑ።'),
  ('80db024f-70ba-516a-a90f-6dd88f1e262c', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 8, 38, 'ከሠራሁ ግን፥ እኔን እንኳን ባታምኑ እኔ በአብ እንዳለሁ አብም በእኔ እንዳለ ታውቁና ትረዱ ዘንድ ሥራዬን እመኑ።”'),
  ('7e13a450-ddb7-5d9b-a212-972f496f9d5d', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'b1e62d52-9b5f-50f9-a02e-274b293acc8d', 9, 39, 'ዳግመኛም ሊይዙት ፈለጉ፤ ከእጃቸውም አመለጠ።'),
  ('9a54df4d-a5f6-5c23-a9d2-c0ab28e4f947', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'fa6f50d0-3e54-5475-a4b2-7ec8e57c63c6', 1, 40, 'ዳግመኛም ቀድሞ ዮሐንስ ያጠምቅበት ወደ ነበረው ስፍራ ወደ ዮርዳኖስ ማዶ ሄደ፤ በዚያም ተቀመጠ።'),
  ('39b9a058-2e86-5680-afcb-338fb51ae0b1', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'fa6f50d0-3e54-5475-a4b2-7ec8e57c63c6', 2, 41, 'ብዙዎችም ወደ እርሱ ሄደው፥ “ዮሐንስ ምንም ያደረገው ተአምራት የለም፤ ነገር ግን ዮሐንስ ስለዚህ ሰው የተናገረው ሁሉ እውነት ሆነ” አሉ።'),
  ('83f0c214-409a-50b7-a3c4-e1566278662b', '08eeb031-69cf-5c95-a027-51e4f56a379c', 'fa6f50d0-3e54-5475-a4b2-7ec8e57c63c6', 3, 42, 'በዚያም ብዙ ሰዎች አመኑበት።'),
  ('fb2bbcd6-bba2-5944-a230-b5989f00ea09', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 1, 1, 'የማርያምና የእኅቷ የማርታ መንደር በሚሆን በቢታንያ ስሙ አልዓዛር የሚባል የታመመ አንድ ሰው ነበር።'),
  ('2ac735a3-5318-5e5d-a27c-d12110197a24', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 2, 2, 'ማርያም ግን ጌታችንን ሽቱ የቀባችው፥ እግሩንም በጠጕርዋ ያሸችው ናት፤ ወንድምዋ አልዓዛርም ታሞ ነበር።'),
  ('6bbdd13e-1031-5b4a-ab07-3e8a09556887', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 3, 3, 'እኅቶቹም፥ “ጌታችን ሆይ፥ እነሆ፥ የምትወደው ታሞአል” ብለው ወደ ጌታችን ኢየሱስ ላኩ።'),
  ('7c186ca0-f6ce-51a4-ae82-735c20063dde', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 4, 4, 'ጌታችን ኢየሱስም ሰምቶ እንዲህ አለ፥ “ይህ ደዌ በእርሱ የእግዚአብሔር ልጅ ይከብር ዘንድ ስለ እግዚአብሔር ክብር ነው እንጂ ለሞት አይደለም።”'),
  ('1b8e5d4a-153b-5e98-ad41-0dfa379b79c8', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 5, 5, 'ጌታችን ኢየሱስም ማርታንና እኅቷን ማርያምን፥ አልዓዛርንም ይወዳቸው ነበር።'),
  ('23f21249-132e-5316-a64e-63cb31444b9d', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 6, 6, 'እንደ ታመመ በሰማ ጊዜM በነበረበት ቦታ ሁለት ቀን ቈየ።'),
  ('f25df347-a84f-56cd-a1cc-b5a6c952d41b', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 7, 7, 'ከዚህም በኋላ፥ ደቀ መዛሙርቱን፥ “ኑ፥ ወደ ይሁዳ ሀገር ደግሞ እንሂድ” አላቸው።'),
  ('497dce10-6b5d-5d04-ab19-c9cfb3717adb', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 8, 8, 'ደቀ መዛሙርቱም፥ “መምህር ሆይ፥ አይሁድ ሊወግሩህ ይሹ አልነበረምን? ዛሬ ደግሞ አንተ ወደዚያ ልትሄድ ትሻለህን?” አሉት።'),
  ('4c3a3cad-94bc-5add-a3d8-181d3de4067a', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 9, 9, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “ቀኑ ዐሥራ ሁለት ሰዓት አይደለምን? በቀን የሚሄድ አይሰናከልም፤ የዚህን ዓለም ብርሃን ያያልና።'),
  ('8b7a3c86-9343-5d16-a68b-8bd6992825b9', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 10, 10, 'በሌሊት የሚሄድ ግን ይሰነካከላል፤ በውስጡ የሚያየው ብርሃን የለምና።”'),
  ('0817dd05-f184-5884-ac97-9df7c10e43ff', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 11, 11, 'ይህንም ለደቀ መዛሙርቱ ነገራቸው፤ ከዚህም በኋላ፥ “ወዳጃችን አልዓዛር ተኝቶአል፤ ነገር ግን ላነቃው እሄዳለሁ” አላቸው።'),
  ('947146aa-8874-5abe-abea-4e3570b42ad6', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 12, 12, 'ደቀ መዛሙርቱም፥ “አቤቱ፥ ከተኛስ ይነቃል፤ ይድናልም” አሉት።'),
  ('b9ff3804-4c32-56c8-a2ac-515c137fa7b9', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 13, 13, 'ጌታችን ኢየሱስም ስለ ሞቱ ተናገረ፤ እነርሱ ግን ስለ እንቅልፍ መተኛት መስሎአቸው ነበር።'),
  ('fc4ba71a-4330-5440-a17d-3caacb423097', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 14, 14, 'ከዚህ በኋላም ጌታችን ኢየሱስ ገልጦ እንዲህ አላቸው፥ “አልዓዛር ሞተ።'),
  ('3b37171b-fa16-5b2c-acc3-f8430dd7aa06', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 15, 15, 'ታምኑም ዘንድ እኔ በዚያ ባለመኖሬ ስለ እናንተ ደስ ይለኛል፤ ነገር ግን ኑ፥ ወደ እርሱ እንሂድ።”'),
  ('eecefc2f-7275-5782-a719-a050653b468c', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '05b49bb3-c439-511d-aa6e-3850234f5cd6', 16, 16, 'ዲዲሞስ የሚሉት ቶማስም፥ ባልንጀሮቹን ደቀ መዛሙርት፥ “እኛም ከእርሱ ጋር እንሞት ዘንድ እንሂድ” አላቸው።'),
  ('05a87335-256a-5dac-afad-fbbece1b52bf', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 1, 17, 'ጌታችን ኢየሱስም ወደ ቢታንያ ሄደ፤ ከዚያም በደረሰ ጊዜ ከተቀበረ አራት ቀን ሆኖት አገኘው።'),
  ('b702210c-37ba-5b6d-a98c-9760a694e931', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 2, 18, 'ቢታንያም ለኢየሩሳሌም ዐሥራ አምስት ምዕራፍ ያህል ቅርብ ነበረች።'),
  ('e78cb142-d569-583f-a373-69388cfee7c7', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 3, 19, 'ከአይሁድም ስለ ወንድማቸው ሊያጽናኑአቸው ወደ ማርያምና ወደ ማርታ የሄዱ ብዙዎች ነበሩ።'),
  ('11b8950c-ac24-58d1-ad1e-0811261283ed', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 4, 20, 'ማርታም ጌታችን ኢየሱስ እንደ መጣ በሰማች ጊዜ ወጥታ ተቀበለችው፤ ማርያም ግን በቤት ተቀምጣ ነበር።'),
  ('7c6ffb36-9611-5ebb-a526-d93d75b53487', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 5, 21, 'ማርታም ጌታችን ኢየሱስን እንዲህ አለችው፥ “ጌታዬ ሆይ፥ በዚህ ኖረህ ቢሆን ወንድሜ ባልሞተም ነበር።'),
  ('d7231fea-5c34-5875-add1-220c018e78cc', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 6, 22, 'አሁንም ከእግዚአብሔር የምትለምነውን እግዚአብሔር እንዲሰጥህ አውቃለሁ።”'),
  ('3d76bab7-f4bd-5ea6-ae6e-e6e66a4d5d7a', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 7, 23, 'ጌታችን ኢየሱስም፥ “ወንድምሽስ ይነሣል” አላት።'),
  ('0f2a3850-43cb-516b-aff7-59df2e503f19', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '53cb7797-d2b5-5512-a498-344639f5b8a1', 8, 24, 'ማርታም፥ “ሙታን በሚነሡባት በኋለኛዪቱ ቀን እንደሚነሣ አውቃለሁ” አለችው።'),
  ('ce290288-c6fb-57e1-aa69-a52bf384db3b', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '02704503-38dc-5027-a2fb-d19afe6fb56d', 1, 25, 'ጌታችን ኢየሱስም አላት፥ “ትንሣኤና ሕይወት እኔ ነኝ፤ የሚያምንብኝ ቢሞትም ይነሣል።'),
  ('1a2144cb-0a53-5b06-a5f7-cdc49451cb08', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '02704503-38dc-5027-a2fb-d19afe6fb56d', 2, 26, 'ሕያው የሆነ የሚያምንብኝም ሁሉ ለዘለዓለም አይሞትም፤ ይህንስ ታምኛለሽን?”'),
  ('41a81c1f-964a-581b-a15d-eef77f0b7cab', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '02704503-38dc-5027-a2fb-d19afe6fb56d', 3, 27, 'እርስዋም፥ “አዎን፥ ጌታዬ ሆይ፥ አንተ ወደ ዓለም የሚመጣው የእግዚአብሔር ልጅ ክርስቶስ እንደ ሆንህ እኔ አምናለሁ” አለችው።'),
  ('d2e804ea-e181-5ec8-afd1-8f226416d885', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 1, 28, 'ይህንም ብላ ሄደች፤ እኅቷን ማርያምንም ቀስ ብላ ጠራችና፥ “እነሆ፥ መምህራችን መጥቶ ይጠራሻል” አለቻት።'),
  ('c4c97617-3456-553b-acab-3886b6f244f1', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 2, 29, 'እርስዋም ይህን በሰማች ጊዜ ፈጥና ተነሣች፤ ወደ እርሱም ሄደች።'),
  ('05383e57-3701-5e2e-a092-1ab05e469f10', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 3, 30, 'ጌታችን ኢየሱስም ማርታ በተቀበለችበት ስፍራ ነበረ እንጂ ገና ወደ መንደር አልገባም ነበር።'),
  ('49a1d85f-47b3-5505-a34a-00d60da55d74', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 4, 31, 'ሊያጽናኑአት መጥተው በቤት ከእርስዋ ጋር የነበሩ አይሁድም ፈጥና ተነሥታ እንደ ወጣች ባዩ ጊዜ በዚያ ለወንድምዋ ልታለቅስ ወደ መቃብሩ የምትሄድ መስሎአቸው ተከተሉአት።'),
  ('27cef471-b3cc-5d6b-ab46-8d94c922d24b', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 5, 32, 'ማርያምም ጌታችን ኢየሱስ ወደ አለበት ስፍራ ደረሰችና በአየችው ጊዜ ከእግሩ በታች ሰግዳ፥ “ጌታዬ ሆይ፥ በዚህ ኑረህ ቢሆን ወንድሜ ባልሞተም ነበር” አለችው።'),
  ('a27ce6f4-e989-5ac1-a69c-3f39f015ebf0', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 6, 33, 'ጌታችን ኢየሱስም እርስዋ ስታለቅስ፥ ከእርስዋ ጋር የመጡ አይሁድም ሲያለቅሱ ባየ ጊዜ በልቡ አዘነ፤ በራሱም ታወከ።'),
  ('260eba16-c936-58ae-abd7-06c59138c835', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 7, 34, 'እርሱም፥ “የት ቀበራችሁት?” አለ፤ እነርሱም፥ “አቤቱ፥ መጥተህ እይ” አሉት።'),
  ('b3ea5c86-f0ff-5ea3-a54f-2b48f67febcc', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 8, 35, 'ጌታችን ኢየሱስም እንባውን አፈሰሰ።'),
  ('547b5dc7-1163-5d72-a998-01bcb9ced613', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 9, 36, 'አይሁድም፥ “ምን ያህል ይወደው እንደ ነበር እዩ” አሉ።'),
  ('43e61872-d68f-5ce6-ae3a-787cb7926b6a', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 10, 37, 'ከእነርሱም መካከል፥ “ዕዉር ሆኖ የተወለደውን ዐይን ያበራው ይህ ሰው ይህስ እንዳይሞት ሊያደርግ ባልቻለም ነበርን?” ያሉ ነበሩ።'),
  ('b27a0cf8-e9a7-512c-a7b4-ac70c75a595c', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 11, 38, 'ዳግመኛም ጌታችን ኢየሱስ በልቡ አዘነ፤ ወደ መቃብሩም ሄደ፤ መቃብሩም ዋሻ ነበር፤ በላዩም ታላቅ ድንጋይ ተገጥሞበት ነበር።'),
  ('acfa4e7b-c054-5b4a-a5dd-0f8564eb2aea', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 12, 39, 'ጌታችን ኢየሱስም፥ “ድንጋዩን አንሡ” አላቸው፤ የሟቹ እኅት ማርታም፥ “ጌታዬ ሆይ፥ አራት ቀን ሆኖታልና ፈጽሞ ሸትቶ ይሆናል” አለችው።'),
  ('dd311d95-ecf7-5bfe-a9c8-1339ca078d01', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 13, 40, 'ጌታችን ኢየሱስም፥ “ብታምናስ የእግዚአብሔርን ክብር ታያለሽ አላልሁሽም ነበርን?” አላት።'),
  ('8514368e-8382-5038-ace3-f1615a61fc45', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 14, 41, 'ድንጋዩንም አነሡ፤ ጌታችን ኢየሱስም ዐይኖቹን አቅንቶ እንዲህ አለ፥ “አባት ሆይ፥ ሰምተኸኛልና አመሰግንሃለሁ።'),
  ('de3f2abd-24fb-5101-a686-a7f6e1edcc5e', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 15, 42, 'እኔም ዘወትር እንደምትሰማኝ አውቃለሁ፤ ነገር ግን አንተ እንደ ላክኸኝ ያምኑ ዘንድ በዚህ ቆመው ስላሉት ሰዎች ይህን እናገራለሁ።”'),
  ('37975121-420b-50bd-ab90-e184ed99a128', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 16, 43, 'ይህንም ብሎ በታላቅ ቃል ጮኸና፥ “አልዓዛር፥ ና፤ ወደ ውጭ ውጣ” አለ።'),
  ('971c6a88-fc16-5926-ac02-e81132335c1f', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 17, 44, 'ሞቶ የነበረውም እንደ ተገነዘ፥ እጁንና እግሩንም እንደ ታሰረ፥ ፊቱም በሰበን እንደ ተጠቀለለ ወጣ፤ ጌታችን ኢየሱስም፥ “እንግዲህስ ፍቱትና ተዉት ይሂድ” አላቸው።'),
  ('8726a472-97df-5d25-a655-55c768939370', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 18, 45, 'ስለዚህ ከአይሁድም ወደ ማርታና ወደ ማርያም መጥተው የነበሩ ብዙ ሰዎች ጌታችን ኢየሱስ ያደረገውን አይተው በእርሱ አመኑ።'),
  ('738f0c74-3a30-577b-a4b1-f834ebc91650', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '9eb9fe53-c74f-5887-abb9-268146b58676', 19, 46, 'ከእነርሱም መካከል ወደ ፈሪሳውያን ሄደው የከሰሱት ነበሩ፤ ጌታችን ኢየሱስ ያደረገውንም ሁሉ ነገሩአቸው።'),
  ('e32af331-dad2-553d-a637-d5560f26a106', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 1, 47, 'የካህናት አለቆችና ፈሪሳውያንም ጉባኤውን ሰብስበው እንዲህ አሉአቸው፥ “እነሆ፥ ይህ ሰው ብዙ ተአምራት ያደርጋል፤ ምን እናድርግ?'),
  ('c7082d03-fbd8-51f0-a277-69c493271e15', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 2, 48, 'እንዲሁ ብንተወውም ሁሉ ያምኑበታል፤ የሮም ሰዎችም መጥተው ሀገራችንንና ወገናችንን ይወስዱብናል።”'),
  ('583dedcb-d984-5ef2-a5de-e1c45973e6ce', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 3, 49, 'በዚያችም ዓመት የካህናት አለቃ የነበረው ስሙ ቀያፋ የተባለው ከእነርሱ አንዱ እንዲህ አላቸው፥ “እናንተስ ምንም አታውቁም።'),
  ('86abb907-87c3-5bce-a318-2ec6186b620a', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 4, 50, 'ምንም አትመክሩም፤ ሕዝቡ ሁሉ ከሚጠፋ ስለ ሕዝቡ አንድ ሰው ቢሞት ይሻለናል።”'),
  ('c08c4a5b-b0c4-5b7e-a9e2-f68486240da4', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 5, 51, 'ይህንም ከልቡ የተናገረው አይደለም፤ ነገር ግን በዚያች ዓመት የካህናት አለቃ ነበርና ጌታችን ኢየሱስ ስለ ሕዝብ ሁሉ ቤዛ ሆኖ ይሞት ዘንድ ስላለው ይህን ትንቢት ተናገረ።'),
  ('94cbd58c-c3a2-57f1-a4a3-1986d569131f', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 6, 52, 'ስለ ሕዝብ ብቻ አልነበረም፤ የተበተኑትን የእግዚአብሔርንም ልጆች በአንድነት ይሰበስባቸው ዘንድ ነው እንጂ።'),
  ('14c0b694-b0d0-50af-aa8e-ea7aa3c333c4', '141b9e9a-07b0-5007-a322-3a4bc7830d17', '1698f238-cad4-5d3d-a179-b19a2a8a5714', 7, 53, 'ከዚያችም ቀን ጀምሮ የካህናት አለቆች ሊገድሉት ተማከሩ።'),
  ('7988f291-03b7-570d-ad36-0f39aa6ee5ad', '141b9e9a-07b0-5007-a322-3a4bc7830d17', 'ccaade75-b7a3-58cd-a6ba-a95e2c16e25a', 1, 54, 'ከዚያም ወዲያ ጌታችን ኢየሱስ በአይሁድ መካከል በግልጥ አልተመላለሰም፤ ነገር ግን ለምድረ በዳ አቅራቢያ ወደ ሆነች ምድር፥ ኤፍሬም ወደምትባል ከተማ ሄደ፤ በዚያም ከደቀ መዛሙርቱ ጋር ተቀመጠ።'),
  ('0f6d57ba-2c9f-5c28-a113-19bac48cae4a', '141b9e9a-07b0-5007-a322-3a4bc7830d17', 'ccaade75-b7a3-58cd-a6ba-a95e2c16e25a', 2, 55, 'የአይሁድም የፋሲካ በዓል ቀርቦ ነበር፤ ብዙ ሰዎችም ከበዓሉ አስቀድሞ ራሳቸውን ያነጹ ዘንድ ከየሀገሩ ወደ ኢየሩሳሌም ወጥተው ነበር።'),
  ('7d0a9826-c491-5758-a010-f11433213b84', '141b9e9a-07b0-5007-a322-3a4bc7830d17', 'ccaade75-b7a3-58cd-a6ba-a95e2c16e25a', 3, 56, 'አይሁድም ጌታችን ኢየሱስን ይፈልጉት ጀመር፤ በቤተ መቅደስም ቆመው እርስ በርሳቸው፥ “ምን ይመስላችኋል? ለበዓል አይመጣ ይሆን?” ተባባሉ።'),
  ('cb7e3b11-df0d-5508-a733-17495c9d27a4', '141b9e9a-07b0-5007-a322-3a4bc7830d17', 'ccaade75-b7a3-58cd-a6ba-a95e2c16e25a', 4, 57, 'የካህናት አለቆችና ፈሪሳውያንም ያለበትን የሚያውቅ ቢኖር ይይዙት ዘንድ እንዲያመለክታቸው አዘዙ።'),
  ('9cf26b17-e67c-563f-aab2-45103c0b7ee0', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 1, 1, 'ፋሲካ ከሚውልበት ከስድስተኛው ቀን አስቀድሞ ጌታችን ኢየሱስ ከሙታን ያስነሣው አልዓዛር ወደ ነበረበት ወደ ቢታንያ መጣ።'),
  ('97239727-567b-5fb5-a68d-82633817558f', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 2, 2, 'በዚያም ምሳ አደረጉለት፤ ማርታም ታሳልፍላቸው ነበር፤ አብረውት ምሳ ከበሉትም አንዱ አልዓዛር ነበር።'),
  ('558a79a1-2c74-58ba-a98c-61d02fde817b', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 3, 3, 'ማርያም ግን ዋጋዉ የከበረና የበዛ አንድ ነጥር የጥሩ ናርዶስ ሽቱ ወሰደችና የጌታችን ኢየሱስን እግር ቀባችው፤ በፀጕሯም አሸችው፤ የዚያ ሽቱ መዓዛም ቤቱን መላው።'),
  ('421e1b67-7021-5b09-a458-239403c7e6b5', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 4, 4, 'ከደቀ መዛሙርቱ አንዱ የነበረ ያሲዘው ዘንድ ያለው የስምዖን ልጅ አስቆሮታዊው ይሁዳ ግን እንዲህ አለ።'),
  ('49335442-f87d-5f78-a8df-b7aa91769293', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 5, 5, '“ለነዳያን ይሰጥ ዘንድ ይህን ሽቱ ለሦስት መቶ ዲናር ለምን አልሸጡትም?”'),
  ('a0ab8f4c-a2d9-57ab-acd7-b263c8f6905b', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 6, 6, 'ይህንም ያለ፥ ድሆች አሳዝነውት አይደለም፤ ሌባ ነበርና፥ ሙዳየ ምጽዋቱንም ሲጠብቅ በውስጡ ከሚገባው ይወስድ ነበርና ስለዚህ ነው እንጂ።'),
  ('c57fa77f-536d-526d-aaae-e2830684324d', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 7, 7, 'ጌታችን ኢየሱስም እንዲህ አለ፥ “ለምቀበርበት ቀን ትጠብቀው ዘንድ ተዉአት።'),
  ('eeec95fa-de5d-5beb-a96a-95337ad5d4ef', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 8, 8, 'ድሆች ግን ዘወትር አብረዋችሁ አሉ፤ ዘወትርም ታገኙአቸዋላችሁ፤ በወደዳችሁም ጊዜ መልካም ታደርጉላቸዋላችሁ፤ እኔን ግን ዘወትር የምታገኙኝ አይደለም።”'),
  ('165f096a-eaa5-597b-aa47-c2cc657ceb9c', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 9, 9, 'ከአይሁድም ብዙ ሰዎች ጌታችን ኢየሱስ በዚያ እንዳለ በዐወቁ ጊዜ ወደ እርሱ መጡ፤ የመጡትም ጌታችን ኢየሱስን ለማየት ብቻ አልነበረም፤ ጌታችን ኢየሱስ ከሙታን ለይቶ ያስነሣዉን አልዓዛርንም ያዩ ዘንድ ነበር እንጂ።'),
  ('bf230103-ed30-5a6d-a9f0-f617f466f5d0', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 10, 10, 'የካህናት አለቆችም አልዓዛርን ሊገድሉት ተማከሩ።'),
  ('27e9834d-d229-53e9-a37f-388d8246da2a', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'bce98eca-aa2a-5347-ac45-97dbbdcae4b9', 11, 11, 'ከአይሁድ ብዙዎች ስለ እርሱ እየሄዱ በጌታችን በኢየሱስ ያምኑ ነበርና።'),
  ('4410745d-64ee-56c4-a847-762b4afb0d87', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 1, 12, 'በማግሥቱም ለበዓል መጥተው የነበሩ ብዙ ሰዎች ጌታችን ኢየሱስ ወደ ኢየሩሳሌም እንደሚመጣ በሰሙ ጊዜ፥'),
  ('c0e862c0-abac-52f9-adb0-4f27171abfd8', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 2, 13, 'የዘንባባ ዛፍ ዝንጣፊ ይዘው “ሆሣዕና በእግዚአብሔር ስም የሚመጣ፥ የእስራኤልም ንጉሥ ቡሩክ ነው” እያሉ ወጥተው ተቀበሉት።'),
  ('e6247b11-5472-50b7-a519-0ea2703e6498', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 3, 14, 'ጌታችን ኢየሱስም የአህያ ውርንጫ አግኝቶ በእርስዋ ላይ ተቀመጠ።'),
  ('6fdbb6a4-f462-5c41-ac08-1d97cff5175a', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 4, 15, '“የጽዮን ልጅ ሆይ፥ አትፍሪ፤ እነሆ፥ ንጉሥሽ በአህያ ውርንጫ ተቀምጦ ይመጣል” ተብሎ እንደ ተጻፈ፤'),
  ('7ff904de-6707-592a-ac6e-2fa436bbd70b', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 5, 16, 'ደቀ መዛሙርቱም አስቀድመው ይህን ነገር አላወቁም፤ ነገር ግን ጌታችን ኢየሱስ ከከበረ በኋላ በዚያ ጊዜ ይህ ነገር ስለ እርሱ እንደ ተጻፈ፥ ይህንም እንደ አደረጉለት ትዝ አላቸው።'),
  ('dfa8619b-7db8-59a0-afc3-2144769459ca', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 6, 17, 'ከዚያም አብረውት የነበሩት ሕዝብ አልዓዛርን ከመቃብር እንደ ጠራው፥ ከሙታንም እንደ አስነሣው መሰከሩለት።'),
  ('580c3dca-7a6d-57bd-a732-e394b7fea835', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 7, 18, 'ስለዚህም ነገር ሕዝቡ ሁሉ ሊቀበሉት ወጡ፤ ይህን ተአምራት እንደ አደረገ ሰምተዋልና።'),
  ('07de4ded-5627-5e48-a288-0757ed5dde0d', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', '3578f7c6-8cfd-5f9f-ae44-f0edaefd6c6b', 8, 19, 'ፈሪሳውያንም እርስ በርሳቸው፥ “የምታገኙት ምንም ጥቅም እንደሌለ ታያላችሁን? እነሆ፥ ዓለም ሁሉ ተከትሎታል” ተባባሉ።'),
  ('d64db0ed-656a-5426-a95d-cc7114c65d69', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 1, 20, 'ከጽርዕ ሰዎችም ይሰግዱ ዘንድ ለበዓል የወጡ ነበሩ።'),
  ('281e3c43-009e-5692-a67d-e5f01e72b4de', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 2, 21, 'እነርሱም ከገሊላ፥ የቤተ ሳይዳ ሰው ወደ ሆነው ወደ ፊልጶስ ሄደው፥ “አቤቱ፥ ጌታ ኢየሱስን ልናየው እንወድዳለን” ብለው ለመኑት።'),
  ('2d1f9965-143c-5054-ad75-d5fc3b478e2f', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 3, 22, 'ፊልጶስም ሄዶ ለእንድርያስ ነገረው፤ እንድርያስና ፊልጶስም ሄደው ለጌታችን ለኢየሱስ ነገሩት።'),
  ('a8d733bf-f8b5-527c-ab4c-6a290b18b184', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 4, 23, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፤ “አሁን የሰው ልጅ ይከብር ዘንድ ጊዜው ደረሰ።'),
  ('d5cc8e94-c646-51ff-a1bf-d85aca1aa622', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 5, 24, 'እውነት እውነት እላችኋለሁ፤ የስንዴ ቅንጣት በምድር ላይ ካልወደቀችና ካልሞተች ብቻዋን ትኖራለች፤ ከሞተች ግን ብዙ ፍሬን ታፈራለች።'),
  ('706abf5f-7f41-5dd1-a025-f6e62313d368', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 6, 25, 'ነፍሱን የሚወዳት ይጥላታል፤ በዚህ ዓለም ነፍሱን የሚጥላትም ለዘለዓለም ሕይወት ይጠብቃታል።'),
  ('ba1e3bd2-99ee-5f24-afb6-2b9faa6e7f09', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 7, 26, 'እኔን የሚያገለግለኝ ካለ ይከተለኝ፤ የሚያገለግለኝ እኔ ባለሁበት በዚያ ይኖራልና፤ እኔን የሚያገለግለኝንም አብ ያከብረዋል።'),
  ('db9b6dc7-0d3d-57d4-a512-3d3edb120a99', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 8, 27, '“አሁንስ ነፍሴ ታወከች፤ ግን ምን እላለሁ? አባት ሆይ፥ ከዚች ሰዓት ነፍሴን አድናት፤ ነገር ግን ስለዚህ ነገር ለዚች ሰዓት ደርሻለሁ።'),
  ('6ee559f5-7f7f-54d9-a56b-746553817507', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 9, 28, 'አባት ሆይ፥ ልጅህን አክብረው።” ከሰማይም፥ “አከበርሁህ፤ ደግሞም እንደገና አከብርሃለሁ፤” የሚል ቃል መጣ።'),
  ('5f8175e8-5d32-53ca-a34c-c8f3709583cd', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 10, 29, 'በዚያ ቆመው ይሰሙ የነበሩ ሕዝብ ግን “ነጐድጓድ ነው” አሉ፤ “መልአክ ተናገረው” ያሉም አሉ።'),
  ('92723511-c884-54a0-ac42-5298b8568093', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 11, 30, 'ጌታችን ኢየሱስም መልሶ እንዲህ አላቸው፥ “ይህ ቃል የመጣ ስለ እናንተ ነው እንጂ ስለ እኔ አይደለም።'),
  ('1dba6499-a932-5c07-a2fa-aafd2b2ae43b', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 12, 31, 'አሁን የዚህ ዓለም ፍርድ ደረሰ፤ ከእንግዲህስ ወዲህ የዚህን ዓለም ገዥ ወደ ውጭ አስወጥተው ይሰዱታል።'),
  ('616bd85d-6401-5b93-a10b-e1e823c60b39', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 13, 32, 'እኔም ከምድር ከፍ ከፍ ካልሁ ሁሉን ወደ እኔ እስባለሁ።”'),
  ('97b8e2ae-9a43-5907-a893-b090fc62ef1c', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 14, 33, 'ይህንም ያለ በምን ዐይነት ሞት ይሞት ዘንድ እንዳለው ሲያመለክታቸው ነው።'),
  ('321b73f1-c601-50bf-ab79-893f163372f9', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 15, 34, 'ሕዝቡም፥ “እኛስ ክርስቶስ ለዘለዓለም እንዲኖር በኦሪት ሰምተን ነበር፤ እንግዲህ እንዴት አንተ ‘የሰው ልጅ ከፍ ከፍ ይል ዘንድ አለው’ ትለናለህ? እንግዲህ ይህ የሰው ልጅ ማን ነው?” ብለው መለሱለት።'),
  ('1abf8af2-eefe-5747-a1a6-90f288fc0231', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 16, 35, 'ጌታችን ኢየሱስም እንዲህ አላቸው፥ “ ገና ለጥቂት ጊዜ ብርሃን ከእናንተ ጋር ነው፤ በጨለማ የሚመላለስ የሚሄድበትን አያውቅምና ጨለማ እንዳያገኛችሁ ብርሃን ሳለላችሁ ተመላለሱ፤'),
  ('cf9a7a60-70b5-51e2-a3ab-bb6fa85b79fc', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 17, 36, 'የብርሃን ልጆች ትሆኑ ዘንድ ብርሃን ሳለላችሁ በብርሃን እመኑ” ጌታችን ኢየሱስም ይህን ተናግሮ ሄደ፤ ተሰወራቸውም።'),
  ('75d46eba-493d-538a-a3d6-52cbbc2b10be', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 18, 37, 'ይህንም ያህል ተአምራት በፊታቸው ሲያደርግ አላመኑበትም።'),
  ('45c7c9da-4ac7-57da-a28d-698cf3cfb351', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 19, 38, '“አቤቱ፥ ምስክርነታችንን ማን ያምነናል? የእግዚአብሔርስ ክንድ ለማን ተገለጠ?” ያለው የነቢዩ የኢሳይያስ ቃል ይደርስ ዘንድ።'),
  ('2cf9a4b5-25ba-59b4-a704-f5b7aab26d30', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 20, 39, 'ስለዚህም ማመን ተሳናቸው፤ ኢሳይያስ ዳግመኛ እንዲህ ብሎአልና።'),
  ('bce2346b-633d-566b-ac65-87e40e4f16cd', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 21, 40, '“በዐይናቸው አይተው፥ በልባቸውም አስተውለው እንዳይመለሱና እንዳልፈውሳቸው ዐይኖቻቸው ታወሩ፤ ልባቸውም ደነደነ።”'),
  ('0542edf0-3f0e-5020-aaaf-dd882b0c4ad7', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 22, 41, 'ኢሳይያስ ጌትነቱን አይቶአልና፥ ይህን ተናገረ፤ ስለ እርሱም መሰከረ።'),
  ('c424b262-d5af-5064-ac9e-454c83a10f4a', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 23, 42, 'ከሕዝቡ አለቆችም ያመኑበት ብዙዎች ነበሩ፤ ነገር ግን ከምኵራብ አስወጥተው እንዳይሰዱአቸው በፈሪሳውያን ምክንያት አልመሰከሩለትም።'),
  ('41d6445c-ff14-56d6-ae2e-397edf249887', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 24, 43, 'ከእግዚአብሔር ክብር ይልቅ የሰውን ክብር ወደዋልና።'),
  ('51b502eb-8afb-5526-a436-10e03d9b3808', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 25, 44, 'ጌታችን ኢየሱስም ድምፁን ከፍ አድርጎ እንዲህ አለ፥ “በእኔ የሚያምን በላከኝም ነው እንጂ በእኔ ብቻ የሚያምን አይደለም።'),
  ('11529eab-a049-53ba-abc1-793c35455a4c', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 26, 45, 'እኔን ያየ የላከኝን አየ።'),
  ('5139a2c0-3fd1-52bc-a207-4e43b33d0eae', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 27, 46, 'በእኔ የሚያምን ሁሉ በጨለማ እንዳይኖር ብርሃን እኔ ወደ ዓለም መጣሁ።'),
  ('32c0e0e7-f870-5333-abef-cc9dba8c0bc5', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 28, 47, 'ቃሌን ሰምቶ የማይጠብቀውን እኔ የምፈርድበት አይደለሁም፤ ዓለምን ላድን እንጂ በዓለም ልፈርድበት አልመጣሁምና።'),
  ('eeb8484b-c42b-525e-acf7-af0deaa2f96f', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 29, 48, 'የሚክደኝን፥ ቃሌንም የማይቀበለውን ግን የሚፈርድበት አለ፤ እኔ የተናገርሁት ቃል እርሱ በመጨረሻዪቱ ቀን ይፈርድበታል።'),
  ('06dc9c33-19fb-53b8-a6da-43786ad4d880', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 30, 49, 'የተናገርሁት ከእኔ የሆነ አይደለምና፤ ነገር ግን የላከኝ አብ እንድናገር፥ እንዲህም እንድል እርሱ ትእዛዝን ሰጠኝ።'),
  ('804c2884-ee8b-523c-af28-5b8d1778364d', '67f220c5-3d8e-52b3-a1c8-f32d1f51587c', 'd8e84fa4-dd96-5fc1-a09b-7eed2078bfc1', 31, 50, 'ትእዛዙም የዘለዓለም ሕይወት እንደ ሆነ አውቃለሁ፤ እኔም የምናገረውን አብ እንዳለኝ እንዲሁ እናገራለሁ።”'),
  ('5bc002c8-5b27-51c9-aaa3-0999c708a2fc', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 1, 1, 'ከፋሲካ በዓል አስቀድሞ ጌታችን ኢየሱስ ከዚህ ዓለም ወደ ላከው ወደ አብ ይሄድ ዘንድ ጊዜው እንደ ደረሰ ባወቀ ጊዜ በዓለም ያሉትን የወደዳቸውን ወገኖቹን ፈጽሞ ወደዳቸው።'),
  ('a3273d2d-7625-5e23-a456-c949cf9f4dff', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 2, 2, 'ራት ሲበሉም አሳልፎ ይሰጠው ዘንድ በስምዖን ልጅ በአስቆሮቱ ሰው በይሁዳ ልብ ሰይጣን አደረ።'),
  ('18363849-bc61-5cfe-aeee-fdce1bb07309', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 3, 3, 'ጌታችን ኢየሱስም፥ አብ ሁሉን በእጁ እንደ ሰጠው፥ ከእግዚአብሔር እንደ ወጣ፥ ወደ እግዚአብሔርም እንደሚሄድ ባወቀ ጊዜ፥'),
  ('e79615d3-e0ec-5f86-a824-d03d89a83c6d', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 4, 4, 'ራት ከሚበሉበት ተነሥቶ ልብሱን አኖረና ማበሻ ጨርቅ አንሥቶ ወገቡን ታጠቀ።'),
  ('bd34ceec-7863-57d5-ad14-619f6f7dbaca', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 5, 5, 'በኵስኵስቱም ውኃ ቀድቶ የደቀ መዛሙርቱን እግር ያጥብ ጀመር፤ በዚያ በታጠቀው ማበሻ ጨርቅም አበሰ።'),
  ('868dc3c9-f417-5952-adee-74f2c46d726d', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 6, 6, 'ወደ ስምዖን ጴጥሮስም ደረሰ፤ እርሱም፥ “አቤቱ፥ አንተ እግሬን ታጥበኛለህን?” አለው።'),
  ('c5eb6a65-5417-58a8-aecc-089423357561', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 7, 7, 'ጌታችን ኢየሱስም፥ “እኔ የምሠራውን አንተ ዛሬ አታውቅም፤ ኋላ ግን ታስተውለዋለህ” ብሎ መለሰለት።'),
  ('95796458-a9b4-5fbe-a202-1337c26c5ce1', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 8, 8, 'ጴጥሮስም፥ “መቼም ቢሆን አንተ እግሬን አታጥበኝም” አለው፤ ጌታችን ኢየሱስም፥ “እውነት እውነት እልሃለሁ፤ እኔ እግርህን ካላጠብሁህ ከእኔ ጋር ዕድል ፋንታ የለህም” ብሎ መለሰለት።'),
  ('045dde8f-00f5-5ad3-a824-4ccd6a8ddc81', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 9, 9, 'ስምዖን ጴጥሮስም፥ “አቤቱ፥ እንኪያስ የምታጥበኝ እጆችንና ራሴንም እንጂ እግሮችን ብቻ አይደለም፤” አለው።'),
  ('22764c69-ab5f-58ec-afa7-3bda6e45b3e3', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 10, 10, 'ጌታችን ኢየሱስም፥ “ፈጽሞ የታጠበ ከእግሩ በቀር ሊታጠብ አያስፈልገውም፤ ሁለንተናው ንጹሕ ነውና፤ እናንተማ ንጹሓን ናችሁ፤ ነገር ግን ሁላችሁ አይደላችሁም” አለው።'),
  ('47c24ce7-195c-5319-afa5-ed97325c057a', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '0245f62c-3a07-5ad8-a7ed-cd382ed4d2a8', 11, 11, 'ጌታችን ኢየሱስም አሳልፎ የሚሰጠውን ያውቅ ነበርና ስለዚህ “ሁላችሁ ንጹሓን አይደላችሁም” አለ።'),
  ('fbc0c3d8-cf3a-59e7-abac-e33c828a24e0', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 1, 12, 'እግራቸውንም ካጠባቸው በኋላ ልብሱን አንሥቶ ለበሰና እንደ ገና ከእነርሱ ጋር ተቀመጠ፤ እንዲህም አላቸው፥ “ያደረግሁላችሁን ዐወቃችሁን?'),
  ('0f12e5f5-affd-5a15-ae75-fe337d723a86', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 2, 13, 'እናንተ ‘መምህራችን፥ ጌታችንም’ ትሉኛላችሁ፤ መልካም ትላላችሁ፤ እኔ እንዲሁ ነኝና።'),
  ('212baa7a-0039-5739-a460-dffd6ad7300d', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 3, 14, 'እንግዲህ እኔ መምህራችሁና ጌታችሁ ስሆን እግራችሁን ካጠብኋችሁ እናንተም እንዲሁ የባልጀሮቻችሁን እግር ልታጥቡ ይገባችኋል።'),
  ('aecd5cb0-657b-5ee0-a1b2-f754fa9255cb', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 4, 15, 'እኔ እንደ አደረግሁላችሁ እናንተም ልታደርጉ ምሳሌ ሰጥቻችኋለሁና።'),
  ('8cd4e5cf-dd19-5189-a15e-360abd4cdae9', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 5, 16, 'እውነት እውነት እላችኋለሁ፤ ከጌታው የሚበልጥ አገልጋይ የለም፤ ከላከው የሚበልጥ መልእክተኛም የለም።'),
  ('752a7d8b-9f88-5127-aba7-5439ec7e394a', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 6, 17, 'ይህንም ዐውቃችሁ ብትሠሩ ብፁዓን ናችሁ።'),
  ('65dd1176-5277-57b1-a1b3-f90441dbca84', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 7, 18, 'ነገር ግን ይህን የምናገር ስለ ሁላችሁ አይደለም፤ የመረጥኋቸው እነማን እንደ ሆኑ እኔ አውቃለሁ፤ ነገር ግን መጽሐፍ ‘እንጀራዬን የሚመገብ ተረከዙን በእኔ ላይ አነሣ’ ያለው ይፈጸም ዘንድ ነው።'),
  ('a6167653-8e95-52a0-a0a1-33eebe52d9b5', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 8, 19, 'በሆነም ጊዜ እኔ እንደ ሆንሁ ታምኑ ዘንድ ከዛሬ ጀምሮ ከመሆኑ አስቀድሞ እነግራችኋለሁ።'),
  ('a0f32f75-b4fa-5bba-ae40-4a35bb8b8337', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '429c9440-9d56-551e-a3cd-d9c0dae37b54', 9, 20, 'እውነት እውነት እላችኋለሁ፤ እኔ የምልከውን የሚቀበል እኔን ይቀበላል፤ እኔንም የሚቀበል የላከኝን ይቀበላል።”'),
  ('725259e5-e52f-5f6e-a118-6cbcd2a25e18', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 1, 21, 'ይህንም ተናግሮ ጌታችን ኢየሱስ በልቡ አዘነ፤ መሰከረ፤ እንዲህም አለ፥ “እውነት እውነት እላችኋለሁ፤ ከእናንተ አንዱ አሳልፎ ይሰጠኛል።”'),
  ('6402044b-992a-5c89-a90e-9a9828521238', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 2, 22, 'ደቀ መዛሙርቱም ይህን ስለ ማን እንደ ተናገረ ተጠራጥረው እርስ በርሳቸው ተያዩ፤'),
  ('ba994aeb-fa6d-5741-ae90-5e0c876a2e4e', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 3, 23, 'ጌታችን ኢየሱስም ይወደው የነበረ ከደቀ መዛሙርቱ አንዱ በጌታችን ኢየሱስ አጠገብ ተቀምጦ ነበር።'),
  ('faa07960-947a-5360-a130-cf774c90051e', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 4, 24, 'ስምዖን ጴጥሮስም እርሱን ጠቀሰና፥ “ይህን ስለ ማን እንደ ተናገረ ጠይቀህ ንገረን” አለው።'),
  ('d7cc5652-db68-50ac-a572-aac1882f95cc', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 5, 25, 'ያም ደቀ መዝሙር በጌታችን ኢየሱስ አጠገብ ቀረብ ብሎ፥ “ጌታ ሆይ፥ እርሱ ማነው?” አለው።'),
  ('5ad1d38b-4ea4-524a-a9c7-94d107d05abc', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 6, 26, 'ጌታችን ኢየሱስም መልሶ፥ “ይህ እኔ እንጀራ በወጥ አጥቅሼ የምሰጠው ነው” አለው፤ ያን ጊዜም እንጀራ በወጥ አጥቅሶ ለስምዖን ልጅ ለአስቆሮታዊው ይሁዳ ሰጠው።'),
  ('4034b016-cf63-572c-ace4-31d5fcc3b27c', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 7, 27, 'እንጀራውንም ከተቀበለ በኋላ ወዲያውኑ በይሁዳ ልብ ሰይጣን አደረበት፤ ጌታችን ኢየሱስም፥ “እንግዲህ የምታደርገውን ፈጥነህ አድርግ” አለው።'),
  ('dd4225b6-7bb5-5d09-a13e-bde9d995e8c5', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 8, 28, 'አብረውትም በማዕድ የተቀመጡት ስለ ምን ይህን እንዳለው አላወቁም።'),
  ('cde865b4-f94a-58e7-a7d5-87b14cf00f9c', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 9, 29, 'ሙዳየ ምጽዋቱ በይሁዳ ዘንድ ነበረና፥ ለበዓል የምንሻውን ወይም ለነዳያን የምንሰጠውን ግዛ ያለው የመሰላቸው ነበሩ።'),
  ('d14da018-abd9-528c-a0a4-d838092b2065', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'c55690cb-86c5-5965-a4f6-791db4bdb4aa', 10, 30, 'ይሁዳም ያን እንጀራ ተቀብሎ ወዲያውኑ ወጣ፥ ሌሊትም ነበር።።'),
  ('7562b81f-157a-599b-afea-e46816683b4f', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'f5070720-bb26-53f5-a8e3-cd32138a7a95', 1, 31, 'ይሁዳም ከወጣ በኋላ ያንጊዜ ጌታችን ኢየሱስ እንዲህ አላቸው፥ “አሁን የሰው ልጅ ከበረ፤ እግዚአብሔርም በእርሱ ከበረ።'),
  ('6cfd86b0-b498-5e66-ac66-e087dd796dda', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'f5070720-bb26-53f5-a8e3-cd32138a7a95', 2, 32, 'እግዚአብሔር በእርሱ ከከበረ እግዚአብሔርም እርሱን ያከብረዋል፥ ያንጊዜም ያከብረዋል።'),
  ('d53ee791-89da-5707-ab1c-be13e9c45c40', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'f5070720-bb26-53f5-a8e3-cd32138a7a95', 3, 33, 'ልጆች ሆይ፥ ገና ጥቂት ጊዜ ከእናንተ ጋር አለሁ፤ ትሹኛላችሁ፤ ለአይሁድም እኔ ወደምሄድበት እናንተ መምጣት አይቻላችሁም እንዳልኋቸው፥ አሁንም ለእናንተ እነግራችኋለሁ።'),
  ('de9d835a-ac10-5733-a1a9-5a8cfdc0ffc7', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'b9f74d4f-ce3e-5b97-ae46-678b692bad38', 1, 34, '“እርስ በርሳችሁ ቷደዱ ዘንድ፥ አዲስ ትእዛዝ እሰጣችኋለሁ፤ እኔ እንደ ወደድኋችሁ እናንተም እንዲሁ እርስ በርሳችሁ ተዋደዱ።'),
  ('540fc386-56c3-5c82-a17e-cf20586d9c39', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', 'b9f74d4f-ce3e-5b97-ae46-678b692bad38', 2, 35, 'እርስ በርሳችሁም ብቷደዱ፥ የእኔ ደቀ መዛሙርት እንደ ሆናችሁ በዚህ ሁሉ ያውቋችኋል።”'),
  ('c926737f-be7c-5465-af10-716d60097c58', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '5d9329c0-a716-54e8-a361-e80480bac6e0', 1, 36, 'ስምዖን ጴጥሮስም፥ “ጌታ ሆይ፥ ወዴት ትሄዳለህ?” አለው፤ ጌታችን ኢየሱስም መልሶ፥ “ወደምሄድበት አሁን ልትከተለኝ አትችልም፤ ኋላ ግን ትከተለኛለህ” አለው።'),
  ('062d439c-34d6-560d-a7a2-fc3d98c1c4b9', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '5d9329c0-a716-54e8-a361-e80480bac6e0', 2, 37, 'ጴጥሮስም፥ “ጌታ ሆይ፥ ስለ ምን አሁን ልከተልህ አልችልም? እኔ ነፍሴንም እንኳ ቢሆን ስለ አንተ አሳልፌ እሰጣለሁ” አለው።'),
  ('26430744-5b46-5d9e-a28f-7a0131702763', 'ab1ffb3e-9383-5d21-a706-08aa746f07b8', '5d9329c0-a716-54e8-a361-e80480bac6e0', 3, 38, 'ጌታችን ኢየሱስም መልሶ እንዲህ አለው፤ “ነፍስህን ስለ እኔ አሳልፈህ ትሰጣለህን? እውነት እውነት እልሃለሁ፤ ሦስት ጊዜ እስክትክደኝ ዶሮ አይጮህም።'),
  ('2f89ac83-fb6a-5730-a502-0fb23ecc518c', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 1, 1, '“ልባችሁ አይደንግጥ፤ በእግዚአብሔር እመኑ፤ በእኔም እመኑ።'),
  ('222a2b7e-e4dc-51a9-ac7f-77ab1d52a696', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 2, 2, 'በአባቴ ቤት ብዙ ማደሪያና ማረፊያ አለ፤ እንዲህስ ባይሆን ኖሮ ቦታ ላዘጋጅላችሁ እሄዳለሁ እላችሁ ነበር።'),
  ('155ccc27-e417-5191-abf5-902b3514f77a', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 3, 3, 'ከሄድሁና ቦታ ካዘጋጀሁላችሁም ዳግመኛ እመጣለሁ፤ እናንተም እኔ በአለሁበት ትኖሩ ዘንድ ወደ እኔ እወስዳችኋለሁ።'),
  ('d6d4ecf5-8e7c-58b0-a11d-f899e38f9564', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 4, 4, 'ወዴትም እንደምሄድ ራሳችሁ ታውቃላችሁ፤ መንገዱንም ታውቃላችሁ።”'),
  ('4203b592-0433-5857-afca-cd143c93f35d', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 5, 5, 'ቶማስም፥ “ጌታዬ ሆይ፥ የምትሄድበትን የማናውቅ እንግዲህ መንገዱን እንዴት እናውቃለን?” አለው።'),
  ('71009084-dd3f-5c2b-ad75-cb728e525c02', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 6, 6, 'ጌታችን ኢየሱስም እንዲህ አለው፥ “የእውነትና የሕይወት መንገድ እኔ ነኝ፤ በእኔ በኩል ካልሆነ በቀር ወደ አብ የሚመጣ የለም።'),
  ('d88e2a1e-cad6-59dc-a5b3-f901acc5c4cd', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 7, 7, 'እኔንስ ብታውቁኝ አባቴንም ባወቃችሁት ነበር፤ ከእንግዲህ ወዲህ ግን አውቃችሁታል፤ አይታችሁትማል።”'),
  ('624df5b9-5e4c-50c3-a29b-5a746b6187f0', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 8, 8, 'ፊልጶስም፥ “ጌታ ሆይ፥ አብን አሳየንና ይበቃናል” አለው።'),
  ('4042a1b1-ea03-578c-ae63-2265512de387', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 9, 9, 'ጌታችን ኢየሱስም እንዲህ አለው፥ “ፊልጶስ፥ ይህን ያህል ዘመን አብሬአችሁ ስኖር አታወቀኝምን? እኔን ያየ አብን አየ፤ እንግዲህ እንዴት አብን አሳየን ትላለህ?'),
  ('b2def489-7551-58b8-adf0-c156da913042', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 10, 10, 'እኔ በአብ እንዳለሁ አብም በእኔ እንዳለ አታምንምን? እኔ የምነግራችሁ ይህ ቃልም ከራሴ የተናገርሁት አይደለም፤ በእኔ ያለ አብ እርሱ ይህን ሥራ ይሠራዋል እንጂ።'),
  ('80c8209b-e63b-5167-afcf-5956c243a26e', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 11, 11, 'እኔ በአብ እንዳለሁ፥ አብም በእኔ እንዳለ እመኑ፤ ያለዚያም ስለ ሥራዬ እመኑኝ።'),
  ('287b5c88-e810-54b7-a765-68aa025b167f', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 12, 12, '“እውነት እውነት እላችኋለሁ፤ በእኔ የሚያምን እኔ የምሠራውን ሥራ እርሱም ይሠራል፤ ከዚያም የሚበልጥ ይሠራል፤ እኔ ወደ አብ እሄዳለሁና።'),
  ('4a31ccd2-a5ca-53a9-af86-0dae0f17c568', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 13, 13, 'አብ በወልድ ይከብር ዘንድ በስሜ የምትለምኑትን ሁሉ አደርግላችኋለሁ።'),
  ('2e252347-0f0f-5ca5-ad65-962464efdb40', '6db748e3-7531-57ac-a1e6-a2262e63ca54', 'a22912ab-5eca-5521-a709-1703469fdc78', 14, 14, 'በስሜ የምትለምኑት ነገር ቢኖር ያን አደርግላችኋለሁ።'),
  ('e30b62b0-c2db-5446-a72b-9ddd7cd22dff', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 1, 15, '“ከወደዳችሁኝስ ትእዛዜን ጠብቁ።'),
  ('563be09e-4245-50bc-ad7c-19e2424eed93', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 2, 16, 'እኔም አብን እለምነዋለሁ፤ እርሱም ለዘለዓለም ከእናንተ ጋር ይኖር ዘንድ ሌላ አጽናኝ ይልክላችኋል።'),
  ('3f92b038-c0a5-546c-acfb-18d74da55ac9', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 3, 17, 'እርሱም ዓለም ስለማያየውና ስለማያውቀው ሊቀበለው የማይቻለው የእውነት መንፈስ ነው፤ እናንተ ግን ታውቁታላችሁ፤ በእናንተ ዘንድ ይኖራልና፤ ያድርባችሁማልና።'),
  ('78d90c69-2895-53ce-a4bd-e24401b1ca96', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 4, 18, '“የሙት ልጆች ትሆኑ ዘንድ አልተዋችሁም፤ ወደ እናንተ እመጣለሁ።'),
  ('1d436e04-ff2e-598f-ab69-ff3025c48c42', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 5, 19, 'ገና ጥቂት ጊዜ አለ፤ እንግዲህ ወዲህም ዓለም አያየኝም፤ እናንተ ግን ታዩኛላችሁ፤ እኔ ሕያው ነኝና፤ እናንተም ሕያዋን ትሆናላችሁ።'),
  ('ce85b28e-4b4b-555f-a4a2-1f64235a03db', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 6, 20, 'እኔ በአብ እንዳለሁ፥ አብም በእኔ እንዳለ፥ እናንተም በእኔ፥ እኔም በእናንተ እንዳለሁ ያንጊዜ ታውቃላችሁ።'),
  ('4d4a3762-7221-5995-a50f-bc6560d63d60', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 7, 21, 'ትእዛዜ በእርሱ ዘንድ ያለ የሚጠብቀውም የሚወደኝ እርሱ ነው፤ የሚወደኝንም አባቴ ይወደዋል፤ እኔም እወደዋለሁ፤ ራሴንም እገልጥለታለሁ።”'),
  ('b1da2140-2f13-5f4e-af41-7d2ab6c6c8c6', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 8, 22, 'የአስቆሮቱ ሰው ያይደለ ይሁዳም፥ “ጌታ ሆይ፥ ለዓለም ያይደለ ለእኛ ራስህን ትገልጥ ዘንድ እንዳለህ የተናገርኸው ምንድን ነው?” አለው።'),
  ('c183db41-ed38-58c7-acf5-23a616a807d0', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 9, 23, 'ጌታችን ኢየሱስም መልሶ አለው፥ “የሚወደኝ ቃሌን ይጠብቃል፤ አባቴም ይወደዋል፤ ወደ እርሱም መጥተን በእርሱ ዘንድ ማደሪያ እናደርጋለን።'),
  ('698dab89-5e33-5ee6-a71b-be2ab0cb4afc', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 10, 24, 'የማይወደኝ ግን ቃሌን አይጠብቅም፤ ይህም የምትሰሙት ቃል የላከኝ የአብ ቃል ነው እንጂ የእኔ ቃል አይደለም።'),
  ('e5aa0f2b-5bfa-5bc6-aef1-6c466a4a87c8', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 11, 25, '“ከእናንተም ጋር ሳለሁ ይህን ነገርኋችሁ።'),
  ('46c455be-f8ca-52ad-abd8-b95bb302c095', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '4a11da74-4c17-5bb6-a7ec-da961cfc64a3', 12, 26, 'ነገር ግን አብ በስሜ የሚልከው የእውነት መንፈስ ጰራቅሊጦስ እርሱ ሁሉን ያስተምራችኋል፤ እኔ የነገርኋችሁንም ሁሉ ያሳስባችኋል።'),
  ('09c9a817-af43-55ff-a263-981c08f98442', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '56f46640-0620-5a6b-a689-f999b4c2fc3a', 1, 27, '“ሰላምን እተውላችኋለሁ፥ ሰላሜንም እሰጣችኋለሁ፤ እኔ የምሰጣችሁ ዓለም እንደሚሰጠው አይደለም፤ ልባችሁ አይደንግጥ፤ አትፍሩም።'),
  ('3b140c8f-a7e4-5e4e-a488-2910658484a9', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '56f46640-0620-5a6b-a689-f999b4c2fc3a', 2, 28, 'እኔ እንደምሄድ ወደ እናንተም እንደምመለስ የነገርኋችሁን ሰምታችኋል፤ ብትወዱኝስ ወደ አብ በመሄዴ ደስ ባላችሁ ነበር፤ እርሱ አብ ይበልጠኛልና።'),
  ('55b06cab-09e4-5bf1-a93e-611e13359eaf', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '56f46640-0620-5a6b-a689-f999b4c2fc3a', 3, 29, 'አሁንም ይህ በሆነ ጊዜ ታምኑ ዘንድ አስቀድሜ ሳይሆን ነገርኋችሁ።'),
  ('4faa9325-e063-5610-a7b5-13c8d0c12cdf', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '56f46640-0620-5a6b-a689-f999b4c2fc3a', 4, 30, 'እንግዲህ ወዲህ ከእናንተ ጋር ብዙ አልናገርም፤ የዚህ ዓለም ገዢ ይመጣልና፤ በእኔም ላይ ምንም አያገኝም።'),
  ('4ed26f25-da08-57fa-a2ee-b76d0b000ec5', '6db748e3-7531-57ac-a1e6-a2262e63ca54', '56f46640-0620-5a6b-a689-f999b4c2fc3a', 5, 31, 'ነገር ግን አብን እንደምወደው ዓለም ያውቅ ዘንድ አብ ትእዛዙን እንደ ሰጠኝ እንዲሁ አደርጋለሁ፤ ተነሡ ከዚህ፤ እንሂድ።'),
  ('f2062271-3ffe-5152-ac7e-9cd6ce72d3f9', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 1, 1, '“እውነተኛ የወይን ሐረግ እኔ ነኝ፤ ተካዩም አባቴ ነው።'),
  ('e84083d3-428a-5417-a749-31e52a5e345d', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 2, 2, 'በእኔ ያለውን፥ ፍሬ የማያፈራውን ቅርንጫፍም ሁሉ ያስወግደዋል፤ የሚያፈራውን ቅርንጫፍ ሁሉ ግን በብዙ እንዲያፈራ ያጠራዋል።'),
  ('1805da7d-2cdc-502b-a7b0-7a8048c79b0d', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 3, 3, 'እናንተ ግን ስለ ነገርኋችሁ ቃል ፈጽማችሁ ንጹሓን ናችሁ።'),
  ('dd704735-1c86-5918-ac8e-6c868c62a9a0', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 4, 4, 'በእኔ ኑሩ፤ እኔም በእናንተ፤ ቅርንጫፍ በወይኑ ግንድ ከአልኖረ ብቻውን ሊያፈራ እንደማይችል እናንተም እንዲሁ በእኔ ካልኖራችሁ ፍሬ ማፍራት አትችሉም።'),
  ('bd8543ee-0656-5285-a723-ebdc646d6504', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 5, 5, 'እኔ የወይን ግንድ ነኝ፤ ቅርንጫፎቹም እናንተ ናችሁ፤ በእኔ የሚኖር እኔም በእርሱ፥ ብዙ ፍሬ የሚያፈራ እርሱ ነው፤ ያለ እኔ ምንም ማድረግ አትችሉምና።'),
  ('27059e69-d11e-597f-a7a3-f14be1e035a5', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 6, 6, 'በእኔ የማይኖር ቢኖር እንደ ደረቅ ቅርንጫፍ ወደ ውጭ ይጥሉታል፤ ሰብስበውም በእሳት ያቃጥሉታል።'),
  ('a106afb4-e521-5979-a6fe-895f078a4cbb', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 7, 7, 'በእኔም ብትኖሩ ቃሌም በእናንተ ቢኖር የምትሹትን ሁሉ ትለምናላችሁ፤ ይደረግላችሁማል።'),
  ('a18b032f-5f97-5bdb-aac3-957e2092fbaa', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 8, 8, 'ብዙ ፍሬ ብታፈሩ፥ ደቀ መዛሙርቴም ብትሆኑ በዚህ አባቴ ይከበራል።'),
  ('b35c7818-3432-5ec2-ae0a-3e869778cb02', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 9, 9, 'አብ እንደ ወደደኝ እንዲሁ ወደድኋችሁ፤ በፍቅሬም ኑሩ።'),
  ('67717938-84dc-5f8f-afa8-bd3a089523c2', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 10, 10, 'የምትወዱኝ ብትሆኑ ትእዛዜን ጠብቁ፤ እኔ የአባቴን ትእዛዝ እንደ ጠበቅሁ፥ በፍቅሩም እንደምኖር እናንተም ትእዛዜን ብትጠብቁ በፍቅሬ ትኖራላችሁ።'),
  ('33ebd4aa-d776-5a73-ad76-fd6f10f3eeef', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 11, 11, 'ደስታዬ በእናንተ ይኖር ዘንድ፥ ደስታችሁም ፍጹም ይሆን ዘንድ ይህን ነገርኋችሁ።'),
  ('278bbec1-1087-56d0-aa2b-64d2a7070d50', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 12, 12, '“እኔ እንደ ወደድኋችሁ እርስ በርሳችሁ እንድቷደዱ የእኔ ትእዛዝ ይህች ናት።'),
  ('d61d8b65-2787-5d55-afa0-586224035bb1', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 13, 13, 'ስለ ወዳጆቹ ሕይወቱን አሳልፎ የሚሰጥ ሰው ያለ እንደ ሆነ ከዚህ የሚበልጥ ፍቅር የለም።'),
  ('8fcc6a3d-782b-51ad-a379-c722f115462b', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 14, 14, 'እናንተስ ያዘዝኋችሁን ሁሉ ካደረጋችሁ ወዳጆች ናችሁ።'),
  ('67d9e622-84f2-50e8-a336-3b41ef480782', 'acd37d09-efd3-59ce-aaba-188a44ba1cc4', '7107bcfa-2481-5e46-a703-490c129b3f4f', 15, 15, 'እንግዲህ ወዲህ ባሮች አልላችሁም፤ ባሪያ ጌታው የሚያደርገውን አያውቅምና፤ እናንተን ግን ወዳጆች እላችኋለሁ፤ በአባቴ ዘንድ የሰማሁትን ሁሉ ነግሬአችኋለሁና።')
